INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "字面就是指一个词或一句话，最直接、最表面的意思，不往深里想。", "primary_collocate": null, "pronunciation": "zì miàn", "ipa": "tsɿ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "“开门见山”的字面意思是打开门看山。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话的字面不难，但意思很深。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，别只看字面意思。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从字面上理解，他是在夸我。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的字面和实际用法不一样。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子只听懂了字面意思，没有想别的。", "target_word": "字面", "complexity_tier": "T3", "furigana": "hái zi zhǐ tīng dǒng le zì miàn yì sī, méi yǒu xiǎng bié de.", "sentence_source": "generated"}, {"text": "请按字面意思回答这个问题。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜名按字面意思听很好笑。", "target_word": "字面", "complexity_tier": "T3", "furigana": "zhè ge cài míng àn zì miàn yì sī tīng hěn hǎo xiào.", "sentence_source": "generated"}, {"text": "他的话不能只从字面去理解。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "字面上看，这个办法很简单。", "target_word": "字面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "字面上", "label": "复合"}, {"form": "字面意思", "label": "复合"}, {"form": "字面意义", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个词或一句话最直接、最表面的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "字面", "is_correct": true, "explanation": "字面：指成语的直接字义，与“意思”搭配，句意通顺。"}, {"text": "出处", "is_correct": false, "explanation": "语义：出处指来源，不是成语的直接意思。"}, {"text": "读音", "is_correct": false, "explanation": "语义：读音指发音，与“意思”无关。"}, {"text": "笔画", "is_correct": false, "explanation": "搭配：“意思”不接笔画，笔画不能说明成语的意义。"}], "explanations": {"字面": "字面：指成语的直接字义，与“意思”搭配，句意通顺。", "出处": "语义：出处指来源，不是成语的直接意思。", "读音": "语义：读音指发音，与“意思”无关。", "笔画": "搭配：“意思”不接笔画，笔画不能说明成语的意义。"}, "sentence_index": 0, "correct_answer": "字面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字面很平静，心里却很紧张。", "explanation": "这里应该用〈表面〉。字面指词句的意思，描写人的外表应说“表面”。"}, {"text": "这篇文章的字面写得很工整。", "explanation": "这里应该用〈字迹〉。字面指意思，不指写字的样子。"}, {"text": "这块布的字面很软，穿着很舒服。", "explanation": "这里应该用〈质地〉。字面指词句的意思，不指布料的软硬；形容布料柔软，应说“质地很软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字面", "is_correct": true, "explanation": "字面：指问题的直接意思，与“按……意思回答”搭配，句意通顺。"}, {"text": "声调", "is_correct": false, "explanation": "语义：声调指发音高低，不能按声调回答问题。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“按……意思”后不接颜色。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状与回答问题无关，句意荒谬。"}], "explanations": {"字面": "字面：指问题的直接意思，与“按……意思回答”搭配，句意通顺。", "声调": "语义：声调指发音高低，不能按声调回答问题。", "颜色": "搭配：“按……意思”后不接颜色。", "形状": "语义：形状与回答问题无关，句意荒谬。"}, "sentence_index": 6, "correct_answer": "字面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的字面很高，大家都尊敬他。", "explanation": "这里应该用〈地位〉。字面指词句的意思，不能用来形容人的高低。"}, {"text": "这本书的字面有三百页。", "explanation": "这里应该用〈页数〉。字面指意思，不指页数。"}, {"text": "他把水果的字面削干净了。", "explanation": "这里应该用〈皮〉。字面指词句的意思，不指水果的表皮；削水果应说“削皮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个词的字面意思了很好懂。", "corrected_sentence": "这个词的字面意思很好懂。", "error_description": "“了”不能接在名词短语“字面意思”后面，应删去，写作“字面意思很好懂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个成语的这字面意思和它的引申义不一样。", "corrected_sentence": "这个成语的字面意思和它的引申义不一样。", "error_description": "“的”已修饰“字面意思”，不能再加指示词“这”；应写作“这个成语的字面意思”，去掉“这”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
