INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数据保护就是不让别人拿走或弄坏我们的信息。", "primary_collocate": null, "pronunciation": "shù jù bǎo hù", "ipa": "ʂu˥˩ tɕy˥˩ pɑʊ˨˩˦ xu˥˩", "syllable_count": 4, "sentences": [{"text": "数据保护就是防止别人拿走或弄坏你的文件。", "target_word": "数据保护", "complexity_tier": "T3", "furigana": "shù jù bǎo hù", "sentence_source": "generated"}, {"text": "手机需要数据保护，不然照片会丢。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么做数据保护。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据保护做得好，坏人就拿不走我们的信息。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了数据保护，我给电脑设了一个新密码。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以帮你做数据保护。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不懂数据保护，坏人拿走了他的文件。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有数据保护的规定。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的电脑坏了，幸好有数据保护，资料还在。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生也应该学习数据保护。", "target_word": "数据保护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "数据保护法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "不让别人拿走或弄坏自己的信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "数据保护", "is_correct": true, "explanation": "数据保护：指防止文件被拿走或弄坏，与句意相符。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育与防止文件被拿走或弄坏无关，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型外貌，不能用来说防止文件被拿走。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜不能被说成防止文件被拿走或弄坏的做法。"}], "explanations": {"数据保护": "数据保护：指防止文件被拿走或弄坏，与句意相符。", "体育": "语义：体育与防止文件被拿走或弄坏无关，句子不通。", "身材": "体貌：“身材”指人的体型外貌，不能用来说防止文件被拿走。", "衣柜": "语义：衣柜不能被说成防止文件被拿走或弄坏的做法。"}, "sentence_index": 0, "correct_answer": "数据保护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给电脑装了一台数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈台〉用于机器设备，数据保护是抽象的功能，不能用〈台〉计量。"}, {"text": "我给手机买了一只数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈只〉用于动物或成对的东西，数据保护不能用〈只〉计量。"}, {"text": "我给文件装了一把数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈把〉用于有柄的东西，数据保护不能用〈把〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "数据保护", "is_correct": true, "explanation": "数据保护：他不懂数据保护，所以坏人能拿走文件，句意连贯。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法与文件被拿走之间没有逻辑关系。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“不懂衣服”不是常用搭配，句子不通。"}, {"text": "歌剧", "is_correct": false, "explanation": "语义：歌剧与文件被拿走之间没有逻辑关系。"}], "explanations": {"数据保护": "数据保护：他不懂数据保护，所以坏人能拿走文件，句意连贯。", "书法": "语义：书法与文件被拿走之间没有逻辑关系。", "衣服": "搭配：“不懂衣服”不是常用搭配，句子不通。", "歌剧": "语义：歌剧与文件被拿走之间没有逻辑关系。"}, "sentence_index": 6, "correct_answer": "数据保护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我给电脑加了一辆数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈辆〉用于车辆，数据保护不能用〈辆〉计量。"}, {"text": "学校订了一张数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈张〉用于纸张、桌子等平面的东西，数据保护不能用〈张〉计量。"}, {"text": "我的软件里有一块数据保护。", "explanation": "这里应该用〈套〉或〈种〉。〈块〉用于块状或片状的东西，数据保护不能用〈块〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个软件能提供一颗数据保护。", "corrected_sentence": "这个软件能提供数据保护。", "error_description": "量词错误：“颗”只用于粒状的东西，不能修饰“数据保护”；直接说“能提供数据保护”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们应该好做数据保护。", "corrected_sentence": "我们应该做好数据保护。", "error_description": "语序错误：“好”作补语应置于动词之后，表示做得完善，说“做好数据保护”；“好做”是“容易做”之义，与“应该”搭配，句意不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
