INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道事情的真实情况。", "primary_collocate": null, "pronunciation": "zhī qíng", "ipa": "ʈʂɻ̩˥ tɕʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "对这个消息，妈妈早就知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他假装不知情，什么也没说。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人知情，事情就这样过去了。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板知情后，马上给我们打了电话。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们都知情，只有他不知道。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知情的话，请告诉我们。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们对旅行的变化并不知情。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁知情，谁就应该站出来。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校对学生的事不知情，家长很生气。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我事先不知情，所以没来。", "target_word": "知情", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不知情", "label": "否定"}, {"form": "知情人", "label": "复合"}, {"form": "知情者", "label": "复合"}], "register": "中性", "sense_fingerprint": "知道事情的真实情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27430, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道事情的真实情况。"}, {"text": "知青", "is_correct": false, "explanation": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。"}, {"text": "痴情", "is_correct": false, "explanation": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。"}, {"text": "诗情", "is_correct": false, "explanation": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。"}, {"text": "知名", "is_correct": false, "explanation": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道事情的真实情况。", "知青": "知青 zhī qīng 与 知情 第二音节声调不同（阴平与阳平），意思是知识青年。", "痴情": "痴情 chī qíng 与 知情 声母不同（ch 与 zh），意思是深切的感情。", "诗情": "诗情 shī qíng 与 知情 声母不同（sh 与 zh），意思是诗意的情感。", "知名": "知名 zhī míng 与 知情 第二音节声母不同（m 与 q），意思是有名气。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“早就知情”指事先已经知道真实情况，与“早就”及句意相合。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能用于“消息”。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与对消息的了解毫无关系，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”是一种活动，与对消息的认知语境不符。"}], "explanations": {"知情": "正确：“早就知情”指事先已经知道真实情况，与“早就”及句意相合。", "打扫": "搭配：“打扫”的对象是场所或物品，不能用于“消息”。", "游泳": "语义：“游泳”与对消息的了解毫无关系，句意不通。", "散步": "语义：“散步”是一种活动，与对消息的认知语境不符。"}, "sentence_index": 0, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直知情他的秘密，因为我是他的好朋友。", "explanation": "这里应该用〈知道〉。知情不能直接带“秘密”作宾语，应说“知道他的秘密”。"}, {"text": "我知情那本书很好看，就买了一本。", "explanation": "这里应该用〈觉得〉。知情不能带小句作宾语，表示认为某物好看，应说“觉得那本书很好看”。"}, {"text": "这件事我早就知情了你的想法。", "explanation": "这里应该用〈了解〉。知情不带“想法”这类宾语，表示了解别人的想法要用“了解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27430, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：知情 zhī qíng，指知道事情的真实情况。"}, {"text": "知行", "is_correct": false, "explanation": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。"}, {"text": "事情", "is_correct": false, "explanation": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。"}, {"text": "实情", "is_correct": false, "explanation": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。"}], "explanations": {"知情": "正确：知情 zhī qíng，指知道事情的真实情况。", "知行": "知行 zhī xíng 与 知情 第二音节声母不同（x 与 q），意思是认识与实践。", "事情": "事情 shì qíng 与 知情 第一音节声母与声调都不同（sh 与 zh，第四声与第一声），意思是事件或情况。", "实情": "实情 shí qíng 与 知情 第一音节声母与声调不同（sh 与 zh，第二声与第一声），意思是实际的情况。"}, "sentence_index": null, "correct_answer": "知情"}, "level_3": {"options": [{"text": "知情", "is_correct": true, "explanation": "正确：“并不知情”指对变化没有了解，与“旅行的变化”的语境相合。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是物件，不能说“修理变化”。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与旅行中的变化无关，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，与对变化的了解无关。"}], "explanations": {"知情": "正确：“并不知情”指对变化没有了解，与“旅行的变化”的语境相合。", "修理": "搭配：“修理”的对象是物件，不能说“修理变化”。", "唱歌": "语义：“唱歌”与旅行中的变化无关，句意不通。", "翻译": "语义：“翻译”指转换语言，与对变化的了解无关。"}, "sentence_index": 6, "correct_answer": "知情"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我知情他的生日，所以提前准备了礼物。", "explanation": "这里应该用〈记得〉。知情指知道事情的真实情况，不能带“生日”这类个人信息作宾语，应说“记得他的生日”。"}, {"text": "她知情了一大碗饭。", "explanation": "这里应该用〈吃〉。知情不能带“饭”这类食物作宾语，表示吃东西应说“吃了一大碗饭”。"}, {"text": "我们都知情这次会议的内容。", "explanation": "这里应该用〈了解〉。知情不直接带“内容”作宾语，表示了解内容要用“了解”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板对此早就了知情。", "corrected_sentence": "老板对此早就知情。", "error_description": "错误：“了”放在“知情”之前，不能说“早就了知情”。“了”不能放在动词前面，应说“对此早就知情”，去掉动词前的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一直都别知情。", "corrected_sentence": "我们一直都不知情。", "error_description": "错误：否定词用了“别”。“别”表示劝阻或禁止，不能用来陈述“一直都不知情”，应把“别”改为“不”，说“我们一直都不知情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
