INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或几个人有一样的想法。", "primary_collocate": null, "pronunciation": "tóng yì", "ipa": "tʰʊŋ³⁵ i⁵¹", "syllable_count": 2, "sentences": [{"text": "我和姐姐都同意，周末在家休息。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会的时候，大家都同意他的想法。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你说得对，我完全同意你的话。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们几个人的想法一样，都同意换地方。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩的意见不同，很难同意对方。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李都同意，明天一起去。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关于春游的地点，同学们终于都同意了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的我都同意，因为我也这么想。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人同意的话，事情就好办了。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸和妈妈都同意买这套房子。", "target_word": "同意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "同意了", "label": "体标"}, {"form": "不同意", "label": "否定"}, {"form": "同意书", "label": "复合"}], "register": "中性", "sense_fingerprint": "几个人想法一样，意见一致", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27436, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：同意 tóng yì，指两人或几个人想法一样。"}, {"text": "同事", "is_correct": false, "explanation": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。"}, {"text": "同一", "is_correct": false, "explanation": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。"}, {"text": "中意", "is_correct": false, "explanation": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。"}, {"text": "同理", "is_correct": false, "explanation": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。"}], "explanations": {"同意": "正确：同意 tóng yì，指两人或几个人想法一样。", "同事": "同事 tóng shì 与 同意 第二音节声母不同（sh 与 y），意思是共事的人。", "同一": "同一 tóng yī 与 同意 第二音节声调不同（第一声与第四声），意思是相同的。", "中意": "中意 zhōng yì 与 同意 第一音节声母与声调不同（zh 与 t，第一声与第二声），意思是满意、喜欢。", "同理": "同理 tóng lǐ 与 同意 第二音节声母与声调不同（l 与 y，第三声与第四声），意思是同样的道理。"}, "sentence_index": null, "correct_answer": "同意"}, "level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“我和姐姐都同意”表示两人想法一致，与后半句的安排相合。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”指动身，与“周末在家休息”的意思相反。"}, {"text": "旅行", "is_correct": false, "explanation": "语义：“旅行”与“在家休息”相悖，句意矛盾。"}, {"text": "爬山", "is_correct": false, "explanation": "搭配：“爬山”是外出活动，与“在家休息”并列时语义冲突。"}], "explanations": {"同意": "正确：“我和姐姐都同意”表示两人想法一致，与后半句的安排相合。", "出发": "语义：“出发”指动身，与“周末在家休息”的意思相反。", "旅行": "语义：“旅行”与“在家休息”相悖，句意矛盾。", "爬山": "搭配：“爬山”是外出活动，与“在家休息”并列时语义冲突。"}, "sentence_index": 0, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都同意你的生日。", "explanation": "这里应该用〈庆祝〉。同意用于请求、意见，不能用于“生日”这样的节日。"}, {"text": "几个人的身高很同意。", "explanation": "这里应该用〈一样〉。同意指人的想法一致，不用于身高这类客观情况。"}, {"text": "这两件衣服的颜色很同意。", "explanation": "这里应该用〈相同〉。同意指人的想法一致，物件的颜色不用“同意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同意", "is_correct": true, "explanation": "正确：“同学们终于都同意了”表示大家意见一致，与选择地点的语境相合。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与选择春游地点的语境无关，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与讨论地点的语境无关。"}, {"text": "写作", "is_correct": false, "explanation": "搭配：“写作”的对象是文字，不能用于“地点”的选择。"}], "explanations": {"同意": "正确：“同学们终于都同意了”表示大家意见一致，与选择地点的语境相合。", "游泳": "语义：“游泳”与选择春游地点的语境无关，句意不通。", "唱歌": "语义：“唱歌”与讨论地点的语境无关。", "写作": "搭配：“写作”的对象是文字，不能用于“地点”的选择。"}, "sentence_index": 6, "correct_answer": "同意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和你的年龄很同意。", "explanation": "这里应该用〈相同〉。同意指人的想法一致，不用于“年龄”这类客观情况。"}, {"text": "妈妈同意了这件蛋糕。", "explanation": "这里应该用〈喜欢〉。同意是接受请求或计划，不能用于“蛋糕”这样的物品。"}, {"text": "爸爸同意了我的玩笑。", "explanation": "这里应该用〈听懂〉。同意不能用于“玩笑”这类话语内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们俩想法一样，都了同意换个地方。", "corrected_sentence": "我们俩想法一样，都同意换个地方。", "error_description": "错误：“了”放在“同意”之前，不能说“都了同意换个地方”，应说“都同意换个地方”，“了”不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都把同意这个主意。", "corrected_sentence": "大家都同意这个主意。", "error_description": "错误：“把”放在“同意”之前，不能说“都把同意这个主意”。“同意”不能用“把”字句，应说“都同意这个主意”，去掉动词前的“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "灵活性", "is_correct": false, "explanation": "与概括性无反义关系：灵活性指能随情况变化、不呆板的特性。"}, {"text": "流动性", "is_correct": false, "explanation": "与概括性无反义关系：流动性指事物能够移动、变化的特性。"}, {"text": "稳定性", "is_correct": false, "explanation": "与概括性无反义关系：稳定性指不易发生变化的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "灵活性": "与概括性无反义关系：灵活性指能随情况变化、不呆板的特性。", "流动性": "与概括性无反义关系：流动性指事物能够移动、变化的特性。", "稳定性": "与概括性无反义关系：稳定性指不易发生变化的特性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体性", "is_correct": true, "explanation": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。"}, {"text": "连续性", "is_correct": false, "explanation": "与概括性无反义关系：连续性指时间或空间上不间断的特性。"}, {"text": "时效性", "is_correct": false, "explanation": "与概括性无反义关系：时效性指在一定时间内有效的特性。"}, {"text": "可靠性", "is_correct": false, "explanation": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}], "correct_answer": "具体性", "explanations": {"具体性": "具体性与概括性相对：概括性指归纳共同点，具体性指细节明确、针对个别事物。", "连续性": "与概括性无反义关系：连续性指时间或空间上不间断的特性。", "时效性": "与概括性无反义关系：时效性指在一定时间内有效的特性。", "可靠性": "与概括性无反义关系：可靠性指值得信赖、不易出错的特性。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "能说出很多事情的共同点的特点。", "primary_collocate": null, "pronunciation": "gài kuò xìng", "ipa": "kaɪ⁵¹ kʰuɔ⁵¹ ɕiŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "“水果”这个词的概括性很强。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲话的概括性很强，一句话说完了。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表有概括性，能看出大家的共同点。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这本书，因为它的概括性很好。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸这个学生的总结很有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“家具”比“桌子”更有概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话的概括性太弱，说不清楚大家的共同点。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写总结时，要注意概括性。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话没有概括性，总是讲小事。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字有概括性，包括了很多种动物。", "target_word": "概括性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "概括", "label": "词根"}], "register": "书面", "sense_fingerprint": "能说出许多事物共同点的特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '32cca9b7-00be-47a2-8603-0c4deb9a2c2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性指能说出许多事物共同点的特性，与「很强」搭配自然。"}, {"text": "专业性", "is_correct": false, "explanation": "语域：「水果」是日常通用词，说它专业性很强与词义不符。"}, {"text": "方言性", "is_correct": false, "explanation": "语义：「水果」是普通话通用词，不具方言性。"}, {"text": "古语性", "is_correct": false, "explanation": "语域：「水果」是现代通用语，不带古语色彩。"}], "explanations": {"概括性": "概括性指能说出许多事物共同点的特性，与「很强」搭配自然。", "专业性": "语域：「水果」是日常通用词，说它专业性很强与词义不符。", "方言性": "语义：「水果」是普通话通用词，不具方言性。", "古语性": "语域：「水果」是现代通用语，不带古语色彩。"}, "sentence_index": 0, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的概括性很高，误差只有零点零一毫米。", "explanation": "这里应该用〈精度〉。概括性指归纳共同点的特性，不指测量的准确程度；误差很小，应说精度高。"}, {"text": "这个水杯的概括性很好，颜色也漂亮。", "explanation": "这里应该用〈美观〉。概括性指归纳共同点的特性，不指器物的外观；杯子颜色漂亮，应说美观。"}, {"text": "我家的狗很有概括性。", "explanation": "这里应该用〈聪明〉。概括性指归纳共同点的特性，不用来形容动物；形容狗，应说“很聪明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "概括性", "is_correct": true, "explanation": "概括性指能归纳共同点，与「太弱，说不清楚大家的共同点」的语境相符。"}, {"text": "幽默性", "is_correct": false, "explanation": "语义：幽默性指使人发笑的特性，与「说不清楚大家的共同点」无关。"}, {"text": "节奏性", "is_correct": false, "explanation": "语义：节奏性指有起伏、有韵律的特性，与句中讲共同点的语境不符。"}, {"text": "艺术性", "is_correct": false, "explanation": "搭配：「太弱」常修饰归纳、表达的效果，「艺术性太弱」与「说不清楚共同点」不搭。"}], "explanations": {"概括性": "概括性指能归纳共同点，与「太弱，说不清楚大家的共同点」的语境相符。", "幽默性": "语义：幽默性指使人发笑的特性，与「说不清楚大家的共同点」无关。", "节奏性": "语义：节奏性指有起伏、有韵律的特性，与句中讲共同点的语境不符。", "艺术性": "搭配：「太弱」常修饰归纳、表达的效果，「艺术性太弱」与「说不清楚共同点」不搭。"}, "sentence_index": 6, "correct_answer": "概括性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张图的概括性很高，每个字都看得清。", "explanation": "这里应该用〈清晰度〉。概括性指归纳共同点的特性，不指图片的清楚程度；每个字都看得清，应说清晰度高。"}, {"text": "这座桥的概括性很好，车辆多也不晃。", "explanation": "这里应该用〈稳定性〉。概括性指归纳共同点的特性，不指桥梁的牢固程度；车多也不晃，应说稳定性好。"}, {"text": "这次比赛的概括性很高，裁判一视同仁。", "explanation": "这里应该用〈公平性〉。概括性指归纳共同点的特性，不指比赛是否公正；裁判一视同仁，应说公平性高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的讲话很概括性，一句话就说清楚了。", "corrected_sentence": "他的讲话很有概括性，一句话就说清楚了。", "error_description": "搭配错误：「概括性」是名词，不能直接用「很」修饰，应说「很有概括性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇文章有一把很强的概括性，读起来很容易懂。", "corrected_sentence": "这篇文章有一种很强的概括性，读起来很容易懂。", "error_description": "量词错误：「概括性」是抽象名词，应用「种」；「把」用于有柄的器具，不能修饰概括性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c75e2b6d-6326-4a0d-8575-9aa579d848ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
