INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27442, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能帮助说明一个东西是什么样子的。", "primary_collocate": null, "pronunciation": "jiě shì xìng", "ipa": "tɕjɛ˨˩ ʂɨ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "图片旁边有一段解释性的文字。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图是解释性的，能看出房子的样子。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书里有很多解释性的图。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了解释性的照片。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个模型有解释性，大家一看就明白。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上的解释性图画让我知道了那只动物的样子。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用解释性的话说明了新手机的样子。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些解释性的图片很清楚。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图下面有解释性的小字。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的解释性很强，图也多。", "target_word": "解释性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解释性图画", "label": "复合"}, {"form": "解释性文字", "label": "复合"}], "register": "书面语", "sense_fingerprint": "能帮助说明事物样子的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '057e6d26-3654-4b17-8f8c-867298f547be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解释性", "is_correct": true, "explanation": "与“图片旁边”搭配，文字用来说明图片中事物的样子，符合语境。"}, {"text": "抽象性", "is_correct": false, "explanation": "语义：图片旁边的文字要帮助看出事物的样子，抽象的说法与图片不符。"}, {"text": "保密性", "is_correct": false, "explanation": "语义：印在图片旁边的文字是给人看的，不说它有“保密性”。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”多用于数据或过程，不用来形容说明文字。"}], "explanations": {"解释性": "与“图片旁边”搭配，文字用来说明图片中事物的样子，符合语境。", "抽象性": "语义：图片旁边的文字要帮助看出事物的样子，抽象的说法与图片不符。", "保密性": "语义：印在图片旁边的文字是给人看的，不说它有“保密性”。", "随机性": "搭配：“随机性”多用于数据或过程，不用来形容说明文字。"}, "sentence_index": 0, "correct_answer": "解释性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个笑话很有解释性，大家都笑了。", "explanation": "解释性用于说明图片、文字的样子或含义，不用来描述笑话；这里应该用〈好笑〉。"}, {"text": "妈妈给我买了一条解释性的裙子。", "explanation": "解释性不用于形容服装的样子；这里应该用〈漂亮〉或〈时尚〉。"}, {"text": "这场比赛很有解释性，大家都看入迷了。", "explanation": "这里应该用〈精彩〉。解释性指能帮助看出事物样子的图文，不用来形容比赛是否精彩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解释性", "is_correct": true, "explanation": "与“说明了新手机的样子”搭配，话用来说明事物的样子，符合语境。"}, {"text": "模糊性", "is_correct": false, "explanation": "语义：话模糊就不能清楚说明新手机的样子，与句意相矛盾。"}, {"text": "神秘性", "is_correct": false, "explanation": "语义：说明样子需要清楚直接，神秘的说法无法说清新手机的样子。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：装饰性指起美化点缀的作用，用来说明样子的话不靠装饰，与句意不符。"}], "explanations": {"解释性": "与“说明了新手机的样子”搭配，话用来说明事物的样子，符合语境。", "模糊性": "语义：话模糊就不能清楚说明新手机的样子，与句意相矛盾。", "神秘性": "语义：说明样子需要清楚直接，神秘的说法无法说清新手机的样子。", "装饰性": "语义：装饰性指起美化点缀的作用，用来说明样子的话不靠装饰，与句意不符。"}, "sentence_index": 6, "correct_answer": "解释性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天天气很有解释性，我们去公园吧。", "explanation": "解释性用于说明事物样子的图文，不用来描述天气；这里应该用〈晴朗〉。"}, {"text": "这张桌子很有解释性，坐着很舒服。", "explanation": "解释性不用来形容桌子的舒适；这里应该用〈结实〉或〈舒适〉之类的词。"}, {"text": "他的生日蛋糕很有解释性，大家都很高兴。", "explanation": "解释性不用来形容蛋糕；这里应该用〈好看〉或〈美味〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张示意图很解释性，一眼就能看出结构。", "corrected_sentence": "这张示意图很有解释性，一眼就能看出结构。", "error_description": "错误：“很解释性”漏了“有”。正确说法是“很有解释性”，“有”不能省。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套图册的说明写地很有解释性。", "corrected_sentence": "这套图册的说明写得很有解释性。", "error_description": "错误：“写得”的“得”误写成了“地”。“地”用于动词前作状语，动词后引出补语要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
