INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27444, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能自己做出新东西。", "primary_collocate": null, "pronunciation": "shēng chéng shì", "ipa": "ʂəŋ˥ ʈʂʰəŋ˧˥ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这个生成式软件能自己画出新图片。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式系统可以自己写出新故事。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对生成式工具很感兴趣。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一种生成式的新方法。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式模型能做出新的音乐。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学习生成式技术。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个生成式程序写出了一篇新文章。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式应用越来越多了。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用生成式软件做了一本图画书。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生成式工具能根据你的话做出新照片。", "target_word": "生成式", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "生成式：能自己做出新东西的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生成式", "is_correct": true, "explanation": "正确：修饰“软件”，指能自己做出新图片的，符合句意。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，不能用来修饰“软件”，句意不通。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味觉词，不能修饰“软件”，句意不通。"}, {"text": "昏庸", "is_correct": false, "explanation": "语域：“昏庸”多用于文言或书面评述，与现代软件的语境不合。"}], "explanations": {"生成式": "正确：修饰“软件”，指能自己做出新图片的，符合句意。", "清脆": "语义：“清脆”形容声音，不能用来修饰“软件”，句意不通。", "咸": "语义：“咸”是味觉词，不能修饰“软件”，句意不通。", "昏庸": "语域：“昏庸”多用于文言或书面评述，与现代软件的语境不合。"}, "sentence_index": 0, "correct_answer": "生成式"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台生成式词典能查生词。", "explanation": "这里应该用〈电子〉。生成式指能自己做出新东西，查生词不是做出新东西，应该用“电子”。"}, {"text": "这款生成式音箱能播放音乐。", "explanation": "这里应该用〈智能〉。播放音乐是放现成的内容，不是自己做出新东西，应该用“智能”。"}, {"text": "这扇生成式门能打开。", "explanation": "这里应该用〈自动〉。开门是门自己动起来，不是做出新东西，应该用“自动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生成式", "is_correct": true, "explanation": "正确：修饰“程序”，指能自己做出新东西的，符合句意。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来修饰“程序”，句意不通。"}, {"text": "甜腻", "is_correct": false, "explanation": "语义：“甜腻”形容味道，不能用来修饰“程序”，句意不通。"}, {"text": "巍峨", "is_correct": false, "explanation": "搭配：“巍峨”形容山势高大，不能用来修饰“程序”，句意不通。"}], "explanations": {"生成式": "正确：修饰“程序”，指能自己做出新东西的，符合句意。", "寒冷": "语义：“寒冷”形容温度，不能用来修饰“程序”，句意不通。", "甜腻": "语义：“甜腻”形容味道，不能用来修饰“程序”，句意不通。", "巍峨": "搭配：“巍峨”形容山势高大，不能用来修饰“程序”，句意不通。"}, "sentence_index": 6, "correct_answer": "生成式"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台生成式冰箱能冷藏食物。", "explanation": "这里应该用〈制冷〉。冷藏靠降温，不是做出新东西；应说制冷。"}, {"text": "这张生成式桌子很结实。", "explanation": "这里应该用〈木制〉。生成式指能自己做出新东西，不能用来描述桌子的材质；桌子的材质应说木制。"}, {"text": "这台生成式洗衣机洗得很干净。", "explanation": "这里应该用〈全自动〉。洗衣靠按程序清洗，不是做出新东西；应说全自动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种生成式工具们能自己谱出新曲子。", "corrected_sentence": "这种生成式工具能自己谱出新曲子。", "error_description": "词形错误：“们”只用于指人的复数，“工具”是事物名词，不能加“们”，应说“这种生成式工具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方法是很生成式的。", "corrected_sentence": "这种方法是生成式的。", "error_description": "程度词误用：“很”不能修饰“生成式”，应直接说“是生成式的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
