INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "写电脑程序时，人写的字和符号。", "primary_collocate": null, "pronunciation": "yuán dài mǎ", "ipa": "ɥɛn˧˥ taɪ̯˥˩ ma˨˩˦", "syllable_count": 3, "sentences": [{"text": "我写的源代码有一个错误。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们看一下他的源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的源代码很长。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把源代码保存在电脑里。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把源代码复制到了新文件里。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "源代码里的符号不能写错。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥正在电脑上写源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能帮我检查一下源代码吗？", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生交了作业，也交了源代码。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些源代码是我自己写的。", "target_word": "源代码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一段源代码", "label": "量词"}, {"form": "一份源代码", "label": "量词"}, {"form": "开放源代码", "label": "复合"}, {"form": "源代碼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "写程序时人亲手写下的文字和符号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：源代码指写程序时人写下的文字和符号，与“写的”相符，句意是程序里有错误。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人写下的文字和符号，不能说写的天气。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“写”用于文字、程序，不说写汤。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是人写下的文字和符号，与“写的”不符。"}], "explanations": {"源代码": "正确：源代码指写程序时人写下的文字和符号，与“写的”相符，句意是程序里有错误。", "天气": "语义：天气不是人写下的文字和符号，不能说写的天气。", "汤": "搭配：“写”用于文字、程序，不说写汤。", "月亮": "语义：月亮不是人写下的文字和符号，与“写的”不符。"}, "sentence_index": 0, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他双击了这个源代码，游戏就启动了。", "explanation": "这里应该用“软件”。源代码是人写的字和符号，不能双击启动游戏；能启动游戏的是软件。"}, {"text": "数学公式里有很多源代码。", "explanation": "这里应该用“符号”。源代码指写程序时用的字和符号，数学公式里的应说符号，不能说源代码。"}, {"text": "这台电脑的源代码很重，要两个人才能抬动。", "explanation": "这里应该用“主机”。源代码是人写的字和符号，没有重量；说电脑的重量应用主机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "源代码", "is_correct": true, "explanation": "正确：源代码是写程序用的文字和符号，在电脑上书写的正是它，与句意相符。"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“写”用于文字、程序，不说写面条。"}, {"text": "火车", "is_correct": false, "explanation": "语义：火车是交通工具，不能在电脑上书写。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不是可以书写的文字或符号。"}], "explanations": {"源代码": "正确：源代码是写程序用的文字和符号，在电脑上书写的正是它，与句意相符。", "面条": "搭配：“写”用于文字、程序，不说写面条。", "火车": "语义：火车是交通工具，不能在电脑上书写。", "花园": "语义：花园是地方，不是可以书写的文字或符号。"}, "sentence_index": 6, "correct_answer": "源代码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇作文的源代码写得很优美。", "explanation": "这里应该用“文字”。源代码指写程序时用的字和符号，不能用来形容作文的文字。"}, {"text": "他用这个源代码订了一张火车票。", "explanation": "这里应该用“程序”。源代码是写程序用的字和符号，本身不能用来订票。"}, {"text": "这部电影的源代码翻译得很准确。", "explanation": "这里应该用“字幕”。源代码指程序的字和符号，不能指电影的字幕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下午把一棵源代码发给了同事。", "corrected_sentence": "他下午把一段源代码发给了同事。", "error_description": "错误：“一棵源代码”，应为“一段源代码”。“棵”用于树木，源代码的量词是段、份。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把一座源代码放进了邮件里。", "corrected_sentence": "他把一份源代码放进了邮件里。", "error_description": "错误：“一座源代码”，应为“一份源代码”。“座”用于山、建筑等大型固定物，源代码的量词是段、份。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“机密”意思相反，指让别人知道的事情。"}, {"text": "简单", "is_correct": false, "explanation": "语义：“简单”说明不复杂，与“机密”的不能告诉别人无关。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”说明光线充足，与“机密”的含义无关。"}, {"text": "普遍", "is_correct": false, "explanation": "语义：“普遍”说明范围广，与“机密”的含义无关。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“机密”意思相反，指让别人知道的事情。", "简单": "语义：“简单”说明不复杂，与“机密”的不能告诉别人无关。", "明亮": "语义：“明亮”说明光线充足，与“机密”的含义无关。", "普遍": "语义：“普遍”说明范围广，与“机密”的含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "公开", "is_correct": true, "explanation": "正确：“公开”与“机密”意思相反，指让别人知道的事情。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”说明明白，与“机密”的不能告诉别人无关。"}, {"text": "普通", "is_correct": false, "explanation": "语义：“普通”说明一般，与“机密”的含义无关。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”说明场面喧闹，与“机密”的含义无关。"}], "correct_answer": "公开", "explanations": {"公开": "正确：“公开”与“机密”意思相反，指让别人知道的事情。", "清楚": "语义：“清楚”说明明白，与“机密”的不能告诉别人无关。", "普通": "语义：“普通”说明一般，与“机密”的含义无关。", "热闹": "语义：“热闹”说明场面喧闹，与“机密”的含义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机密就是不能告诉别人的重要事情。", "primary_collocate": null, "pronunciation": "jī mì", "ipa": "tɕi˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "这是我们两个人的机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能替我保守这个机密吗？", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把机密告诉了好朋友。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹有一个不能说的机密。", "target_word": "机密", "complexity_tier": "T3", "furigana": "mèi mei yǒu yí ge bù néng shuō de jī mì", "sentence_source": "generated"}, {"text": "这件事是机密，别告诉别人。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想说出这个机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于说出了心里的机密。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的机密，我从来不乱说。", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道他的机密吗？", "target_word": "机密", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟偷偷藏着一个重要的机密。", "target_word": "机密", "complexity_tier": "T3", "furigana": "dì di tōu tōu cáng zhe yí ge zhòng yào de jī mì", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个机密", "label": "量词"}, {"form": "一份机密", "label": "量词"}, {"form": "国家机密", "label": "复合"}, {"form": "機密", "label": "繁体"}], "register": "口语", "sense_fingerprint": "日常生活中不能告诉别人的重要事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d5cc799-3df8-4bb6-b844-1bd220175944') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机密", "is_correct": true, "explanation": "正确：“机密”指不能告诉别人的重要事情，与“两个人的”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“两个人的”修饰可以归属的事物，天气不能说成两个人的。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮是天体，不是两个人之间的秘密事情。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是自然环境，不是两个人之间不能告诉别人的事情。"}], "explanations": {"机密": "正确：“机密”指不能告诉别人的重要事情，与“两个人的”相符。", "天气": "搭配：“两个人的”修饰可以归属的事物，天气不能说成两个人的。", "月亮": "语义：月亮是天体，不是两个人之间的秘密事情。", "空气": "语义：空气是自然环境，不是两个人之间不能告诉别人的事情。"}, "sentence_index": 0, "correct_answer": "机密"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把钥匙锁进了机密里，我们找了一整天。", "explanation": "这里应该用“抽屉”。机密是不能告诉别人的重要事情，不是能装东西的地方；装钥匙的应是抽屉。"}, {"text": "我忘了网站的机密，只好重新设置。", "explanation": "这里应该用“密码”。机密是不能告诉别人的重要事情，不能用来登录网站；登录网站的应是密码。"}, {"text": "这把机密很锋利，可以用来切菜。", "explanation": "这里应该用“刀”。机密是不能告诉别人的重要事情，不是切东西的工具；切菜用的应是刀。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机密", "is_correct": true, "explanation": "正确：“机密”指心里不能告诉别人的重要事情，与“说出了心里的”相符。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是可以说出来的心里话。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不是可以说出口的心事。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“说出”用于话语、想法，不说说出汽车。"}], "explanations": {"机密": "正确：“机密”指心里不能告诉别人的重要事情，与“说出了心里的”相符。", "面包": "语义：面包是食物，不是可以说出来的心里话。", "闹钟": "语义：闹钟是计时器具，不是可以说出口的心事。", "汽车": "搭配：“说出”用于话语、想法，不说说出汽车。"}, "sentence_index": 6, "correct_answer": "机密"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气是机密。", "explanation": "这里应该用“常识”。机密是不能告诉别人的重要事情，天气人人都知道，不能当作机密。"}, {"text": "这次球赛的比分是机密，电视上都播出来了。", "explanation": "这里应该用“公开”。机密是不能告诉别人的重要事情，电视上播出的比分已经公开，不再是机密。"}, {"text": "我的手机号码是机密，每个人都能在网上查到。", "explanation": "这里应该用“个人信息”。机密是不能告诉别人的重要事情，网上随处可查的号码不算机密，应说个人信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不会把这只机密告诉别人。", "corrected_sentence": "我不会把这个机密告诉别人。", "error_description": "错误：“这只机密”，应为“这个机密”。“只”通常用于动物，机密的量词用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆机密我从来没有告诉过别人。", "corrected_sentence": "这个机密我从来没有告诉过别人。", "error_description": "错误：“这辆机密”，应为“这个机密”。“辆”用于车辆，机密的量词用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91e37daa-2e70-4d22-b319-78b56b3d1521') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
