INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27450, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一群人组织起来做事的团体，比如学校、公司。", "primary_collocate": null, "pronunciation": "jī gòu", "ipa": "tɕi˥ kou˥˩", "syllable_count": 2, "sentences": [{"text": "学校是教育机构。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构帮助有困难的孩子。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和学校都是机构。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在一个大机构里工作。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构有一百多个人。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想找一家好的培训机构。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家机构的老师都很热心。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们机构明天开会。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们机构做了很多好事。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机构在学校旁边。", "target_word": "机构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "培训机构", "label": "复合"}, {"form": "機構", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "一群人组织起来做事的团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '057e6d26-3654-4b17-8f8c-867298f547be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指一群人组织起来做事的团体，“教育机构”是常见说法，与“学校”相符。"}, {"text": "食品", "is_correct": false, "explanation": "语义：“食品”是供人吃的东西，学校不是食品，“学校是教育食品”说不通。"}, {"text": "摊子", "is_correct": false, "explanation": "语域：“摊子”是口语，指小买卖的摊位，与书面语“教育”不协调，也不指学校。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食物，与学校的性质无关，“学校是教育饼干”说不通。"}], "explanations": {"机构": "正确：“机构”指一群人组织起来做事的团体，“教育机构”是常见说法，与“学校”相符。", "食品": "语义：“食品”是供人吃的东西，学校不是食品，“学校是教育食品”说不通。", "摊子": "语域：“摊子”是口语，指小买卖的摊位，与书面语“教育”不协调，也不指学校。", "饼干": "语义：“饼干”是食物，与学校的性质无关，“学校是教育饼干”说不通。"}, "sentence_index": 0, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的机构是我的妈妈。", "explanation": "这里应该用〈亲人〉。“机构”指一群人组织起来做事的团体，不能用来指单独的一个人，“妈妈”是个人，要说“亲人”。"}, {"text": "我哥哥在一座大机构里工作。", "explanation": "这里应该用〈个〉或〈家〉。“座”多用于山、楼、桥等大型建筑，“机构”是团体，不用“座”来数。"}, {"text": "这栋房子的机构很稳固。", "explanation": "这里应该用〈结构〉。“机构”指团体或部门，房屋的承重和组合方式要用“结构”，不能用“机构”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "机构", "is_correct": true, "explanation": "正确：“机构”指一群人组织起来做事的团体，有老师，与“这家”搭配自然。"}, {"text": "花店", "is_correct": false, "explanation": "语义：“花店”是卖花的店，没有老师，“这家花店的老师”说不通。"}, {"text": "饭馆", "is_correct": false, "explanation": "语义：“饭馆”一般不设老师，“饭馆的老师都很热心”说不通。"}, {"text": "小店", "is_correct": false, "explanation": "语域：“小店”是口语，指规模很小的店铺，与书面语的“机构”语域不一致，也没有老师。"}], "explanations": {"机构": "正确：“机构”指一群人组织起来做事的团体，有老师，与“这家”搭配自然。", "花店": "语义：“花店”是卖花的店，没有老师，“这家花店的老师”说不通。", "饭馆": "语义：“饭馆”一般不设老师，“饭馆的老师都很热心”说不通。", "小店": "语域：“小店”是口语，指规模很小的店铺，与书面语的“机构”语域不一致，也没有老师。"}, "sentence_index": 6, "correct_answer": "机构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的机构喜欢吃苹果。", "explanation": "这里应该用〈小孩〉。“机构”指团体，不能用来指一个会吃东西的个人，说“他的小孩”才对。"}, {"text": "这个机构的眼睛很大。", "explanation": "这里应该用〈人〉。“机构”指由人组成的团体，不能用来描述有眼睛的个体。"}, {"text": "这台机构在学校旁边。", "explanation": "这里应该用〈个〉或〈家〉。“台”用于机器和设备，“机构”不是机器，不能用“台”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的朋友在一位培训机构教英语。", "corrected_sentence": "我的朋友在一家培训机构教英语。", "error_description": "量词错误：“位”用于人，“培训机构”应该用量词“家”或“个”，不能用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本培训机构去年招了三百名学生。", "corrected_sentence": "这家培训机构去年招了三百名学生。", "error_description": "量词错误：“本”用于书籍，“培训机构”应该用量词“家”，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bdef413-8734-4479-8886-a44e6396d74a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
