INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27452, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情还没发生，就能猜到它大概会怎样。", "primary_collocate": null, "pronunciation": "kě yù cè xìng", "ipa": "kʰɤ˨˩˦ y˥˩ tsʰɤ˥˩ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这场比赛的可预测性很低，谁都猜不到。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活很有规律，可预测性很高。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气的可预测性不高，明天可能下雨。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影太没有可预测性了，我一点也猜不到。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事的可预测性太高，我一看就知道结局。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震的可预测性很低，人们很难提前知道。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说考试的可预测性不高，要多复习。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的行为可预测性低，父母常常吃惊。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意最怕没有可预测性，谁也不知道以后。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "交通的可预测性很差，常常突然堵车。", "target_word": "可预测性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可預測性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可预测性|事情没发生前就能猜到大概结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美观性", "is_correct": false, "explanation": "语义：后半句“谁都猜不到”说明结果难以预见，美观性与之无关，句意矛盾。"}, {"text": "可预测性", "is_correct": true, "explanation": "正确：指比赛结果能否提前推断，与“谁都猜不到”的意思一致。"}, {"text": "对称性", "is_correct": false, "explanation": "语义：比赛的对称性与“很低，谁都猜不到”没有关系。"}, {"text": "环保性", "is_correct": false, "explanation": "搭配：比赛不说“环保性”，“环保性很低”也无法与后面的“猜不到”衔接。"}], "explanations": {"美观性": "语义：后半句“谁都猜不到”说明结果难以预见，美观性与之无关，句意矛盾。", "可预测性": "正确：指比赛结果能否提前推断，与“谁都猜不到”的意思一致。", "对称性": "语义：比赛的对称性与“很低，谁都猜不到”没有关系。", "环保性": "搭配：比赛不说“环保性”，“环保性很低”也无法与后面的“猜不到”衔接。"}, "sentence_index": 0, "correct_answer": "可预测性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师对这段话的可预测性很深，大家都佩服。", "explanation": "这里应该用〈理解〉。〈理解〉指懂得、弄明白，说对内容懂得深要用〈理解〉；可预测性指事情能否被猜到，不能说“深”。"}, {"text": "这次比赛的可预测性很著名，很多人都来看。", "explanation": "这里应该用〈著名〉。〈著名〉形容人或事物有名气，说比赛出名要用〈著名〉；可预测性指事情能否被猜到，不能形容名气。"}, {"text": "这座花园的可预测性很漂亮，很多人来拍照。", "explanation": "这里应该用〈外观〉。〈外观〉指物体的样子，说花园好看要用〈外观〉；可预测性指事情能否被猜到，不能形容好看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地域性", "is_correct": false, "explanation": "搭配：“地域性”不用于考试，二者搭配不当。"}, {"text": "可预测性", "is_correct": true, "explanation": "正确：指考试结果难以推断，所以“要多复习”，符合句意。"}, {"text": "音乐性", "is_correct": false, "explanation": "语义：考试不以音乐性为标准，句意不通。"}, {"text": "历史性", "is_correct": false, "explanation": "语义：“历史性”指事件的历史意义，与复习的建议无关。"}], "explanations": {"地域性": "搭配：“地域性”不用于考试，二者搭配不当。", "可预测性": "正确：指考试结果难以推断，所以“要多复习”，符合句意。", "音乐性": "语义：考试不以音乐性为标准，句意不通。", "历史性": "语义：“历史性”指事件的历史意义，与复习的建议无关。"}, "sentence_index": 6, "correct_answer": "可预测性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的可预测性很鲜，大家都爱喝。", "explanation": "这里应该用〈味道〉。〈鲜〉形容汤的味道好，说汤的味道要用〈味道〉；可预测性指事情能否被猜到，不能形容味道。"}, {"text": "这个孩子的可预测性很强，能背很多古诗。", "explanation": "这里应该用〈能力〉。〈能力〉指做事的本领，说孩子会背诗的本事要用〈能力〉；可预测性指事情能否被猜到，不能形容本领。"}, {"text": "这次天气的可预测性很准，我们都没带伞。", "explanation": "这里应该用〈预报〉。“准”用于天气预报的结果，说预报准不准要用〈预报〉；可预测性指事情能否被猜到，不能说“准”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划的可预测性好很，大家都放心。", "corrected_sentence": "这个计划的可预测性很好，大家都放心。", "error_description": "错误在“很”的位置：形容词作谓语前要加“很”，应说“很好”，不说“好很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革有一只很高的可预测性。", "corrected_sentence": "这次改革有一种很高的可预测性。", "error_description": "错误在量词：可预测性表示性质，应该用量词〈种〉，不能用〈只〉（〈只〉多用于动物或成对的东西）。正确说法是：有一种很高的可预测性。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
