INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27456, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做决定。", "primary_collocate": null, "pronunciation": "jué cè", "ipa": "tɕye˧˥ tsʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "遇到大事，他总是很快决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "领导们正在会议室里决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要在下个月决策是否投资。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不喜欢一个人决策，总想听大家的意见。", "target_word": "决策", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对危机，管理者必须冷静地决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事太复杂，他没办法马上决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的大事由爸爸来决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队教练要在比赛中快速决策。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生必须在几分钟内决策，不能再等。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他决策得太晚，机会已经没有了。", "target_word": "决策", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "决策了", "label": "体标"}, {"form": "決策", "label": "繁体"}], "register": "书面", "sense_fingerprint": "决策|动词|就事情做出决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“很快决策”指遇事快速做出决定，与“遇到大事”的语境一致。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”是慢慢推迟，与“很快”的意思矛盾。"}, {"text": "犹豫", "is_correct": false, "explanation": "语义：“犹豫”表示拿不定主意，与“很快”的意思矛盾。"}, {"text": "举行", "is_correct": false, "explanation": "配价：“举行”需要带宾语（如会议、仪式），单说“很快举行”不成句。"}], "explanations": {"决策": "正确。“很快决策”指遇事快速做出决定，与“遇到大事”的语境一致。", "拖延": "语义：“拖延”是慢慢推迟，与“很快”的意思矛盾。", "犹豫": "语义：“犹豫”表示拿不定主意，与“很快”的意思矛盾。", "举行": "配价：“举行”需要带宾语（如会议、仪式），单说“很快举行”不成句。"}, "sentence_index": 0, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道数学题我还没决策出来。", "explanation": "这里应该用〈解出〉。“决策”指做决定，解数学题要说“解出来”。"}, {"text": "妈妈在市场里决策水果。", "explanation": "这里应该用〈挑选〉。买水果是挑选，“决策”是对重要事情做选择和判断。"}, {"text": "周末我们要决策房间。", "explanation": "这里应该用〈打扫〉。“决策”是做决定，不能用于打扫房间这类日常劳动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "决策", "is_correct": true, "explanation": "正确。“由爸爸来决策”指爸爸来做决定，与“家里的大事”一致。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”是个人的日常行为，与“家里的大事”无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是个人休息，不能用来处理家里的大事。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”需要带宾语（拥有什么），“由爸爸来拥有”宾语缺失，不成句。"}], "explanations": {"决策": "正确。“由爸爸来决策”指爸爸来做决定，与“家里的大事”一致。", "洗澡": "语义：“洗澡”是个人的日常行为，与“家里的大事”无关，句意不通。", "睡觉": "语义：“睡觉”是个人休息，不能用来处理家里的大事。", "拥有": "配价：“拥有”需要带宾语（拥有什么），“由爸爸来拥有”宾语缺失，不成句。"}, "sentence_index": 6, "correct_answer": "决策"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把菜决策得很好吃。", "explanation": "这里应该用〈做〉。“决策”指做选择和判断，做菜要说“做得很好吃”。"}, {"text": "医生决策病人的病情。", "explanation": "这里应该用〈判断〉。判断病情是认识和分析，“决策”是做选择，不能用于病情。"}, {"text": "他去决策消息了。", "explanation": "这里应该用〈打听〉。“打听”是询问消息，“决策”是做选择，不能用于消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位经理很快就很决策了。", "corrected_sentence": "这位经理很快就决策了。", "error_description": "错误：副词“很”不能直接修饰动词“决策”。应去掉多余的“很”，说“很快就决策了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "领导还没决策了。", "corrected_sentence": "领导还没决策。", "error_description": "错误：“还没……”表示未完成，不能与“了”同用。应去掉“了”，说“还没决策”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
