INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "告诉你怎么做。", "primary_collocate": null, "pronunciation": "zhǐ nán", "ipa": "ʈʂɻ̩˨˩ nan˧˥", "syllable_count": 2, "sentences": [{"text": "这本指南很有用，我出去旅行时带着它。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "我买了一本指南，里面有北京的美食。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "新手可以先看看这本指南。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "这本指南上写着怎么开机。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "这份指南告诉你哪里便宜。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "她在网上找了一份做蛋糕的指南。", "target_word": "指南", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你照着这份指南一步一步做。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "这本指南教你怎么学汉语。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "我朋友给我写了一份指南，讲怎么留学。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}, {"text": "出门旅游以前，我先看了一下这份指南。", "target_word": "指南", "complexity_tier": "T3", "furigana": "しなん", "sentence_source": "generated"}], "morphological_forms": [{"form": "旅行指南", "label": "复合"}, {"form": "使用指南", "label": "复合"}], "register": "中性", "sense_fingerprint": "指南：教人具体怎么做的手册或说明（名词，中性）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指南", "is_correct": true, "explanation": "指南：教人具体怎么做的手册，符合“很有用”和“带着它旅行”的语境。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说主要供阅读消遣，不是指导具体做法的参考，与“很有用”的语境不符。"}, {"text": "漫画", "is_correct": false, "explanation": "语义：漫画用于娱乐，与“很有用”以及旅行参考的语境不符。"}, {"text": "烂书", "is_correct": false, "explanation": "语域：“烂”是口语且含贬义，与“很有用”的正面评价相矛盾。"}], "explanations": {"指南": "指南：教人具体怎么做的手册，符合“很有用”和“带着它旅行”的语境。", "小说": "语义：小说主要供阅读消遣，不是指导具体做法的参考，与“很有用”的语境不符。", "漫画": "语义：漫画用于娱乐，与“很有用”以及旅行参考的语境不符。", "烂书": "语域：“烂”是口语且含贬义，与“很有用”的正面评价相矛盾。"}, "sentence_index": 0, "correct_answer": "指南"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本指南讲了一个感人的故事。", "explanation": "这里应该用〈小说〉。指南是教人具体怎么做的手册，不讲故事。"}, {"text": "这本指南的歌词很好听。", "explanation": "这里应该用〈歌曲〉。指南是告诉人怎么做的资料，没有歌词，不能用“好听”来形容。"}, {"text": "他的指南是一米八。", "explanation": "这里应该用〈身高〉。指南是告诉人怎么做的资料，不能说有多高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指南", "is_correct": true, "explanation": "指南：教人具体怎么做的手册，符合“照着做”的语境。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是供人阅读的故事，不是可以照着一步一步操作的说明。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“照着”后接的是做法或说明，不能照着感情一步一步做。"}, {"text": "薪水", "is_correct": false, "explanation": "语义：薪水是工资，不是可以照着一步一步操作的说明。"}], "explanations": {"指南": "指南：教人具体怎么做的手册，符合“照着做”的语境。", "小说": "语义：小说是供人阅读的故事，不是可以照着一步一步操作的说明。", "感情": "搭配：“照着”后接的是做法或说明，不能照着感情一步一步做。", "薪水": "语义：薪水是工资，不是可以照着一步一步操作的说明。"}, "sentence_index": 6, "correct_answer": "指南"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都吃指南。", "explanation": "这里应该用〈饼干〉。指南是告诉人怎么做的资料，不能吃。"}, {"text": "妈妈每天洗指南。", "explanation": "这里应该用〈衣服〉。指南是告诉人怎么做的资料，不能洗。"}, {"text": "他打碎了指南。", "explanation": "这里应该用〈花瓶〉。指南是书面资料，不能打碎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去年买了一只新指南。", "corrected_sentence": "我去年买了一本新指南。", "error_description": "量词错误：“只”用于动物或成对的东西，指南是书，应该用量词“本”。正确说法是“一本新指南”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师给我们推荐了一本的新指南。", "corrected_sentence": "老师给我们推荐了一本新指南。", "error_description": "多余的“的”：数量词“一本”与形容词“新”之间不能加“的”，应说“一本新指南”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后置", "is_correct": true, "explanation": "后置：放在后面，与“前置”意思相反。"}, {"text": "保存", "is_correct": false, "explanation": "保存：使东西保持完好，与“前置”不构成反义关系。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃：不再要某物或某做法，与“前置”不构成反义关系。"}, {"text": "收藏", "is_correct": false, "explanation": "收藏：把东西收存起来，与“前置”不构成反义关系。"}], "correct_answer": "后置", "explanations": {"后置": "后置：放在后面，与“前置”意思相反。", "保存": "保存：使东西保持完好，与“前置”不构成反义关系。", "放弃": "放弃：不再要某物或某做法，与“前置”不构成反义关系。", "收藏": "收藏：把东西收存起来，与“前置”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
