INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放在前面。", "primary_collocate": null, "pronunciation": "qián zhì", "ipa": "tɕʰi̯ɛn˧˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "把重要的文件前置，找起来更方便。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，常用的东西要前置。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把最常读的书前置，方便随手拿到。", "target_word": "前置", "complexity_tier": "T3", "furigana": "ぜんち", "sentence_source": "generated"}, {"text": "商店把新产品前置，顾客一进门就能看到。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个句子里的时间词可以前置。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，可以把最重要的内容前置。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市把促销的水果前置，吸引顾客先看到。", "target_word": "前置", "complexity_tier": "T3", "furigana": "ぜんち", "sentence_source": "generated"}, {"text": "她把常用的课本前置，每天最先拿到手边。", "target_word": "前置", "complexity_tier": "T3", "furigana": "ぜんち", "sentence_source": "generated"}, {"text": "请把这几张椅子前置，靠近舞台。", "target_word": "前置", "complexity_tier": "T3", "furigana": "ぜんち", "sentence_source": "generated"}, {"text": "把孩子的座位前置，他就看得更清楚了。", "target_word": "前置", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前置了", "label": "体标（了）"}, {"form": "前置摄像头", "label": "复合"}], "register": "中性", "sense_fingerprint": "前置：把物品或成分放到前面的位置（动词，中性）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置 qiánzhì：把东西放到前面的位置。"}, {"text": "前世", "is_correct": false, "explanation": "声母 sh 与 zh 不同，“前世”指前生。"}, {"text": "前肢", "is_correct": false, "explanation": "qiánzhī（第一声）与 qiánzhì（第四声）声调不同，前肢指动物的前腿。"}, {"text": "前值", "is_correct": false, "explanation": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前值指前一个数值。"}], "explanations": {"前置": "前置 qiánzhì：把东西放到前面的位置。", "前世": "声母 sh 与 zh 不同，“前世”指前生。", "前肢": "qiánzhī（第一声）与 qiánzhì（第四声）声调不同，前肢指动物的前腿。", "前值": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前值指前一个数值。"}, "sentence_index": null, "correct_answer": "前置"}, "level_3": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置：把文件放到前面，方便找到。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”指去掉，与“找起来更方便”矛盾。"}, {"text": "隐藏", "is_correct": false, "explanation": "语义：“隐藏”指藏起来，与“找起来更方便”矛盾。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”指扔掉，与“找起来更方便”的语境矛盾。"}], "explanations": {"前置": "前置：把文件放到前面，方便找到。", "删除": "语义：“删除”指去掉，与“找起来更方便”矛盾。", "隐藏": "语义：“隐藏”指藏起来，与“找起来更方便”矛盾。", "丢弃": "语义：“丢弃”指扔掉，与“找起来更方便”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "前置"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这份合同前置了，已经不算数了。", "explanation": "这里是〈作废〉的意思，但“前置”只表示放到前面或提前，不表示宣布失效。"}, {"text": "他把这份报告前置到了明年才交。", "explanation": "这里是〈延期〉的意思，但“前置”表示提前或放到前面，不表示往后推。"}, {"text": "他把客人的话前置了，完全没听进去。", "explanation": "这里是〈忽略〉的意思，但“前置”只表示放到前面或提前，不表示不予理会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置 qiánzhì：把东西放到前面的位置。"}, {"text": "前职", "is_correct": false, "explanation": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前职指以前的职位。"}, {"text": "前址", "is_correct": false, "explanation": "qiánzhǐ（第三声）与 qiánzhì（第四声）声调不同，前址指原来的地址。"}, {"text": "前翅", "is_correct": false, "explanation": "声母 ch 与 zh 不同，前翅指昆虫的前翅膀。"}], "explanations": {"前置": "前置 qiánzhì：把东西放到前面的位置。", "前职": "qiánzhí（第二声）与 qiánzhì（第四声）声调不同，前职指以前的职位。", "前址": "qiánzhǐ（第三声）与 qiánzhì（第四声）声调不同，前址指原来的地址。", "前翅": "声母 ch 与 zh 不同，前翅指昆虫的前翅膀。"}, "sentence_index": null, "correct_answer": "前置"}, "level_3": {"options": [{"text": "前置", "is_correct": true, "explanation": "前置：把促销的水果放到前面，吸引顾客先看到。"}, {"text": "后置", "is_correct": false, "explanation": "语义：“后置”指放在后面，与“吸引顾客先看到”矛盾。"}, {"text": "撤下", "is_correct": false, "explanation": "语义：“撤下”指拿走，顾客无法先看到，与“吸引顾客先看到”矛盾。"}, {"text": "冷藏", "is_correct": false, "explanation": "搭配：“冷藏”指低温保存，不能用来吸引顾客。"}], "explanations": {"前置": "前置：把促销的水果放到前面，吸引顾客先看到。", "后置": "语义：“后置”指放在后面，与“吸引顾客先看到”矛盾。", "撤下": "语义：“撤下”指拿走，顾客无法先看到，与“吸引顾客先看到”矛盾。", "冷藏": "搭配：“冷藏”指低温保存，不能用来吸引顾客。"}, "sentence_index": 6, "correct_answer": "前置"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们把新品发布会前置到了年底，还没有确定地点。", "explanation": "这里是〈延期〉的意思，但“前置”表示提前或放到前面，不表示往后推。"}, {"text": "老师把我的问题前置了，却完全没有理会。", "explanation": "这里是〈忽略〉的意思，但“前置”表示放到前面或优先处理，不表示不予理会。"}, {"text": "他把旧椅子前置，就是为了扔掉它。", "explanation": "这里是〈丢弃〉的意思，但“前置”只表示放到前面，不表示扔掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把常用的工具了前置，拿起来很方便。", "corrected_sentence": "他把常用的工具前置，拿起来很方便。", "error_description": "错误在“了”：“了”不能放在动词“前置”之前，这里应直接用“前置”，去掉“了”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前没有把书前置了。", "corrected_sentence": "他以前没有把书前置过。", "error_description": "错误是“了”用错了。表示“以前没有……过”的经历，要用“过”，应说“前置过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
