INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种计划，变成法律后大家要遵守。", "primary_collocate": null, "pronunciation": "fǎ àn", "ipa": "fa˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "这个法案变成法律后，人人都要遵守。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新法案规定，开车不能玩手机。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项法案要求工厂少排污水。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民希望政府提出一项禁烟的法案。", "target_word": "法案", "complexity_tier": "T3", "furigana": "ほうあん", "sentence_source": "generated"}, {"text": "法案通过以后，大家都要照着做。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校附近禁止停车的法案通过了。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上学习了这个法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个法案对老人很有帮助。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，新法案下个月正式实施。", "target_word": "法案", "complexity_tier": "T3", "furigana": "ほうあん", "sentence_source": "generated"}, {"text": "他们写了一项关于环保的法案。", "target_word": "法案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "正式", "sense_fingerprint": "法案：变成法律后大家都要遵守的计划（名词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案 fǎ àn：变成法律后大家都要遵守的计划，即听到的词。"}, {"text": "发案", "is_correct": false, "explanation": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。"}, {"text": "翻案", "is_correct": false, "explanation": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。"}, {"text": "犯案", "is_correct": false, "explanation": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。"}, {"text": "伏案", "is_correct": false, "explanation": "fú（第二声）与 fǎ（第三声）韵母与声调不同，fú àn 意思是伏在桌子上写字。"}], "explanations": {"法案": "法案 fǎ àn：变成法律后大家都要遵守的计划，即听到的词。", "发案": "fā（第一声）与 fǎ（第三声）声调不同，fā àn 意思是案件发生。", "翻案": "fān（第一声）与 fǎ（第三声）韵母与声调不同，fān àn 意思是推翻原来的判决。", "犯案": "fàn（第四声）与 fǎ（第三声）韵母与声调不同，fàn àn 意思是作案。", "伏案": "fú（第二声）与 fǎ（第三声）韵母与声调不同，fú àn 意思是伏在桌子上写字。"}, "sentence_index": null, "correct_answer": "法案"}, "level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：变成法律后大家要遵守的计划，符合句意。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不能变成法律，句子说的是立法。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是娱乐活动，不会变成法律，与“人人都要遵守”的语境冲突。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，不能用于说明法律效力的正式语境。"}], "explanations": {"法案": "法案：变成法律后大家要遵守的计划，符合句意。", "雨伞": "语义：雨伞不能变成法律，句子说的是立法。", "游戏": "语义：游戏是娱乐活动，不会变成法律，与“人人都要遵守”的语境冲突。", "玩意儿": "语域：“玩意儿”是口语，不能用于说明法律效力的正式语境。"}, "sentence_index": 0, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的学习法案每天要背十个单词。", "explanation": "这里应该用〈计划〉。法案是变成法律后大家都要遵守的计划，个人的学习安排不会成为法律。"}, {"text": "公司法案规定周末不能加班。", "explanation": "这里应该用〈规定〉。法案要变成法律才有约束力，公司内部的规定不叫法案。"}, {"text": "学校的法案是每周五下午放假。", "explanation": "这里应该用〈安排〉。法案要变成法律才能约束大家，学校的日程安排不是法案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法案", "is_correct": true, "explanation": "法案：变成法律后大家要遵守的计划，符合“课上学习”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“学习”的对象是知识或技能，不能说学习天气。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：课上学习的是知识内容，不能学习一个食堂。"}, {"text": "勾当", "is_correct": false, "explanation": "语域：“勾当”含贬义且是口语，不能用于描述课上学习的内容。"}], "explanations": {"法案": "法案：变成法律后大家要遵守的计划，符合“课上学习”的语境。", "天气": "搭配：“学习”的对象是知识或技能，不能说学习天气。", "食堂": "语义：课上学习的是知识内容，不能学习一个食堂。", "勾当": "语域：“勾当”含贬义且是口语，不能用于描述课上学习的内容。"}, "sentence_index": 6, "correct_answer": "法案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法案教我们怎么用洗衣机。", "explanation": "这里应该用〈手册〉。法案是变成法律后大家要遵守的计划，教人操作方法的应是手册。"}, {"text": "他按照法案弹了一首曲子。", "explanation": "这里应该用〈乐谱〉。法案是变成法律后要遵守的计划，弹奏曲子应依据乐谱。"}, {"text": "我的法案拍得很清楚。", "explanation": "这里应该用〈照片〉。法案是变成法律后要遵守的计划，不能用来拍照。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只法案明年开始生效。", "corrected_sentence": "这项法案明年开始生效。", "error_description": "量词错误：“只”用于动物或成对的东西，法案应该用量词“项”。正确说法是“这项法案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师今天了讲解这项新法案。", "corrected_sentence": "老师今天讲解这项新法案。", "error_description": "错误在“了”：“了”不能放在动词“讲解”之前，去掉“了”即可，应说“今天讲解这项新法案”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
