INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27472, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "如果有人做错了事，大家会问他为什么做错，让他承认错误。", "primary_collocate": null, "pronunciation": "wèn zé", "ipa": "wən˥˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "小明又没交作业，老师要问责他。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "班里的花瓶打碎了，老师开始问责。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队输了比赛，教练当场问责队员。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同事做错了事，经理没有马上问责。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他犯了错，妈妈却没有问责他。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小组任务没完成，组长要问责每个人。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子撒了谎，家长应该问责他。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队友总是迟到，大家决定一起问责他。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟弄坏了我的手机，我要问责他。", "target_word": "问责", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出了错就要问责，不能只说没关系。", "target_word": "问责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "问责过", "label": "体标"}, {"form": "问责了", "label": "体标"}], "register": "中性", "sense_fingerprint": "做错事后被质问并要求承认错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27472, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问责", "is_correct": true, "explanation": "正确。“问责”指因做错事而追问原因、要求承认错误，与“没交作业”的语境吻合。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”是称赞，与“没交作业”的情境相反，不能用于此处。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：“奖励”是对好表现的回报，与未完成作业的情况矛盾。"}, {"text": "讲述", "is_correct": false, "explanation": "配价：“讲述”带的宾语是内容，不直接带“他”这类人作宾语。"}], "explanations": {"问责": "正确。“问责”指因做错事而追问原因、要求承认错误，与“没交作业”的语境吻合。", "表扬": "语义：“表扬”是称赞，与“没交作业”的情境相反，不能用于此处。", "奖励": "语义：“奖励”是对好表现的回报，与未完成作业的情况矛盾。", "讲述": "配价：“讲述”带的宾语是内容，不直接带“他”这类人作宾语。"}, "sentence_index": 0, "correct_answer": "问责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常问责妈妈的照顾，心里一直记着。", "explanation": "这里应该用〈感谢〉。问责是追问过错、要对方认错，不表示感激；表达谢意要用感谢。"}, {"text": "大家一直问责他的热心。", "explanation": "这里应该用〈称赞〉。称赞是夸奖好的品质，可以用于热心；问责是追问做错的事，不能用来称赞。"}, {"text": "全班同学一起问责新同学的到来。", "explanation": "这里应该用〈欢迎〉。欢迎是热情迎接，可以用于到来；问责是追问做错的事，不能表示迎接。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27472, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问责", "is_correct": true, "explanation": "正确。“问责”指追问撒谎者的过错、要求其承认，与“撒了谎”的语境吻合。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”是称赞，与“撒了谎”的情境相反，不能用于此处。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示谢意，孩子撒谎并不值得感激，句意矛盾。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”针对受损的一方，不能用来对撒谎的孩子表示处理。"}], "explanations": {"问责": "正确。“问责”指追问撒谎者的过错、要求其承认，与“撒了谎”的语境吻合。", "赞美": "语义：“赞美”是称赞，与“撒了谎”的情境相反，不能用于此处。", "感激": "语义：“感激”表示谢意，孩子撒谎并不值得感激，句意矛盾。", "赔偿": "搭配：“赔偿”针对受损的一方，不能用来对撒谎的孩子表示处理。"}, "sentence_index": 6, "correct_answer": "问责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈问责摔倒的弟弟。", "explanation": "这里应该用〈安慰〉。问责是追究做错的事，不能用于安抚摔倒的人。"}, {"text": "学校已经问责了家长会的时间。", "explanation": "这里应该用〈通知〉。通知是告知消息，可以用于时间；问责是追问做错的事，不能以“时间”作宾语。"}, {"text": "大家问责他的好成绩。", "explanation": "这里应该用〈祝贺〉。祝贺是庆贺、道喜，可以用于好成绩；问责是追问过错，不能用于庆贺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27472, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师发现小明没交作业，已经了问责他。", "corrected_sentence": "老师发现小明没交作业，已经问责他。", "error_description": "错误：“了”放在动词“问责”之前，成了“了问责”，不合语法。正确应为“已经问责他”，“了”不能放在动词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27472, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长又一次迟到，大家决定问责过他。", "corrected_sentence": "班长又一次迟到，大家决定问责他。", "error_description": "错误：“决定”表示将来的打算，“问责过”用的是经历体，与将来的打算不符。正确应为“决定问责他”，动词后不加“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走动，与“接受”不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发声演唱，与“接受”不构成反义。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“接受”不构成反义。"}], "correct_answer": "拒绝", "explanations": {"拒绝": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。", "散步": "“散步”指随意走动，与“接受”不构成反义。", "唱歌": "“唱歌”指发声演唱，与“接受”不构成反义。", "清洗": "“清洗”指用水去除污物，与“接受”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拒绝", "is_correct": true, "explanation": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”指在水中运动，与“接受”不构成反义。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“接受”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把东西理顺、归位，与“接受”不构成反义。"}], "correct_answer": "拒绝", "explanations": {"拒绝": "正确：“拒绝”与“接受”构成反义，表示不同意并不收下。", "游泳": "“游泳”指在水中运动，与“接受”不构成反义。", "观察": "“观察”指仔细看，与“接受”不构成反义。", "整理": "“整理”指把东西理顺、归位，与“接受”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人给你东西，你拿过来，说谢谢。", "primary_collocate": null, "pronunciation": "jiē shòu", "ipa": "tɕjɛ˥ ʂoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "她笑着接受了朋友的礼物。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你送的花很漂亮，我接受了，谢谢你。", "target_word": "接受", "complexity_tier": "T3", "furigana": "Nǐ sòng de huā hěn piàoliang, wǒ jiēshòu le, xièxie nǐ.", "sentence_source": "generated"}, {"text": "小明接受了老师送的书。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶不愿意接受我们的钱。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他接受了生日礼物，对大家说谢谢。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小礼物请你接受。", "target_word": "接受", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "朋友给我一杯茶，我高兴地接受了。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人接受了主人送的水果。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从来不接受别人的东西。", "target_word": "接受", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我接受过同学送的小花。", "target_word": "接受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "接受了", "label": "体标"}, {"form": "接受过", "label": "体标"}, {"form": "接受着", "label": "体标"}, {"form": "接受者", "label": "复合"}], "register": "中性", "sense_fingerprint": "别人送东西给你，你收下并道谢", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '248f5714-59ca-4c41-94f7-b47c7a28fb77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示收下别人送的东西，与“礼物”搭配，符合“笑着”的语气。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”用于言论、文章，不能用于礼物。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能说“批评朋友的礼物”。"}, {"text": "指责", "is_correct": false, "explanation": "搭配：“指责”的对象是人或行为，不能说“指责朋友的礼物”。"}], "explanations": {"接受": "正确：“接受”表示收下别人送的东西，与“礼物”搭配，符合“笑着”的语气。", "发表": "搭配：“发表”用于言论、文章，不能用于礼物。", "批评": "搭配：“批评”的对象是人或行为，不能说“批评朋友的礼物”。", "指责": "搭配：“指责”的对象是人或行为，不能说“指责朋友的礼物”。"}, "sentence_index": 0, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个卫星接受了一段新的信号。", "explanation": "这里应该用〈接收〉。接受指同意收下别人送的东西或意见；接收信号、电波要用接收。"}, {"text": "妈妈接受了一封远方寄来的信。", "explanation": "这里应该用〈收到〉。接受指同意收下别人送的东西；收信件要用收到。"}, {"text": "我在商店接受了一件新衣服，花了两百块。", "explanation": "这里应该用〈买〉。接受指同意收下别人给的东西，不能用来说花钱购买；在商店花钱买东西要用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接受", "is_correct": true, "explanation": "正确：“接受”表示高兴地收下别人送的东西，符合句意。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”表示拒绝或躲开，与“高兴地”矛盾。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”指打破器物，与“高兴地收下”的情境不符。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示想不起来，与“高兴地收下茶”的情境不符。"}], "explanations": {"接受": "正确：“接受”表示高兴地收下别人送的东西，符合句意。", "推开": "语义：“推开”表示拒绝或躲开，与“高兴地”矛盾。", "摔碎": "语义：“摔碎”指打破器物，与“高兴地收下”的情境不符。", "忘记": "语义：“忘记”表示想不起来，与“高兴地收下茶”的情境不符。"}, "sentence_index": 6, "correct_answer": "接受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他接受了那间乱糟糟的房间。", "explanation": "这里应该用〈收拾〉。接受指同意收下别人送的东西；整理房间要用收拾。"}, {"text": "学校接受了一场音乐会。", "explanation": "这里应该用〈举办〉。接受指同意收下别人送的东西；组织音乐会要用举办。"}, {"text": "我们接受了整个教室。", "explanation": "这里应该用〈打扫〉。接受指同意收下别人送的东西；清理教室要用打扫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她会接受了朋友的礼物。", "corrected_sentence": "她会接受朋友的礼物。", "error_description": "“会”表示将来或可能，不能与“了”同用；“接受”后不加“了”。正确形式为“她会接受朋友的礼物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不接受过别人的礼物。", "corrected_sentence": "我从来没接受过别人的礼物。", "error_description": "否定词错误：表示从未有过某种经历，“过”前应用“没”，不能用“不”。正确形式为“从来没接受过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11875eb6-5269-4e0d-a662-5715d3f338ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
