INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能证明一件事是真的东西。", "primary_collocate": null, "pronunciation": "zhèng jù", "ipa": "ʈʂɤŋ˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "你说他撒谎，有什么证据吗？", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机里的聊天记录就是证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈想知道真相，可是没有证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我拿不出证据，所以没人相信我。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他丢了钱包，监控录像是最好的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上的脚印是他来过的证据。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张发票可以当作证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，说话要有证据。", "target_word": "证据", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家都想看到你说的证据。", "target_word": "证据", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着拿出了一份证据。", "target_word": "证据", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "證據", "label": "繁体"}], "register": "中性", "sense_fingerprint": "证据|名词|能证明一件事是真的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deaa3fc3-7c1a-43a4-81dd-1b732cf27d0b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明一件事是真的东西。"}, {"text": "政局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。"}, {"text": "正路", "is_correct": false, "explanation": "lù 与 jù 声母不同（l／j），意思是正确的道路。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}], "explanations": {"证据": "证据：zhèng jù，指能证明一件事是真的东西。", "政局": "jú（第二声）与 jù（第四声）声调不同，意思是政治局势。", "正路": "lù 与 jù 声母不同（l／j），意思是正确的道路。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“有什么证据吗”询问对方能否拿出证明撒谎的东西，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“撒谎”无关，不能用来质问对方能否证明撒谎。"}, {"text": "香味", "is_correct": false, "explanation": "语义：“香味”指气味，与质问对方撒谎时要求拿出的证明无关。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”不能作为证明撒谎的东西，“有什么脾气吗”搭配不当。"}], "explanations": {"证据": "“有什么证据吗”询问对方能否拿出证明撒谎的东西，符合句意。", "颜色": "语义：“颜色”与“撒谎”无关，不能用来质问对方能否证明撒谎。", "香味": "语义：“香味”指气味，与质问对方撒谎时要求拿出的证明无关。", "脾气": "搭配：“脾气”不能作为证明撒谎的东西，“有什么脾气吗”搭配不当。"}, "sentence_index": 0, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他拿出了一份出生证据。", "explanation": "这里应该用〈证明〉。出生证明是官方开具的文件；证据指证明事实的材料，不能说“出生证据”。"}, {"text": "他许下了一个证据。", "explanation": "这里应该用〈愿望〉。许下的是愿望，证据是证明事实的材料，不能被“许下”。"}, {"text": "他讲了一个证据，大家都笑了。", "explanation": "这里应该用〈笑话〉。讲的是能让人发笑的笑话，证据不能用来逗人笑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "证据", "is_correct": true, "explanation": "证据：zhèng jù，指能证明一件事是真的东西。"}, {"text": "整句", "is_correct": false, "explanation": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。"}, {"text": "正数", "is_correct": false, "explanation": "shù 与 jù 声母不同（sh／j），意思是大于零的数。"}, {"text": "正序", "is_correct": false, "explanation": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}], "explanations": {"证据": "证据：zhèng jù，指能证明一件事是真的东西。", "整句": "zhěng（第三声）与 zhèng（第四声）声调不同，意思是完整的句子。", "正数": "shù 与 jù 声母不同（sh／j），意思是大于零的数。", "正序": "xù 与 jù 声母不同（x／j），意思是正常的顺序。"}, "sentence_index": null, "correct_answer": "证据"}, "level_3": {"options": [{"text": "证据", "is_correct": true, "explanation": "“当作证据”指发票能作为证明事实的材料，符合句意。"}, {"text": "食物", "is_correct": false, "explanation": "语义：发票不能当作食物来吃，与发票的性质相冲突。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“当作”后接“歌曲”不通，发票不能被当作歌曲。"}, {"text": "座位", "is_correct": false, "explanation": "语义：发票不能用来坐，与句子所说的用途无关。"}], "explanations": {"证据": "“当作证据”指发票能作为证明事实的材料，符合句意。", "食物": "语义：发票不能当作食物来吃，与发票的性质相冲突。", "歌曲": "搭配：“当作”后接“歌曲”不通，发票不能被当作歌曲。", "座位": "语义：发票不能用来坐，与句子所说的用途无关。"}, "sentence_index": 6, "correct_answer": "证据"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这份证据当成生日祝福送给了朋友。", "explanation": "这里应该用〈祝福〉之类的心意。送给朋友的可以是祝福，证据是证明事实的材料，不能当作祝福送人。"}, {"text": "他向我表达了证据。", "explanation": "这里应该用〈歉意〉。能被表达的是歉意、感情，证据不能被“表达”。"}, {"text": "他露出了证据。", "explanation": "这里应该用〈笑容〉。露出的是表情，证据不是表情，不能“露出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们终于找了到证据。", "corrected_sentence": "我们终于找到了证据。", "error_description": "“到”是“找”的结果补语，“了”应放在补语之后，应说“找到了证据”，不能说“找了到证据”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只证据很重要。", "corrected_sentence": "这份证据很重要。", "error_description": "错误：“只”不能用来计数“证据”，证据通常用“条”“份”等量词。应改为“这份证据”。正确的说法是：这份证据很重要。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fff22ad-c39a-4654-ac73-b7d870499c6f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
