INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "跑在最前面，别人在后面追。", "primary_collocate": null, "pronunciation": "lǐng xiān", "ipa": "liŋ˨˩ ɕjɛn˥", "syllable_count": 2, "sentences": [{"text": "比赛开始后，他很快就领先了。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小李一直领先，别的人都在后面。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑到第三圈时，她领先了所有人。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的车领先第二名一百米。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在最后一圈还是领先的。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那匹白马领先跑了很远。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥起跑很快，一路领先。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他领先后面的人二十米。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骑车上山时，姐姐总是领先我。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在谁领先？穿红衣服的那个人。", "target_word": "领先", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "领先了", "label": "完成体（了）"}, {"form": "领先过", "label": "经历体（过）"}, {"form": "一路领先", "label": "复合"}, {"form": "領先", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赛跑、骑车等比赛中位置在最前面，别人落在后面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示比赛中跑在最前面，与“比赛开始后”“很快就”的语境相符。"}, {"text": "发表", "is_correct": false, "explanation": "配价：“发表”需要宾语（如意见、文章），此处缺少宾语，句子不完整。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”与比赛开始后的语境不符。"}, {"text": "装饰", "is_correct": false, "explanation": "配价：“装饰”需要宾语，此处缺少宾语，句子不完整。"}], "explanations": {"领先": "正确：“领先”表示比赛中跑在最前面，与“比赛开始后”“很快就”的语境相符。", "发表": "配价：“发表”需要宾语（如意见、文章），此处缺少宾语，句子不完整。", "退休": "语义：“退休”与比赛开始后的语境不符。", "装饰": "配价：“装饰”需要宾语，此处缺少宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快就领先了老师的意思。", "explanation": "这里应该用〈领会〉。领先指跑在前面、比别人更快，理解意思要说领会。"}, {"text": "这个月我的体重领先了三公斤。", "explanation": "这里应该用〈增加〉。领先用于比赛中的前后位置，体重的增加要说增加。"}, {"text": "这个地方的风景很领先，我们都很喜欢。", "explanation": "这里应该用〈美丽〉。领先不用于描述风景，风景优美要说美丽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "领先", "is_correct": true, "explanation": "正确：“领先”表示位置靠前，与“起跑很快”“一路”的语境一致。"}, {"text": "落后", "is_correct": false, "explanation": "语义：“落后”与“起跑很快”的语境相矛盾。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“一路”后接“停止”不自然，不符合常规表达。"}, {"text": "发愁", "is_correct": false, "explanation": "语义：“发愁”与“起跑很快”的积极语境不符。"}], "explanations": {"领先": "正确：“领先”表示位置靠前，与“起跑很快”“一路”的语境一致。", "落后": "语义：“落后”与“起跑很快”的语境相矛盾。", "停止": "搭配：“一路”后接“停止”不自然，不符合常规表达。", "发愁": "语义：“发愁”与“起跑很快”的积极语境不符。"}, "sentence_index": 6, "correct_answer": "领先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他领先了自己的极限，变得更强。", "explanation": "这里应该用〈超越〉。领先指位置靠前，突破自己的极限要说超越。"}, {"text": "他领先了一杯水，一口就喝完了。", "explanation": "这里应该用〈喝〉。领先指位置靠前，喝水要说喝，不能说“领先水”。"}, {"text": "妈妈领先了一双新鞋。", "explanation": "这里应该用〈购买〉。领先不表示买东西，买鞋要说购买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在比赛开始时一路了领先，最后赢得了冠军。", "corrected_sentence": "他在比赛开始时一路领先，最后赢得了冠军。", "error_description": "错误形式：“一路了领先”。正确形式：“一路领先”。“了”是完成体标记，不能插在状语“一路”与动词“领先”之间，删去即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "骑车上山时，他领先我了二十米。", "corrected_sentence": "骑车上山时，他领先了我二十米。", "error_description": "错误形式：“领先我了二十米”。正确形式：“领先了我二十米”。“了”应紧跟动词“领先”，表示动作完成，位置放错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
