INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西坏了或者人少了。", "primary_collocate": null, "pronunciation": "zhé sǔn", "ipa": "ʈʂɤ˧˥ suən˨˩˦", "syllable_count": 2, "sentences": [{"text": "路上太颠，箱子里的杯子折损了几个。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山火之后，村里的树折损了不少。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队有人受伤，队伍折损了三个人。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩具用得太多，折损得很快。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家时小心点，别让东西折损。", "target_word": "折损", "complexity_tier": "T3", "furigana": "bānjiā shí xiǎoxīn diǎn, bié ràng dōngxi zhésǔn。", "sentence_source": "generated"}, {"text": "台风过后，果园里折损了很多苹果树。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次爬山，我们队没有折损一个人。", "target_word": "折损", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包太旧，里面的书也折损了。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子玩得太用力，玩具折损了。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂里机器老了，每月都有折损。", "target_word": "折损", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "折损了", "label": "体标"}, {"form": "折损过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西坏掉或人员减少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "折损", "is_correct": true, "explanation": "正确：“折损”指东西损坏或减少，与“路上太颠”造成的破损语境相符。"}, {"text": "修复", "is_correct": false, "explanation": "语义：“修复”指修好，与“路上太颠”导致杯子损坏的语境不符。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示数量变多，与杯子被颠坏的语境相悖。"}, {"text": "装满", "is_correct": false, "explanation": "搭配：“装满”要求以容器作对象，“杯子”不能被“装满”后带数量宾语，句子不通。"}], "explanations": {"折损": "正确：“折损”指东西损坏或减少，与“路上太颠”造成的破损语境相符。", "修复": "语义：“修复”指修好，与“路上太颠”导致杯子损坏的语境不符。", "增加": "语义：“增加”表示数量变多，与杯子被颠坏的语境相悖。", "装满": "搭配：“装满”要求以容器作对象，“杯子”不能被“装满”后带数量宾语，句子不通。"}, "sentence_index": 0, "correct_answer": "折损"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种香味折损得很快。", "explanation": "这里应该用〈消失〉。折损指东西的损耗，香味的散去要说消失。"}, {"text": "我们在路上折损了很多时间。", "explanation": "这里应该用〈浪费〉。折损不用于时间的消耗，时间白白耗去要说浪费。"}, {"text": "气温折损了五度。", "explanation": "这里应该用〈下降〉。折损不用于温度的降低，气温降低要说下降。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "折损", "is_correct": true, "explanation": "正确：“折损”指人员伤亡，与“没有……一个人”搭配，表示没有人员损失。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”针对物品，不能用于人。"}, {"text": "擦亮", "is_correct": false, "explanation": "搭配：“擦亮”针对物体表面，不能用于人。"}, {"text": "加热", "is_correct": false, "explanation": "语义：“加热”指改变温度，与登山队人员的语境不符。"}], "explanations": {"折损": "正确：“折损”指人员伤亡，与“没有……一个人”搭配，表示没有人员损失。", "修理": "搭配：“修理”针对物品，不能用于人。", "擦亮": "搭配：“擦亮”针对物体表面，不能用于人。", "加热": "语义：“加热”指改变温度，与登山队人员的语境不符。"}, "sentence_index": 6, "correct_answer": "折损"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他折损了自信心。", "explanation": "这里应该用〈丧失〉。折损不用于自信的失去，自信心的失去要说丧失。"}, {"text": "这些噪音折损了他的注意力。", "explanation": "这里应该用〈分散〉。折损不用于注意力的转移，注意力被牵走要说分散。"}, {"text": "这个月我的体重折损了三公斤。", "explanation": "这里应该用〈减轻〉。折损指东西坏了或人少了，体重的减少要说减轻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "货车颠得厉害，车里的瓶子折损得好几个。", "corrected_sentence": "货车颠得厉害，车里的瓶子折损了好几个。", "error_description": "错误形式：“折损得好几个”。正确形式：“折损了好几个”。“得”后要接描述程度的成分，“好几个”是数量，不能作补语，应用“了”表示已经发生。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台老旧的机器每个月都会折损过一些零件。", "corrected_sentence": "这台老旧的机器每个月都会折损一些零件。", "error_description": "错误形式：“折损过”。正确形式：“折损”。“过”表示经历过，与“每个月都会”的习惯性语境冲突，应去掉“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
