INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做错事的人要受到批评或惩罚。", "primary_collocate": null, "pronunciation": "zhuī zé", "ipa": "ʈʂweɪ̯˥ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "员工做错了事，主管没有马上追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他隐瞒了工作中的错误，领导决定追责。", "target_word": "追责", "complexity_tier": "T3", "furigana": "ついせき", "sentence_source": "generated"}, {"text": "他把文件弄丢了，经理要追责他。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事的人，迟早会有人来追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说，这次先不追责，下次不能再错了。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都怕领导追责，所以不敢说实话。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主动承认了错误，学校没有追责他。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是谁的错，公司一定会追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们打破了窗户，老师决定不追责。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "错误已经发生了，追责也没有用。", "target_word": "追责", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追责了", "label": "体标（了）"}, {"form": "追责过", "label": "体标（过）"}], "register": "正式", "sense_fingerprint": "追责：让做错事的人受到批评或惩罚（动词，正式）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abff23b1-3793-49d8-86f2-32e8f3c86884') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追责", "is_correct": true, "explanation": "追责：对做错事的人追究责任，符合句子语境。"}, {"text": "追求", "is_correct": false, "explanation": "配价：“追求”需要带目标宾语，此处语义不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”指不接受，与“没有马上追责”的语境不合，不能替代“追责”。"}, {"text": "追悼", "is_correct": false, "explanation": "语义：“追悼”指悼念死者，与孩子做错事的语境不合。"}], "explanations": {"追责": "追责：对做错事的人追究责任，符合句子语境。", "追求": "配价：“追求”需要带目标宾语，此处语义不通。", "拒绝": "语义：“拒绝”指不接受，与“没有马上追责”的语境不合，不能替代“追责”。", "追悼": "语义：“追悼”指悼念死者，与孩子做错事的语境不合。"}, "sentence_index": 0, "correct_answer": "追责"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他帮老师搬了一整天的书，老师决定追责他。", "explanation": "这里应该用〈表扬〉。追责只用于做错事的人，帮忙的人应当表扬。"}, {"text": "孩子哭得很伤心，爸爸赶紧去追责他。", "explanation": "这里应该用〈安慰〉。追责针对做错事的人，伤心的孩子需要安慰。"}, {"text": "他认真复习，成绩进步很大，老师要追责他的努力。", "explanation": "这里应该用〈肯定〉。追责针对错误，不能用于努力和进步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追责", "is_correct": true, "explanation": "追责：学校对他的错误没有追究责任，符合“主动承认了错误”的语境。"}, {"text": "追讨", "is_correct": false, "explanation": "搭配：“追讨”用于债务或财物，不能用于追究学生的责任。"}, {"text": "追捕", "is_correct": false, "explanation": "语义：“追捕”指追拿罪犯，与学校对学生的处理不合。"}, {"text": "追悔", "is_correct": false, "explanation": "语义：“追悔”指当事人自己后悔，不能用来指学校的处理。"}], "explanations": {"追责": "追责：学校对他的错误没有追究责任，符合“主动承认了错误”的语境。", "追讨": "搭配：“追讨”用于债务或财物，不能用于追究学生的责任。", "追捕": "语义：“追捕”指追拿罪犯，与学校对学生的处理不合。", "追悔": "语义：“追悔”指当事人自己后悔，不能用来指学校的处理。"}, "sentence_index": 6, "correct_answer": "追责"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员救助了被困的老人，大家都要追责他。", "explanation": "这里应该用〈表彰〉。救人的消防员立了功，应当表彰，不能追责。"}, {"text": "他一直照顾我，我要追责他。", "explanation": "这里应该用〈感谢〉。追责针对过错，对照顾自己的人应当感谢。"}, {"text": "考试没考好的同学很沮丧，老师决定追责他。", "explanation": "这里应该用〈鼓励〉。沮丧的同学没有犯错，应当鼓励而不是追责。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他撒了谎，老师决定追责了他。", "corrected_sentence": "他撒了谎，老师决定追责他。", "error_description": "错误在“追责”后面加了“了”。“决定”后面的动词不能带“了”，应说“决定追责他”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有追责了那个孩子。", "corrected_sentence": "他没有追责那个孩子。", "error_description": "错误在“追责”后面加了“了”。“没有”否定的动作不能带“了”，应说“没有追责那个孩子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d751c61-8de1-4572-a747-dfff08cf06a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
