INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人对你的评价很好、很正面。", "primary_collocate": null, "pronunciation": "shēng yù", "ipa": "ʂɤŋ˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "他帮助过很多人，在村里声誉很好。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好声誉要靠多年努力才能得到。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭馆做菜干净，声誉很不错。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她诚实守信，在朋友中声誉很高。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要爱护自己的声誉。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师声誉很好，家长们都信任他。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说谎会让你失去好声誉。", "target_word": "声誉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家小店的声誉是慢慢积累起来的。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了班级的声誉，大家都认真打扫。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声誉很好，大家都愿意和他合作。", "target_word": "声誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "别人对你的好评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声誉", "is_correct": true, "explanation": "正确。“在村里声誉很好”表示他在村里获得了别人的好评，与前句“帮助过很多人”相符。"}, {"text": "债务", "is_correct": false, "explanation": "语义：债务是负担，与“很好”不能搭配，句意相反。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是负面的声响，不能用“很好”来评价，句意不通。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：“字体”指字的形式，不能用来评价一个人在村里的整体情况。"}], "explanations": {"声誉": "正确。“在村里声誉很好”表示他在村里获得了别人的好评，与前句“帮助过很多人”相符。", "债务": "语义：债务是负担，与“很好”不能搭配，句意相反。", "噪音": "语义：噪音是负面的声响，不能用“很好”来评价，句意不通。", "字体": "搭配：“字体”指字的形式，不能用来评价一个人在村里的整体情况。"}, "sentence_index": 0, "correct_answer": "声誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个礼堂的声誉很大，后排也听得见。", "explanation": "这里应该用〈声音〉。声誉指社会评价，不指音量；说声音很大才表示音量。"}, {"text": "学校今天发表了重要声誉。", "explanation": "这里应该用〈声明〉。声明是公开表态的文字，可以发表；声誉是社会评价，不能说“发表”。"}, {"text": "他在班里的声誉很靠前。", "explanation": "这里应该用〈名次〉。名次指排列的位置，可以靠前；声誉是他人的评价，不能说靠前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "声誉", "is_correct": true, "explanation": "正确。“失去好声誉”指失去别人的好评，与“说谎”的后果相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“失去好颜色”不合理，颜色不是可以因说谎而失去的好评价。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会因说谎而“失去好”，句意荒谬。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“失去好”常搭配人际、机会、名誉等，“温度”不能与之搭配。"}], "explanations": {"声誉": "正确。“失去好声誉”指失去别人的好评，与“说谎”的后果相符。", "颜色": "语义：“失去好颜色”不合理，颜色不是可以因说谎而失去的好评价。", "年龄": "语义：年龄不会因说谎而“失去好”，句意荒谬。", "温度": "搭配：“失去好”常搭配人际、机会、名誉等，“温度”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "声誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院的声誉服务很好，患者都愿意来。", "explanation": "这里应该用〈生育〉。二者同音，但生育指生孩子相关的服务，声誉指社会评价，这里不能说声誉服务。"}, {"text": "这位男高音的声誉很宽。", "explanation": "这里应该用〈声域〉。二者同音，但声域指能唱的音高范围，声誉指社会评价，不能说“宽”。"}, {"text": "普通话的声誉很难掌握。", "explanation": "这里应该用〈声调〉。声调指音节的高低变化，是普通话的学习难点；声誉指社会评价，不能说难掌握。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她多年来诚实经营，在街坊中有一位很好的声誉。", "corrected_sentence": "她多年来诚实经营，在街坊中有一种很好的声誉。", "error_description": "错误：“声誉”前的量词用了“位”。“位”用于人，不能修饰抽象的“声誉”；应改为“一种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家书店开了十年，在读者中赢得了很好地声誉。", "corrected_sentence": "这家书店开了十年，在读者中赢得了很好的声誉。", "error_description": "错误：修饰名词“声誉”的“很好”之后用了“地”。“地”用于状语，这里作定语，应用“的”。正确为“很好的声誉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
