INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27486, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细地看，检查对不对。", "primary_collocate": null, "pronunciation": "shěn chá", "ipa": "ʂən˨˩ ʈʂʰa˧˥", "syllable_count": 2, "sentences": [{"text": "交作业以前，你要自己审查一遍。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈仔细审查了我的数学作业。", "target_word": "审查", "complexity_tier": "T3", "furigana": "Māma zǐxì shěnchá le wǒ de shùxué zuòyè.", "sentence_source": "generated"}, {"text": "他把考卷又审查了一次。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板审查完账本，点了点头。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请帮我审查一下这个表格。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥认真审查每一个答案。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门前，我仔细审查了一下护照。", "target_word": "审查", "complexity_tier": "T3", "furigana": "Chūmén qián, wǒ zǐxì shěnchá le yíxià hùzhào.", "sentence_source": "generated"}, {"text": "老师要我们互相审查作文。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你先审查，看看有没有错字。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她审查着名单，一个一个地看。", "target_word": "审查", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "审查了", "label": "完成体（了）"}, {"form": "审查着", "label": "持续体（着）"}, {"form": "审查过", "label": "经历体（过）"}], "register": "书面", "sense_fingerprint": "认真地看一遍，检查有没有错误", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27486, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "审查", "is_correct": true, "explanation": "“审查”指认真检查作业，与“交作业以前，你要自己……一遍”搭配。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热或燃烧，作业不能被烧。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”多用于衣物、餐具，不能说“洗作业”来表示检查。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“作业”作宾语。"}], "explanations": {"审查": "“审查”指认真检查作业，与“交作业以前，你要自己……一遍”搭配。", "烧": "语义：“烧”指用火加热或燃烧，作业不能被烧。", "洗": "搭配：“洗”多用于衣物、餐具，不能说“洗作业”来表示检查。", "睡": "配价：“睡”是不及物动词，不能带“作业”作宾语。"}, "sentence_index": 0, "correct_answer": "审查"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生审查了我的心脏。", "explanation": "这里应该用〈检查〉。审查用于文件、材料、申请等，检查身体、器官要说“检查”。"}, {"text": "我们审查了那轮夕阳。", "explanation": "这里应该用〈观赏〉。观赏夕阳是欣赏景色，审查指仔细看对不对，不用于景色。"}, {"text": "他审查了一下花香。", "explanation": "这里应该用〈闻〉。闻花香是用鼻子感受气味，审查只用于核对文件或标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27486, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "审查", "is_correct": true, "explanation": "“审查”指仔细核对护照，与“出门前，我仔细……了一下护照”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪，护照不能被煮。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能直接带“护照”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面应接歌曲，不能接证件。"}], "explanations": {"审查": "“审查”指仔细核对护照，与“出门前，我仔细……了一下护照”搭配。", "煮": "语义：“煮”是烹饪，护照不能被煮。", "笑": "配价：“笑”是不及物动词，不能直接带“护照”作宾语。", "唱": "搭配：“唱”后面应接歌曲，不能接证件。"}, "sentence_index": 6, "correct_answer": "审查"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶审查了被子。", "explanation": "这里应该用〈晒〉。晒被子是晾干，审查只用于核对资料或标准。"}, {"text": "他审查了桌子。", "explanation": "这里应该用〈擦〉。擦桌子是清洁，审查不能用于清洁。"}, {"text": "猫审查了老鼠。", "explanation": "这里应该用〈捉〉。猫捉老鼠是抓住，审查指核对，不能用于抓动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27486, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师仔细审查得每一份试卷。", "corrected_sentence": "老师仔细审查了每一份试卷。", "error_description": "错误：“得”后面要接补语，这里“审查”后直接接宾语，没有补语，句子不完整。应用“了”表示完成。正确是“审查了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27486, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计审查了完所有的发票。", "corrected_sentence": "会计审查完了所有的发票。", "error_description": "错误：“了”插在动词“审查”和结果补语“完”之间。结果补语应紧跟动词，“了”放在补语之后，即“审查完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
