INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方管的范围，比如这个警察管哪块地方，这就是他管的辖区。", "primary_collocate": null, "pronunciation": "xiá qū", "ipa": "ɕja˧˥ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这块地方是李警察的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察要熟悉自己的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街不属于我们的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的辖区里住着很多老人。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家就在这个派出所的辖区。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在辖区里走了一圈。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辖区太大，警察忙不过来。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察对辖区的每条路都很熟。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出了辖区，他就不能管了。", "target_word": "辖区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的警察第一天就走遍了辖区。", "target_word": "辖区", "complexity_tier": "T3", "furigana": "xīnlái de jǐngchá dì yī tiān jiù zǒubiàn le xiáqū", "sentence_source": "generated"}], "morphological_forms": [{"form": "轄區", "label": "繁体"}], "register": "正式", "sense_fingerprint": "警察等负责管理的那块地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宠物", "is_correct": false, "explanation": "语义：宠物是动物，不能说“这块地方是李警察的宠物”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人的身体特征，不能指一块地方。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区”指警察负责管理的地方，与“李警察的”搭配，句子成立。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”可以属于人，但不能用来指一块地方。"}], "explanations": {"宠物": "语义：宠物是动物，不能说“这块地方是李警察的宠物”。", "体重": "体貌：“体重”是人的身体特征，不能指一块地方。", "辖区": "“辖区”指警察负责管理的地方，与“李警察的”搭配，句子成立。", "工资": "搭配：“工资”可以属于人，但不能用来指一块地方。"}, "sentence_index": 0, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的这只辖区里住着很多老人。", "explanation": "这里应该用〈片〉。辖区是一片范围，“只”多用于动物，不能说“这只辖区”。"}, {"text": "他的辖区是一位老人。", "explanation": "这里不能说“辖区是一位老人”。辖区是管辖的地方，不是人，应说“辖区里住着一位老人”。"}, {"text": "他的辖区吃了三碗饭。", "explanation": "这里应该用〈人〉。辖区是地方，不会吃饭，“吃饭”的主语应是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "字体", "is_correct": false, "explanation": "语义：字体太大与警察忙不过来无关，句子说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步太大与警察忙不过来无关，句子说不通。"}, {"text": "辖区", "is_correct": true, "explanation": "“辖区太大”说明管理范围过大，警察因此忙不过来，句子成立。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”是人的体形，不能说它太大导致警察忙不过来。"}], "explanations": {"字体": "语义：字体太大与警察忙不过来无关，句子说不通。", "脚步": "语义：脚步太大与警察忙不过来无关，句子说不通。", "辖区": "“辖区太大”说明管理范围过大，警察因此忙不过来，句子成立。", "身材": "体貌：“身材”是人的体形，不能说它太大导致警察忙不过来。"}, "sentence_index": 6, "correct_answer": "辖区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新来的警察第一天就成了辖区。", "explanation": "这里应该用〈民警〉。辖区是一片管理范围，不是人；“成了”后应接职务或身份，如“成了一名民警”。"}, {"text": "新来的警察第一天就喝光了辖区。", "explanation": "这里应该用〈饮料〉。辖区是地方，不能喝；“喝光”的对象应是饮料，如“喝光了饮料”。"}, {"text": "新来的警察第一天就抱起了辖区。", "explanation": "这里应该用〈箱子〉。辖区是一片范围，不能抱；“抱起”的对象应是具体的东西，如“抱起了箱子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条辖区有三条主要街道。", "corrected_sentence": "这片辖区有三条主要街道。", "error_description": "量词错误：辖区是一片范围，应用“片”，不能用“条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "辖区的内有一座公园。", "corrected_sentence": "辖区内有一座公园。", "error_description": "多余的“的”：方位词“内”前不加“的”，应说“辖区内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
