INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "大家相信某个人或某个机构的程度。", "primary_collocate": null, "pronunciation": "gōng xìn lì", "ipa": "kʊŋ˥ ɕin˥˩ li˥˩", "syllable_count": 3, "sentences": [{"text": "这位医生很有公信力，大家都相信他。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是说谎，已经没有公信力了。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公开信息可以增强公司的公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站的公信力不太高。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察的公信力来自公平做事。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻要真实，才有公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家银行的公信力很强。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做错事后，他的公信力下降了。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校用这种方法提高了公信力。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说，这个节目的公信力最高。", "target_word": "公信力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人们对某人或某机构信任的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24dea6c3-edc9-4528-8989-eb898e1c4897') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“很有公信力”说医生被大家相信，与后一分句“大家都相信他”一致。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：“很有”一般不接“数量”，数量应说“很多”。"}, {"text": "长度", "is_correct": false, "explanation": "语义：长度说的是事物的尺寸，与医生被相信的程度无关。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：海拔是地面的高度，不能用来形容人，句意不通。"}], "explanations": {"公信力": "“很有公信力”说医生被大家相信，与后一分句“大家都相信他”一致。", "数量": "搭配：“很有”一般不接“数量”，数量应说“很多”。", "长度": "语义：长度说的是事物的尺寸，与医生被相信的程度无关。", "海拔": "语义：海拔是地面的高度，不能用来形容人，句意不通。"}, "sentence_index": 0, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小明的公信力很烫，一摸就缩手。", "explanation": "这里应该用〈温度〉。烫说的是温度，公信力指大家相信某人或机构的程度，不能用来形容温度。"}, {"text": "这位歌手的公信力很高，几乎人人都认识他。", "explanation": "这里应该用〈知名度〉。知名度说的是被人知道的程度，公信力说的是被相信的程度，不能用来表示“被认识”。"}, {"text": "他这个月的公信力减轻了三公斤。", "explanation": "这里应该用〈体重〉。公信力是抽象的信任程度，不能用公斤计量，说体重减轻才用“体重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公信力", "is_correct": true, "explanation": "“公信力很强”说银行被大家相信，与句意一致。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的高矮，不能用来形容银行，句意不通。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，银行没有体温，句意不通。"}, {"text": "密度", "is_correct": false, "explanation": "搭配：“很强”一般形容能力、影响等，不说“密度很强”。"}], "explanations": {"公信力": "“公信力很强”说银行被大家相信，与句意一致。", "身高": "语义：身高是人的高矮，不能用来形容银行，句意不通。", "体温": "语义：体温是人体的温度，银行没有体温，句意不通。", "密度": "搭配：“很强”一般形容能力、影响等，不说“密度很强”。"}, "sentence_index": 6, "correct_answer": "公信力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老人的公信力很远，能看见远处的鸟。", "explanation": "这里应该用〈视力〉。能看见远处的东西说的是视力，公信力指大家的信任程度，不能用“远”来形容。"}, {"text": "这道菜的公信力最好，我吃了还想吃。", "explanation": "这里应该用〈味道〉。“最好”形容味道时指好吃，公信力是抽象的信任，不能用来描述食物。"}, {"text": "这幅画的公信力很鲜艳，好看极了。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，公信力是抽象的信任，不能用“鲜艳”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家店地公信力很高，很多人都愿意来。", "corrected_sentence": "那家店的公信力很高，很多人都愿意来。", "error_description": "错误：“地”是状语的结构助词，这里“那家店”修饰“公信力”，是定语，应用“的”。正确是“那家店的公信力很高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家医院有一只公信力，大家都信任它。", "corrected_sentence": "那家医院有一定的公信力，大家都信任它。", "error_description": "错误：“只”是量词，用于动物、手等，不能修饰抽象的“公信力”。这里应直接用“一定的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a544ea13-4631-434d-b7b2-4c879e82b8d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
