INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西从一个地方送到另一个地方。", "primary_collocate": null, "pronunciation": "chuán shū", "ipa": "ʈʂʰwan˧˥ ʂu˥", "syllable_count": 2, "sentences": [{"text": "热量通过金属棒传输到另一端。", "target_word": "传输", "complexity_tier": "T3", "furigana": "chuán shū", "sentence_source": "generated"}, {"text": "能量通过导线传输到远处。", "target_word": "传输", "complexity_tier": "T3", "furigana": "chuán shū", "sentence_source": "generated"}, {"text": "这条管子可以传输热水。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把资料传输给了老师。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话线传输着人们的声音。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些信息传输得很安全。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把照片传输到我的电脑上。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音通过墙壁传输到隔壁房间。", "target_word": "传输", "complexity_tier": "T3", "furigana": "chuán shū", "sentence_source": "generated"}, {"text": "这台机器每天传输很多文件。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声音在空气中传输得很远。", "target_word": "传输", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传输了", "label": "体标"}, {"form": "传输着", "label": "体标"}, {"form": "传输过", "label": "体标"}, {"form": "数据传输", "label": "复合词"}, {"form": "傳輸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把东西从一地送到另一地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：传输 chuán shū，意思是把东西从一地送到另一地。"}, {"text": "穿书", "is_correct": false, "explanation": "chuān（第一声）与 chuán（第二声）声调不同，穿书意思是穿越进书里。"}, {"text": "传述", "is_correct": false, "explanation": "shù（第四声）与 shū（第一声）声调不同，传述意思是转告别人的话。"}, {"text": "传授", "is_correct": false, "explanation": "shòu 与 shū 韵母不同（ou 与 u），传授意思是把知识或技能教给别人。"}, {"text": "传说", "is_correct": false, "explanation": "shuō 与 shū 韵母不同（uo 与 u），传说意思是民间流传的故事。"}], "explanations": {"传输": "正确：传输 chuán shū，意思是把东西从一地送到另一地。", "穿书": "chuān（第一声）与 chuán（第二声）声调不同，穿书意思是穿越进书里。", "传述": "shù（第四声）与 shū（第一声）声调不同，传述意思是转告别人的话。", "传授": "shòu 与 shū 韵母不同（ou 与 u），传授意思是把知识或技能教给别人。", "传说": "shuō 与 shū 韵母不同（uo 与 u），传说意思是民间流传的故事。"}, "sentence_index": null, "correct_answer": "传输"}, "level_3": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：「热量通过金属棒传输到另一端」中，传输表示能量沿介质送达，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：热量不能被扔，「扔」的对象应是有形的物体。"}, {"text": "卖", "is_correct": false, "explanation": "语义：热量不能被卖，「卖」与「热量」在句中无法搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：「游泳」是不及物动词，不能带「通过金属棒」这类介词短语表示热量移动。"}], "explanations": {"传输": "正确：「热量通过金属棒传输到另一端」中，传输表示能量沿介质送达，符合句意。", "扔": "语义：热量不能被扔，「扔」的对象应是有形的物体。", "卖": "语义：热量不能被卖，「卖」与「热量」在句中无法搭配。", "游泳": "搭配：「游泳」是不及物动词，不能带「通过金属棒」这类介词短语表示热量移动。"}, "sentence_index": 0, "correct_answer": "传输"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感冒病毒很容易通过空气传输给别人。", "explanation": "这里应该用〈传染〉。疾病的传播用传染，传输不用于病毒的传播。"}, {"text": "请把杯子传输给我。", "explanation": "这里应该用〈递〉。用手交给对方的东西要用递，传输指送到远处。"}, {"text": "妈妈把饼干传输到了北京。", "explanation": "这里应该用〈寄〉。把食品邮寄到外地要用寄，传输不指邮寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传输", "is_correct": true, "explanation": "正确：「请把照片传输到我的电脑上」中，传输表示把照片送到电脑，符合句意。"}, {"text": "拍", "is_correct": false, "explanation": "语义：「拍」是拍摄的动作，不能把已有的照片「拍」到电脑上。"}, {"text": "擦", "is_correct": false, "explanation": "语义：「擦」是擦拭的动作，照片不能被「擦到」电脑上。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：「缝」通常用于衣物或布料，不能与「到电脑上」这样的处所搭配。"}], "explanations": {"传输": "正确：「请把照片传输到我的电脑上」中，传输表示把照片送到电脑，符合句意。", "拍": "语义：「拍」是拍摄的动作，不能把已有的照片「拍」到电脑上。", "擦": "语义：「擦」是擦拭的动作，照片不能被「擦到」电脑上。", "缝": "搭配：「缝」通常用于衣物或布料，不能与「到电脑上」这样的处所搭配。"}, "sentence_index": 6, "correct_answer": "传输"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把货物传输到了仓库。", "explanation": "这里应该用〈运〉。大批货物的运送用运，传输不用于货物搬运。"}, {"text": "我把旧报纸传输到了楼下。", "explanation": "这里应该用〈扔〉。把废旧物品拿去丢弃要用扔，传输不指这种动作。"}, {"text": "医生们把伤员传输到了医院。", "explanation": "这里应该用〈送〉。人员的转运要用送，传输用于东西的送达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批热水已经传输了完。", "corrected_sentence": "这批热水已经传输完了。", "error_description": "错误形式「传输了完」，正确形式「传输完了」。结果补语「完」应紧跟动词，「了」放在补语之后，不能插在动词和补语之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请把文件传输了我的手机上。", "corrected_sentence": "请把文件传输到我的手机上。", "error_description": "错误在于用“了”代替了趋向补语“到”。“传输”后应接“到”引出送达的处所，应说“传输到我的手机上”，“了”不能放在此处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
