INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27494, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "司法是法院和警察依照法律处理事情的工作。", "primary_collocate": null, "pronunciation": "sī fǎ", "ipa": "sɨ˥ fa˨˩˦", "syllable_count": 2, "sentences": [{"text": "司法就是法院和警察按法律办事。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大后想做司法方面的工作。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法让坏人得到应有的处罚。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法要公平，不能偏向有钱人。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了什么是司法。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法不公平，大家就不安心。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人很相信司法。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对司法很感兴趣。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司法的工作很辛苦。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，司法要靠法律，不能靠关系。", "target_word": "司法", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "司法部", "label": "复合词"}, {"form": "司法机关", "label": "复合词"}], "register": "正式", "sense_fingerprint": "法院和警察依法办事的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：天气不是法院和警察依法办事的工作。"}, {"text": "司法", "is_correct": true, "explanation": "“司法”指法院和警察依法办事的工作，与句子定义一致。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“就是……办事”的主语应是工作或制度，不能是“体育”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不能说它就是法院和警察依法办事。"}], "explanations": {"天气": "语义：天气不是法院和警察依法办事的工作。", "司法": "“司法”指法院和警察依法办事的工作，与句子定义一致。", "体育": "搭配：“就是……办事”的主语应是工作或制度，不能是“体育”。", "厨房": "语义：厨房是场所，不能说它就是法院和警察依法办事。"}, "sentence_index": 0, "correct_answer": "司法"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "律师在法庭上提交了司法。", "explanation": "这里应该用〈证据〉。律师在法庭上提交的是证据，不是司法。"}, {"text": "他决定提起司法。", "explanation": "这里应该用〈诉讼〉。能够“提起”的是诉讼，司法指国家机关依法处理案件的活动，不能被提起。"}, {"text": "小学生每天都在司法。", "explanation": "这里应该用〈学习〉。小学生每天做的是学习，司法指法院和警察依法办事的工作，不能用来形容小学生的日常活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园是地点，不能成为“相信”的对象。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”描述人的身体特征，不能作“相信”的对象。"}, {"text": "司法", "is_correct": true, "explanation": "“相信司法”指相信法院和警察依法办事的制度，搭配自然，与句子相符。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“相信”后接的是人、说法或制度，不接“窗户”。"}], "explanations": {"花园": "语义：花园是地点，不能成为“相信”的对象。", "体重": "体貌：“体重”描述人的身体特征，不能作“相信”的对象。", "司法": "“相信司法”指相信法院和警察依法办事的制度，搭配自然，与句子相符。", "窗户": "搭配：“相信”后接的是人、说法或制度，不接“窗户”。"}, "sentence_index": 6, "correct_answer": "司法"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他出示了司法。", "explanation": "这里应该用〈身份证〉。出示的是身份证件，司法是工作，不能拿出来给人看。"}, {"text": "国家颁布了司法。", "explanation": "这里应该用〈法规〉。颁布的是法规等法律文件，司法是依法办事的工作，不能被颁布。"}, {"text": "这一把司法很公正。", "explanation": "这里应该用〈项〉。“把”用于有柄的器具，司法指工作，应说“这项司法工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只司法很公正。", "corrected_sentence": "这种司法很公正。", "error_description": "量词错误：“司法”是抽象的制度，应用“种”，“只”用于动物或成对物件中的一个，不能说“这只司法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对司法很的感兴趣。", "corrected_sentence": "他对司法很感兴趣。", "error_description": "多余的“的”：副词“很”后不能直接加“的”，应删去，说“他对司法很感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
