INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得不一样。", "primary_collocate": null, "pronunciation": "chā yì huà", "ipa": "ʈʂʰa˥ i˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "公司想实现产品差异化。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "gōng sī xiǎng shí xiàn chǎn pǐn chā yì huà.", "sentence_source": "generated"}, {"text": "我们要提供差异化服务，吸引更多客人。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "wǒ men yào tí gōng chā yì huà fú wù, xī yǐn gèng duō kè rén.", "sentence_source": "generated"}, {"text": "这家店努力差异化，不想和别人一样。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了差异化，他们换了新包装。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师会对教学进行差异化，照顾每个学生。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "lǎo shī huì duì jiào xué jìn xíng chā yì huà, zhào gù měi gè xué shēng.", "sentence_source": "generated"}, {"text": "小店必须差异化，才能和大店竞争。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们实行差异化定价，让不同的人都能买。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "tā men shí xíng chā yì huà dìng jià, ràng bù tóng de rén dōu néng mǎi.", "sentence_source": "generated"}, {"text": "品牌想差异化，就要有自己的特点。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的菜单还需要更多差异化。", "target_word": "差异化", "complexity_tier": "T3", "furigana": "nǐ men de cài dān hái xū yào gèng duō chā yì huà.", "sentence_source": "generated"}, {"text": "我们打算差异化经营，不卖别家的东西。", "target_word": "差异化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差异", "label": "复合"}, {"form": "差异化了", "label": "体标"}, {"form": "差異化", "label": "繁体"}], "register": "正式", "sense_fingerprint": "使东西与别的不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f88850e-622b-426b-b7db-fbf12d98ab7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“实现产品差异化”中，“差异化”指使产品与别的不同，符合句意。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“公司想实现”的目标是产品与别的不同，摧毁产品与句意相反。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指没有工作，与产品无关，不能用于“实现产品”。"}, {"text": "同质化", "is_correct": false, "explanation": "语义：“同质化”指产品变得相同，与公司想要的不同正好相反。"}], "explanations": {"差异化": "正确。“实现产品差异化”中，“差异化”指使产品与别的不同，符合句意。", "摧毁": "语义：“公司想实现”的目标是产品与别的不同，摧毁产品与句意相反。", "失业": "语义：“失业”指没有工作，与产品无关，不能用于“实现产品”。", "同质化": "语义：“同质化”指产品变得相同，与公司想要的不同正好相反。"}, "sentence_index": 0, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "为了让顾客差异化我们，他们换了新包装。", "explanation": "这里应该用〈区分〉。差异化是使事物本身变得不同，让顾客辨认出我们要用〈区分〉。"}, {"text": "他们差异化了资料，方便大家看。", "explanation": "这里应该用〈整理〉。差异化是使东西与别的不同，把资料理顺、分类要用〈整理〉。"}, {"text": "他们差异化了洗衣机，很快就修好了。", "explanation": "这里应该用〈修理〉。差异化是使东西与别的不同，把坏的东西修好要用〈修理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差异化", "is_correct": true, "explanation": "正确。“实行差异化定价”是动词修饰定价，指定价因人而异、各不相同。"}, {"text": "跟风", "is_correct": false, "explanation": "语义：“跟风”指盲目追随别人，与“让不同的人都能买”的定价目的不符。"}, {"text": "抢购", "is_correct": false, "explanation": "搭配：“定价”前常用“统一、分级、浮动”等词，“抢购”不能修饰定价。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”指没有工作，与定价方式无关，句意不通。"}], "explanations": {"差异化": "正确。“实行差异化定价”是动词修饰定价，指定价因人而异、各不相同。", "跟风": "语义：“跟风”指盲目追随别人，与“让不同的人都能买”的定价目的不符。", "抢购": "搭配：“定价”前常用“统一、分级、浮动”等词，“抢购”不能修饰定价。", "失业": "语义：“失业”指没有工作，与定价方式无关，句意不通。"}, "sentence_index": 6, "correct_answer": "差异化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们打算差异化顾客，不卖别家的东西。", "explanation": "这里应该用〈服务〉。差异化的对象是东西，使其与别家不同；为顾客提供好的东西要用〈服务〉。"}, {"text": "他把这篇文章差异化成了英文。", "explanation": "这里应该用〈翻译〉。差异化是使东西与别的不同，把文章换成另一种语言要用〈翻译〉。"}, {"text": "他用计算器差异化出了总数。", "explanation": "这里应该用〈计算〉。差异化是使东西与别的不同，算出总数要用〈计算〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们没被产品差异化，所以顾客还分不清。", "corrected_sentence": "他们没把产品差异化，所以顾客还分不清。", "error_description": "“把”字句中的“把”误写成“被”。“被”表被动，不能引出“产品”作为“差异化”的对象；应说“他们没把产品差异化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把菜单差异化了过，价格没变。", "corrected_sentence": "他们把菜单差异化了，价格没变。", "error_description": "“了”和“过”不能同时用在同一个动词后面。应只保留“了”，写成“把菜单差异化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3735450-d914-49c0-b4a8-d2d3be295640') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺向", "is_correct": true, "explanation": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。"}, {"text": "停留", "is_correct": false, "explanation": "与“逆向”没有反义关系。“停留”指停下不动，与方向相反无关。"}, {"text": "观望", "is_correct": false, "explanation": "与“逆向”没有反义关系。“观望”指先看形势再决定，与行走的方向无关。"}, {"text": "跟随", "is_correct": false, "explanation": "与“逆向”没有反义关系。“跟随”指紧跟别人，与朝相反方向行动不构成对立。"}], "correct_answer": "顺向", "explanations": {"顺向": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。", "停留": "与“逆向”没有反义关系。“停留”指停下不动，与方向相反无关。", "观望": "与“逆向”没有反义关系。“观望”指先看形势再决定，与行走的方向无关。", "跟随": "与“逆向”没有反义关系。“跟随”指紧跟别人，与朝相反方向行动不构成对立。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "顺向", "is_correct": true, "explanation": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。"}, {"text": "等待", "is_correct": false, "explanation": "与“逆向”没有反义关系。“等待”指停下来期望某事发生，与方向无关。"}, {"text": "休息", "is_correct": false, "explanation": "与“逆向”没有反义关系。“休息”指停止劳动或活动，与方向无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“逆向”没有反义关系。“散步”指悠闲地走，只是一种行动，与朝哪个方向走无关。"}], "correct_answer": "顺向", "explanations": {"顺向": "正确。“顺向”与“逆向”相对，指朝同一个方向走或想，二者构成反义关系。", "等待": "与“逆向”没有反义关系。“等待”指停下来期望某事发生，与方向无关。", "休息": "与“逆向”没有反义关系。“休息”指停止劳动或活动，与方向无关。", "散步": "与“逆向”没有反义关系。“散步”指悠闲地走，只是一种行动，与朝哪个方向走无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "朝着相反的方向走或者想。", "primary_collocate": null, "pronunciation": "nì xiàng", "ipa": "ni˥˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "大家都往前走，他却逆向而行。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼一路逆向洄游，想回到老家。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "yú yí lù nì xiàng huí yóu, xiǎng huí dào lǎo jiā。", "sentence_source": "generated"}, {"text": "遇到问题时，你可以逆向想一想。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人群向东走，她一个人逆向走着。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总爱逆向思考，想法和别人不同。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊里人太多，我们只好逆向慢慢挤过去。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "zǒu láng lǐ rén tài duō, wǒ men zhǐ hǎo nì xiàng màn màn jǐ guò qù。", "sentence_source": "generated"}, {"text": "走错路后，他们决定逆向折回，重新找路。", "target_word": "逆向", "complexity_tier": "T3", "furigana": "zǒu cuò lù hòu, tā men jué dìng nì xiàng zhé huí, chóng xīn zhǎo lù。", "sentence_source": "generated"}, {"text": "从结果逆向想，就能找到原因。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们逆向跑，撞到了朋友。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人往上爬，他偏要逆向往下走。", "target_word": "逆向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逆向思维", "label": "复合"}, {"form": "逆向工程", "label": "复合"}], "register": "中性", "sense_fingerprint": "朝相反方向走或想", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d15e82a-085a-429a-8ad9-4fb80ab3820b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。目标词读 nì xiàng（第四声、第四声），意思是朝相反的方向走或想。"}, {"text": "内向", "is_correct": false, "explanation": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。"}, {"text": "意向", "is_correct": false, "explanation": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。"}, {"text": "立项", "is_correct": false, "explanation": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。"}, {"text": "志向", "is_correct": false, "explanation": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}], "explanations": {"逆向": "正确。目标词读 nì xiàng（第四声、第四声），意思是朝相反的方向走或想。", "内向": "nèi（第四声）与 nì（第四声）声调相同，韵母不同（ei 与 i），意思是性格向内、不爱外露。", "意向": "yì 与 nì 声母不同（零声母与 n），声调相同，意思是打算或意图。", "立项": "lì 与 nì 声母不同（l 与 n），第二音节 xiàng 相同，意思是批准设立一个项目。", "志向": "zhì 与 nì 声母不同（zh 与 n），声调相同，意思是立志追求的目标。"}, "sentence_index": null, "correct_answer": "逆向"}, "level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“逆向而行”指朝相反方向走，与“大家都往前走”形成对比，“却”的转折成立。"}, {"text": "随从", "is_correct": false, "explanation": "语义：“随从”表示跟着别人走，与“大家都往前走”的走向一致，与“却”的转折矛盾。"}, {"text": "前进", "is_correct": false, "explanation": "语义：“前进”与前句“往前走”重复，不能构成“却”所要求的转折对比。"}, {"text": "同行", "is_correct": false, "explanation": "搭配：“同行”指一起走，不说“同行而行”，与“他却”的语境也不合。"}], "explanations": {"逆向": "正确。“逆向而行”指朝相反方向走，与“大家都往前走”形成对比，“却”的转折成立。", "随从": "语义：“随从”表示跟着别人走，与“大家都往前走”的走向一致，与“却”的转折矛盾。", "前进": "语义：“前进”与前句“往前走”重复，不能构成“却”所要求的转折对比。", "同行": "搭配：“同行”指一起走，不说“同行而行”，与“他却”的语境也不合。"}, "sentence_index": 0, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是逆向吃饭，吃得很慢。", "explanation": "这里不能用〈逆向〉。学习者易把“逆向”理解为“与众不同的做法”，但它只指朝相反方向走或想，不能用来说“吃饭”的方式。"}, {"text": "他逆向了大家的意愿。", "explanation": "这里应该用〈违背〉。“逆向”只表示朝相反方向走或想，不表示违反大家的意愿。"}, {"text": "人群向东走，她一个人逆向地睡着了。", "explanation": "这里不能用〈逆向〉。学习者易受上句“人群向东走”影响，把“逆向”理解为“逆着人群”，但它不能修饰“睡着”这类静止的状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逆向", "is_correct": true, "explanation": "正确。“逆向折回”指朝相反方向往回走，与“走错路后”“重新找路”的语境吻合。"}, {"text": "直行", "is_correct": false, "explanation": "语义：“直行”指一直向前走，与“折回”的方向相反，句意矛盾。"}, {"text": "跳过", "is_correct": false, "explanation": "搭配：“跳过”指越过某段，不能与“折回”组合，句意不通。"}, {"text": "并排", "is_correct": false, "explanation": "搭配：“并排”说位置相邻，不修饰“折回”这种改变方向的动作。"}], "explanations": {"逆向": "正确。“逆向折回”指朝相反方向往回走，与“走错路后”“重新找路”的语境吻合。", "直行": "语义：“直行”指一直向前走，与“折回”的方向相反，句意矛盾。", "跳过": "搭配：“跳过”指越过某段，不能与“折回”组合，句意不通。", "并排": "搭配：“并排”说位置相邻，不修饰“折回”这种改变方向的动作。"}, "sentence_index": 6, "correct_answer": "逆向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子逆向地爱上了那位老师。", "explanation": "这里不能用〈逆向〉。学习者易把“逆向”理解为“与常情相反”的感情，但它只指朝相反方向走或想，不表示感情的变化。"}, {"text": "这次比赛他的成绩很逆向。", "explanation": "这里应该用〈糟糕〉。学习者易把“逆向”理解为“反常”，但它只指朝相反方向走或想，不能用来评价成绩。"}, {"text": "这座山很逆向，我们爬得很轻松。", "explanation": "这里应该用〈陡峭〉或〈平缓〉。学习者易把“逆向”理解为“难爬”，但它只描述方向或思路，不用来形容山的难易。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他逆向了走了一段路。", "corrected_sentence": "他逆向走了一段路。", "error_description": "错误形式“逆向了走了”，正确形式“逆向走了”。“了”只能放在动词“走”之后，“逆向”与动词之间不能插入“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们只好逆向了折回，重新找路。", "corrected_sentence": "他们只好逆向折回，重新找路。", "error_description": "错误形式“逆向了折回”，正确形式“逆向折回”。“逆向”作状语修饰动词“折回”，二者之间不能插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3306acf9-621c-495f-a2bb-871930848cd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
