INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "竞争力就是看谁做得更好、更快的能力。", "primary_collocate": null, "pronunciation": "jìng zhēng lì", "ipa": "tɕiŋ˥˩ ʈʂɤŋ˥ li˥˩", "syllable_count": 3, "sentences": [{"text": "这个队跑得又快又稳，竞争力很强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的菜便宜又好吃，很有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会三种语言，找工作更有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的手机比别人的便宜，有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂做得慢，没有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学新技术可以提高你的竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的蛋糕又新鲜又便宜，竞争力很强。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想赢比赛，球队要有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "速度慢的公司，竞争力会变弱。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学电脑，让自己更有竞争力。", "target_word": "竞争力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心竞争力", "label": "复合"}], "register": "中性", "sense_fingerprint": "比别人做得更好更快的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。“竞争力”指比别人做得更好更快的能力，与“跑得又快又稳”照应。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色指色彩，与“跑得又快又稳”所说的能力无关，“颜色很强”说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述高矮，不能用“很强”来形容一个队的表现。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道指口感或气味，与“跑得快、稳”无关，“味道很强”在这里说不通。"}], "explanations": {"竞争力": "正确。“竞争力”指比别人做得更好更快的能力，与“跑得又快又稳”照应。", "颜色": "语义：颜色指色彩，与“跑得又快又稳”所说的能力无关，“颜色很强”说不通。", "身高": "体貌：身高描述高矮，不能用“很强”来形容一个队的表现。", "味道": "语义：味道指口感或气味，与“跑得快、稳”无关，“味道很强”在这里说不通。"}, "sentence_index": 0, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的竞争力很快，跑得很稳。", "explanation": "这里应该用〈速度〉。竞争力指比别人更好更快的能力，描述快慢要说“速度”，不能直接说“竞争力很快”。"}, {"text": "两家工厂之间的竞争力很激烈。", "explanation": "这里应该用〈角逐〉。“激烈”形容的是角逐的过程；竞争力是能力，不能说“竞争力很激烈”。"}, {"text": "这家工厂有了一辆很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“辆”只用于车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "竞争力", "is_correct": true, "explanation": "正确。“竞争力”指做得更好更快的能力，与“又新鲜又便宜”所说的优势相合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，蛋糕没有身材，不能说“身材很强”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄只用于人或动物，不能形容蛋糕，“年龄很强”说不通。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：脸色指人的面部气色，与蛋糕无关，不能说明它的优势。"}], "explanations": {"竞争力": "正确。“竞争力”指做得更好更快的能力，与“又新鲜又便宜”所说的优势相合。", "身材": "体貌：身材描述人的体型，蛋糕没有身材，不能说“身材很强”。", "年龄": "语义：年龄只用于人或动物，不能形容蛋糕，“年龄很强”说不通。", "脸色": "语义：脸色指人的面部气色，与蛋糕无关，不能说明它的优势。"}, "sentence_index": 6, "correct_answer": "竞争力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位选手有一只很强的竞争力。", "explanation": "这里应该用〈种〉。竞争力是抽象能力，量词用“种”；“只”用于动物等，不能用于能力。"}, {"text": "他们的竞争力越来越多。", "explanation": "这里应该用〈竞争对手〉。竞争力是能力，不能按数量增加；“越来越多”说的是对手。"}, {"text": "这场竞争力很激烈。", "explanation": "这里应该用〈竞赛〉。竞争力是能力，不指比赛本身；“激烈”形容的是竞赛或竞争的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的服务很好，有一台很强的竞争力。", "corrected_sentence": "这家店的服务很好，有一种很强的竞争力。", "error_description": "量词错误：“竞争力”是抽象能力，应用“种”，不用“台”（“台”用于机器等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27508, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支球队的竞争力的很强。", "corrected_sentence": "这支球队的竞争力很强。", "error_description": "多余的“的”：“竞争力”后不应再接“的”，应说“球队的竞争力很强”，不说“球队的竞争力的很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻性", "is_correct": true, "explanation": "进攻性与防御性相对：防御性指保护自己，进攻性指主动攻击。"}, {"text": "柔软", "is_correct": false, "explanation": "不在反义关系内：柔软形容质地，与“防御性”没有对应的反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "不在反义关系内：明亮形容光线或颜色，与“防御性”没有对应的反义关系。"}, {"text": "宽广", "is_correct": false, "explanation": "不在反义关系内：宽广形容面积或胸怀，与“防御性”没有对应的反义关系。"}], "correct_answer": "进攻性", "explanations": {"进攻性": "进攻性与防御性相对：防御性指保护自己，进攻性指主动攻击。", "柔软": "不在反义关系内：柔软形容质地，与“防御性”没有对应的反义关系。", "明亮": "不在反义关系内：明亮形容光线或颜色，与“防御性”没有对应的反义关系。", "宽广": "不在反义关系内：宽广形容面积或胸怀，与“防御性”没有对应的反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "攻击性", "is_correct": true, "explanation": "攻击性与防御性相对：前者指主动攻击，后者指保护自己。"}, {"text": "清澈", "is_correct": false, "explanation": "不在反义关系内：清澈形容水或眼神干净透明，与“防御性”没有反义关系。"}, {"text": "沉重", "is_correct": false, "explanation": "不在反义关系内：沉重形容分量或心情，与“防御性”没有反义关系。"}, {"text": "狭窄", "is_correct": false, "explanation": "不在反义关系内：狭窄形容空间小，与“防御性”没有反义关系。"}], "correct_answer": "攻击性", "explanations": {"攻击性": "攻击性与防御性相对：前者指主动攻击，后者指保护自己。", "清澈": "不在反义关系内：清澈形容水或眼神干净透明，与“防御性”没有反义关系。", "沉重": "不在反义关系内：沉重形容分量或心情，与“防御性”没有反义关系。", "狭窄": "不在反义关系内：狭窄形容空间小，与“防御性”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "用来保护自己，不让别人伤害。", "primary_collocate": null, "pronunciation": "fáng yù xìng", "ipa": "fɑŋ˧˥ y˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "刺猬身上的刺有防御性，能保护自己。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一种防御性武器，只能用来保护自己。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举起手臂，做了一个防御性的动作。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城墙是防御性建筑，能挡住外面的敌人。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫看到大狗，身体缩成一团，这是防御性姿势。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险时，很多动物会有防御性行为。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拳击手双手护头，先采取防御性站位。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个防御性装备能保护你的头，让你不受伤。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学防御性技巧，遇到坏人不怕。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乌龟的壳有防御性作用，不让敌人伤害它。", "target_word": "防御性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防禦性", "label": "繁体"}, {"form": "防御性武器", "label": "复合"}], "register": "中性", "sense_fingerprint": "防御性：用来保护自己、不让别人伤害的（武器、动作、行为）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防御性", "is_correct": true, "explanation": "防御性指用来保护自己、不让别人伤害的，刺用来保护身体，与句意一致。"}, {"text": "柔软性", "is_correct": false, "explanation": "语义：刺应是尖硬的，“柔软性”与“刺”的特点相反，也与“能保护自己”矛盾。"}, {"text": "装饰性", "is_correct": false, "explanation": "语义：“装饰性”指起美化作用，刺的功能是保护身体，不能用来说明它能保护自己。"}, {"text": "透明性", "is_correct": false, "explanation": "搭配：“透明性”说的是能否透光，不能用来修饰刺。"}], "explanations": {"防御性": "防御性指用来保护自己、不让别人伤害的，刺用来保护身体，与句意一致。", "柔软性": "语义：刺应是尖硬的，“柔软性”与“刺”的特点相反，也与“能保护自己”矛盾。", "装饰性": "语义：“装饰性”指起美化作用，刺的功能是保护身体，不能用来说明它能保护自己。", "透明性": "搭配：“透明性”说的是能否透光，不能用来修饰刺。"}, "sentence_index": 0, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗的防御性很强，常常主动扑向路人。", "explanation": "这里应该用〈攻击性〉。防御性指被动保护自己，主动扑向别人属于攻击，应说“攻击性很强”。"}, {"text": "这首歌的防御性很高，旋律十分轻快。", "explanation": "这里应该用〈感染力〉。防御性指用来保护自己，形容歌曲打动人心的力量要说“感染力”，不能用防御性。"}, {"text": "这支部队的防御性很强，专门负责偷袭敌人的后方。", "explanation": "这里应该用〈进攻性〉。防御性指保护自己，偷袭敌人的后方是进攻行为，要说“进攻性很强”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防御性", "is_correct": true, "explanation": "双手护头是为了保护自己，所以这里应用〈防御性〉。"}, {"text": "观赏性", "is_correct": false, "explanation": "语义：护头是为了保护自己，“观赏性”指供人欣赏的效果，与句中的保护动作不符。"}, {"text": "季节性", "is_correct": false, "explanation": "搭配：“季节性”说的是随季节变化的特点，不能用来修饰站位。"}, {"text": "附着性", "is_correct": false, "explanation": "搭配：“附着性”说的是附在其他物体上的能力，不能用来修饰站位。"}], "explanations": {"防御性": "双手护头是为了保护自己，所以这里应用〈防御性〉。", "观赏性": "语义：护头是为了保护自己，“观赏性”指供人欣赏的效果，与句中的保护动作不符。", "季节性": "搭配：“季节性”说的是随季节变化的特点，不能用来修饰站位。", "附着性": "搭配：“附着性”说的是附在其他物体上的能力，不能用来修饰站位。"}, "sentence_index": 6, "correct_answer": "防御性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的防御性很强，不断派兵攻打邻国。", "explanation": "这里应该用〈侵略性〉。防御性指保护自己，派兵攻打邻国属于侵略，应说“侵略性很强”。"}, {"text": "他说话很有防御性，故意挑起争端。", "explanation": "这里应该用〈挑衅性〉。防御性指保护自己，故意挑起争端是挑衅，应说“挑衅性很强”。"}, {"text": "这种药水的防御性很强，会让皮肤发红发痒。", "explanation": "这里应该用〈刺激性〉。防御性用于保护自己的武器、装备、行为，药水伤害皮肤的性质应说“刺激性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他防御性的抬起手臂，挡住了对方的拳头。", "corrected_sentence": "他防御性地抬起手臂，挡住了对方的拳头。", "error_description": "助词错误：修饰动词“抬起”的成分应用“地”，写作“防御性地抬起”；这里误用“的”，应改为“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块盾牌很防御性，能挡住刀剑。", "corrected_sentence": "这块盾牌很有防御性，能挡住刀剑。", "error_description": "词语漏用：形容词“防御性”前用“很”时，抽象属性要说“很有防御性”，漏掉“有”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
