INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27512, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个数相减的结果。", "primary_collocate": null, "pronunciation": "chā fēn", "ipa": "ʈʂʰa˥ fən˥", "syllable_count": 2, "sentences": [{"text": "请算出这两个数的差分。", "target_word": "差分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "后一个数减前一个数，就是差分。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这组数的差分都是二。", "target_word": "差分", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师让我们求这列数的差分。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "差分是零，说明两个数一样大。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "表里的第二行是前后两天的差分。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在电脑上算出了每天的差分。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "差分越来越大，说明数字变化很快。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生把每一对数的差分写在本子上。", "target_word": "差分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个表格里的差分有正数，也有负数。", "target_word": "差分", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一阶差分", "label": "复合"}, {"form": "差分方程", "label": "复合"}], "register": "专业", "sense_fingerprint": "两个数相减得到的结果（求差分、一阶差分、差分方程）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '755d8dfd-b59d-4c6c-9903-4203478bf4fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27512, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：“名字”不能被算出来，句子说不通"}, {"text": "差分", "is_correct": true, "explanation": "正确：“差分”是两个数相减的结果，句中“算出这两个数的差分”正合适"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“算出”的结果是数值，不说「算出颜色」"}, {"text": "图案", "is_correct": false, "explanation": "语义：“图案”是图形花纹，不是可以计算出的结果"}], "explanations": {"名字": "语义：“名字”不能被算出来，句子说不通", "差分": "正确：“差分”是两个数相减的结果，句中“算出这两个数的差分”正合适", "颜色": "搭配：“算出”的结果是数值，不说「算出颜色」", "图案": "语义：“图案”是图形花纹，不是可以计算出的结果"}, "sentence_index": 0, "correct_answer": "差分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两队的实力差分很大，比分一直是一边倒。", "explanation": "这里应该用〈差距〉。差分是数学上两数相减的结果，形容实力之间的距离要用差距"}, {"text": "两种方法的效果差分明显，实验结果很清楚。", "explanation": "这里应该用〈差异〉。差分不用于表示事物性质或效果的不同，差异才是这个意思"}, {"text": "瀑布的差分很大，水流非常湍急。", "explanation": "这里应该用〈落差〉。落差指高度的差别，差分是数学术语，不用于描述地形高低"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27512, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”不是可以用电脑算出的结果，句子说不通"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“算出”的结果是数值，不说「算出心情」"}, {"text": "差分", "is_correct": true, "explanation": "正确：“差分”是两个数相减的结果，句中“算出了每天的差分”正合适"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”是头发的样式，不能用电脑算出来"}], "explanations": {"歌曲": "语义：“歌曲”不是可以用电脑算出的结果，句子说不通", "心情": "搭配：“算出”的结果是数值，不说「算出心情」", "差分": "正确：“差分”是两个数相减的结果，句中“算出了每天的差分”正合适", "发型": "语义：“发型”是头发的样式，不能用电脑算出来"}, "sentence_index": 6, "correct_answer": "差分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把尺子的差分很大，量出来的长度总不准。", "explanation": "这里应该用〈误差〉。差分指数列中相邻两数相减的结果，不用来描述仪器测出的数值与真实值之间的偏差。"}, {"text": "两家商店的差分很大，同一件东西价格不同。", "explanation": "这里应该用〈差价〉。差价指价格之间的差别，差分不用于描述商品价格的不同"}, {"text": "双方在方案上的差分很大，谈判很难。", "explanation": "这里应该用〈分歧〉。分歧指意见不一致，差分是数学术语，不用于描述看法的不同"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27512, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们算出了相邻两数地差分。", "corrected_sentence": "我们算出了相邻两数的差分。", "error_description": "「差分」前面修饰它的「相邻两数」要用结构助词「的」，应说「相邻两数的差分」；「地」用于修饰动词，不能修饰名词「差分」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27512, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一组数里有一颗差分是零。", "corrected_sentence": "这一组数里有一个差分是零。", "error_description": "「差分」应该用量词「个」，说「一个差分」；「颗」用于颗粒状的东西，不能用来计数差分。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74e99008-eefc-4f4f-b77c-ba1189f4b58b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
