INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27514, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指一种像规则一样，让事情变得有秩序的方式。", "primary_collocate": null, "pronunciation": "zhì dù xìng", "ipa": "tʂɻ̩˥˩ tu˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "公司有制度性的安排，每个人都按时交报告。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校用制度性的办法管理图书馆。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排队买票是一种制度性的做法。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要制度性的办法，让会议更有秩序。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区制定了制度性的规定，车必须停在线内。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有制度性的做法，每天轮流打扫教室。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工作需要制度性的管理，不能只靠一个人。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用制度性的方式分配任务，大家都很满意。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路口没有制度性的规则，所以常常堵车。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂有制度性的检查，每月一次。", "target_word": "制度性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "制度性的", "label": "定语形式"}], "register": "书面语", "sense_fingerprint": "像规则一样让事情有秩序的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27514, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "制度性", "is_correct": true, "explanation": "“制度性”指像规则一样的固定安排，与“每个人都按时交报告”相合。"}, {"text": "神秘", "is_correct": false, "explanation": "语义：“神秘”指难以捉摸，与“按时交报告”的安排不合。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：“调皮”形容人顽皮，不能修饰“安排”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容体型，不能修饰“安排”。"}], "explanations": {"制度性": "“制度性”指像规则一样的固定安排，与“每个人都按时交报告”相合。", "神秘": "语义：“神秘”指难以捉摸，与“按时交报告”的安排不合。", "调皮": "语义：“调皮”形容人顽皮，不能修饰“安排”。", "高大": "体貌：“高大”形容体型，不能修饰“安排”。"}, "sentence_index": 0, "correct_answer": "制度性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做事很有制度性，常常想到哪儿做到哪儿。", "explanation": "这里应该用〈随意〉。制度性指像规则一样让事情有秩序，不能用来形容做事随性、没有章法。"}, {"text": "他脾气很有制度性，谁的话都不听。", "explanation": "这里应该用〈任性〉。制度性指像规则一样让事情有秩序，不用于形容脾气执拗、不听劝告。"}, {"text": "这个孩子很有制度性，总是乱扔东西。", "explanation": "这里应该用〈纪律性〉。制度性指像规则一样让事情有秩序，不用于形容孩子乱扔东西的行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "制度性", "is_correct": true, "explanation": "“制度性”指像规则一样的有序管理，与“不能只靠一个人”相合。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”表示不固定、随便，与“好的工作”需要的管理相反。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道或声音，不能修饰“管理”。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能修饰“管理”。"}], "explanations": {"制度性": "“制度性”指像规则一样的有序管理，与“不能只靠一个人”相合。", "随意": "语义：“随意”表示不固定、随便，与“好的工作”需要的管理相反。", "甜美": "语义：“甜美”形容味道或声音，不能修饰“管理”。", "漂亮": "体貌：“漂亮”形容外貌，不能修饰“管理”。"}, "sentence_index": 6, "correct_answer": "制度性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次的安排是制度性的，只用一次。", "explanation": "这里应该用〈临时性〉。制度性指像规则一样的固定办法，与“只用一次”的语境矛盾。"}, {"text": "他的心情很有制度性，时好时坏。", "explanation": "这里应该用〈不稳定〉。制度性指有序的固定办法，不用于形容情绪的起伏。"}, {"text": "这间教室很有制度性，大家随便乱坐。", "explanation": "这里应该用〈混乱〉。制度性指像规则一样让事情有秩序，与“随便乱坐”的情形相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂要用制度性地办法管理员工。", "corrected_sentence": "工厂要用制度性的办法管理员工。", "error_description": "结构错误：“制度性”修饰名词“办法”时要用“的”，不用“地”。应说“制度性的办法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校有制度性地规定，每个班都一样。", "corrected_sentence": "这所学校有制度性的规定，每个班都一样。", "error_description": "结构错误：“有”后接名词性短语，“制度性”修饰名词“规定”时要用“的”，不用“地”；“制度性地”是修饰动词的状语，“有制度性地规定”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
