INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规则和限制。", "primary_collocate": null, "pronunciation": "guī zhì", "ipa": "kuei˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "学校有很多规制，学生都要遵守。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏有一套简单的规制，新手几分钟就能学会。", "target_word": "规制", "complexity_tier": "T3", "furigana": "zhè ge yóuxì yǒu yí tào jiǎndān de guīzhì, xīnshǒu jǐ fēnzhōng jiù néng xuéhuì。", "sentence_source": "generated"}, {"text": "公园对带宠物进入有新的规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对网上购物有一些规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多规制会让人觉得不自由。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂必须依照规制处理废弃物。", "target_word": "规制", "complexity_tier": "T3", "furigana": "gōngchǎng bìxū yīzhào guīzhì chǔlǐ fèiqìwù。", "sentence_source": "generated"}, {"text": "新来的人要先了解公司的规制。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规制是为了保护大家的安全。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在河边钓鱼有什么规制？", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规制太松，大家就不会认真。", "target_word": "规制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "规则和限制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "规制", "is_correct": true, "explanation": "“规制”指规则和限制，与“学生都要遵守”相合。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“遵守”一般搭配规定、纪律，不能说遵守饮料。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是地面植物，不是需要遵守的规定。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语说法，与本句的正式语体不合。"}], "explanations": {"规制": "“规制”指规则和限制，与“学生都要遵守”相合。", "饮料": "搭配：“遵守”一般搭配规定、纪律，不能说遵守饮料。", "草坪": "语义：草坪是地面植物，不是需要遵守的规定。", "玩意儿": "语域：“玩意儿”是口语说法，与本句的正式语体不合。"}, "sentence_index": 0, "correct_answer": "规制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们两人规制了周末见面。", "explanation": "这里应该用〈约定〉。规制指法律或规定对行为的约束，不用于两人之间口头商定。"}, {"text": "她每天都买一个规制，放进书包里。", "explanation": "这里应该用〈笔记本〉。规制是抽象的规则和限制，不是可以买来装进书包的东西。"}, {"text": "作业太多，我的规制快要写不完了。", "explanation": "这里应该用〈作业〉。规制是抽象的规则和限制，不能像作业一样“写不完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "规制", "is_correct": true, "explanation": "“规制”指公司的规定和限制，是新人需要了解的内容，句意通顺。"}, {"text": "烤箱", "is_correct": false, "explanation": "语义：烤箱是厨房器具，与“了解公司的”语境不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气属于自然现象，一般不说“了解公司的天气”。"}, {"text": "颜值", "is_correct": false, "explanation": "语域：“颜值”是网络口语，与本句的正式语体不合。"}], "explanations": {"规制": "“规制”指公司的规定和限制，是新人需要了解的内容，句意通顺。", "烤箱": "语义：烤箱是厨房器具，与“了解公司的”语境不合。", "天气": "语义：天气属于自然现象，一般不说“了解公司的天气”。", "颜值": "语域：“颜值”是网络口语，与本句的正式语体不合。"}, "sentence_index": 6, "correct_answer": "规制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们规制了这个难题。", "explanation": "这里应该用〈解决〉。规制指规则和限制，不能用来指解决问题。"}, {"text": "我很规制他的勇气。", "explanation": "这里应该用〈欣赏〉。规制指规则和限制，不用于表达对别人品质的赞赏。"}, {"text": "我规制老师的帮助。", "explanation": "这里应该用〈感谢〉。规制指规则和限制，不用于表达对别人帮助的感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司制定了一张新的规制，要求员工按时打卡。", "corrected_sentence": "公司制定了一项新的规制，要求员工按时打卡。", "error_description": "量词错误：“规制”应用量词“项”，不能用“张”（“张”用于平面的物品）。改为“一项新的规制”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把规制写很清楚。", "corrected_sentence": "学校把规制写得很清楚。", "error_description": "补语错误：“写”后面要用“得”引出补语，应说“写得很清楚”，不能说“写很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
