INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律说要你做的事，比如交税、遵守规则。", "primary_collocate": null, "pronunciation": "fǎ lǜ yì wù", "ipa": "fa˨˩˦ ly˥˩ i˥˩ u˥˩", "syllable_count": 4, "sentences": [{"text": "每个人都要交税，这是法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "送孩子上学是父母的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车不喝酒是司机的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板要给工人发工资，这是法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不交税，没有履行法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照顾老人也是子女的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道自己有什么法律义务吗？", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店卖东西要开发票，这是法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机停车等红灯，是法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为公民，我知道自己的法律义务。", "target_word": "法律义务", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "项", "label": "量词"}], "register": "中性", "sense_fingerprint": "法律要求你必须做的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9e2f4-bad9-4d70-bb25-903be09d21b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法律义务", "is_correct": true, "explanation": "正确。句子说每个人都要交税，“法律义务”指法律要求必须做的事，与之相合。"}, {"text": "权利", "is_correct": false, "explanation": "语义：权利指可以享有的东西，与“要交税”的强制性相反。"}, {"text": "爱好", "is_correct": false, "explanation": "语义：爱好是自愿的兴趣，不能用于“要交税”这种强制要求。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，与这句郑重的法律表述不协调，也说不通。"}], "explanations": {"法律义务": "正确。句子说每个人都要交税，“法律义务”指法律要求必须做的事，与之相合。", "权利": "语义：权利指可以享有的东西，与“要交税”的强制性相反。", "爱好": "语义：爱好是自愿的兴趣，不能用于“要交税”这种强制要求。", "玩意儿": "语域：“玩意儿”是口语，与这句郑重的法律表述不协调，也说不通。"}, "sentence_index": 0, "correct_answer": "法律义务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末陪父母吃饭，这是我的法律义务。", "explanation": "这里应该用〈道德责任〉。周末陪父母吃饭是道德上的要求，法律并不规定，不能说“法律义务”。"}, {"text": "下班前喝杯咖啡，这是我的法律义务。", "explanation": "这里应该用〈习惯〉。喝咖啡是个人习惯，法律并不要求，不能说“法律义务”。"}, {"text": "老板要给工人发工资，这是一张法律义务。", "explanation": "这里应该用〈项〉。“法律义务”是抽象的责任，量词用“项”；“张”用于纸张等平面物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法律义务", "is_correct": true, "explanation": "正确。“法律义务”指法律要求你必须做的事，与“你知道自己有什么”的提问相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不是要履行的事，不合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“有什么年龄”不成说法，应说“多大年纪”。"}, {"text": "秒针", "is_correct": false, "explanation": "语义：秒针是钟表的部件，人身上没有，不能说“你知道自己有什么秒针吗”。"}], "explanations": {"法律义务": "正确。“法律义务”指法律要求你必须做的事，与“你知道自己有什么”的提问相合。", "天气": "语义：天气指气候状况，不是要履行的事，不合句意。", "年龄": "搭配：“有什么年龄”不成说法，应说“多大年纪”。", "秒针": "语义：秒针是钟表的部件，人身上没有，不能说“你知道自己有什么秒针吗”。"}, "sentence_index": 6, "correct_answer": "法律义务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次失误的法律义务在我。", "explanation": "这里应该用〈责任〉。“法律义务”指法律规定必须做的事，不用来说失误的过错归属，应说“责任在我”。"}, {"text": "学校规定，学生有一首法律义务。", "explanation": "这里应该用〈项〉。“首”用于诗歌、歌曲等，不能量化抽象的“法律义务”。"}, {"text": "他对朋友的法律义务是周末搬家。", "explanation": "这里应该用〈承诺〉。朋友之间的约定应说“承诺”，“法律义务”指法律规定的责任。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "按时缴税，这是每个人的一台法律义务。", "corrected_sentence": "按时缴税，这是每个人的一项法律义务。", "error_description": "量词错误：“法律义务”是抽象的责任，应说“一项法律义务”；“一台”用于机器等，不能用于责任。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他承担了一只法律义务，必须按时纳税。", "corrected_sentence": "他承担了一项法律义务，必须按时纳税。", "error_description": "量词错误：“法律义务”应说“一项”；“一只”用于动物，不能用于抽象的责任。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd32f6046-6ad7-4f2f-b2de-6bfbc4558f4b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
