INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是很好，没有不好的地方。", "primary_collocate": null, "pronunciation": "wán měi", "ipa": "wan³⁵ mei̯²¹⁴", "syllable_count": 2, "sentences": [{"text": "这道菜的味道很完美，我吃了两碗饭。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的字写得很完美，像印出来的一样。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个答案很完美，一个错误也没有。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚的音乐会完美结束，观众都站起来鼓掌。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的大小对我来说太完美了。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结果很完美，我们队拿了第一。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这个房子的位置很完美，离学校很近。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的回答很完美，老师很满意。", "target_word": "完美", "complexity_tier": "T3", "furigana": "tā de huídá hěn wánměi, lǎoshī hěn mǎnyì", "sentence_source": "generated"}, {"text": "天气、风景和朋友，一切都很完美。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他完美地完成了任务，经理非常高兴。", "target_word": "完美", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "完美地", "label": "状语形式"}, {"form": "完美主义", "label": "复合词"}, {"form": "完美无缺", "label": "复合词"}], "register": "中性", "sense_fingerprint": "形容词：很好，没有不好的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477f6bce-3da5-4648-b3b5-63365f3456a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。「我吃了两碗饭」说明味道很好，「完美」指很好、没有不好的地方，正相符。"}, {"text": "苦", "is_correct": false, "explanation": "语义：「苦」是不好的味道，与「我吃了两碗饭」所表示的满意相矛盾。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：「粗」多形容粗细或质地，不用来形容味道。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：「硬」形容质地，不用来形容味道。"}], "explanations": {"完美": "正确。「我吃了两碗饭」说明味道很好，「完美」指很好、没有不好的地方，正相符。", "苦": "语义：「苦」是不好的味道，与「我吃了两碗饭」所表示的满意相矛盾。", "粗": "搭配：「粗」多形容粗细或质地，不用来形容味道。", "硬": "搭配：「硬」形容质地，不用来形容味道。"}, "sentence_index": 0, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次作业很完美，错字却多得数不清。", "explanation": "这里应该用〈不错〉。「完美」表示没有任何缺点，后半句却说错字多得数不清，前后自相矛盾；只说整体较好时用「不错」。"}, {"text": "这杯牛奶很完美，洒得桌上到处都是。", "explanation": "这里应该用〈挺好〉。「完美」表示没有缺点，「洒得桌上到处都是」是明显的失误，两者矛盾；只说整体较好时用「挺好」。"}, {"text": "他的身体很完美，却在床上躺了整整两天。", "explanation": "这里应该用〈挺好〉。「完美」表示没有任何缺陷，「躺了两天」说明身体并非无恙，两者矛盾；只说身体较好时用「挺好」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "完美", "is_correct": true, "explanation": "正确。后半句「离学校很近」说明位置便利，「完美」表示很好、没有不好的地方，与之相合。"}, {"text": "远", "is_correct": false, "explanation": "语义：「远」与后半句「离学校很近」矛盾，位置不可能既远又近。"}, {"text": "寂寞", "is_correct": false, "explanation": "搭配：「寂寞」多用于人，不用来形容房子的位置。"}, {"text": "伤心", "is_correct": false, "explanation": "搭配：「伤心」形容人的情绪，不能用来形容房子的位置。"}], "explanations": {"完美": "正确。后半句「离学校很近」说明位置便利，「完美」表示很好、没有不好的地方，与之相合。", "远": "语义：「远」与后半句「离学校很近」矛盾，位置不可能既远又近。", "寂寞": "搭配：「寂寞」多用于人，不用来形容房子的位置。", "伤心": "搭配：「伤心」形容人的情绪，不能用来形容房子的位置。"}, "sentence_index": 6, "correct_answer": "完美"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盘菜很完美，咸得没法入口。", "explanation": "这里应该用〈挺好〉。「完美」表示没有缺点，「咸得没法入口」是明显的缺点，两者矛盾；只说整体较好时用「挺好」。"}, {"text": "这次我的答题很完美，却只得了零分。", "explanation": "这里应该用〈认真〉。「完美」指结果没有缺陷，「只得了零分」说明答题并不好，两者矛盾；只说态度认真时用「认真」。"}, {"text": "这份合同的内容很完美，还漏掉了一条重要条款。", "explanation": "这里应该用〈基本完整〉。「完美」指没有任何缺陷，「漏掉了一条重要条款」是缺陷，两者矛盾；只说大体齐全时用「基本完整」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的晚餐安排完美极了，大家都吃得很开心。", "corrected_sentence": "这次的晚餐安排得完美极了，大家都吃得很开心。", "error_description": "错误形式：「安排完美极了」。正确形式：「安排得完美极了」。表示程度的补语要用「得」连接动词和形容词，漏掉「得」不成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这份报告写很完美，老师很满意。", "corrected_sentence": "他把这份报告写得很完美，老师很满意。", "error_description": "错误形式：「写很完美」。正确形式：「写得很完美」。表示程度的补语要用「得」连接动词和形容词，漏掉「得」不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "坏", "is_correct": true, "explanation": "正确：“坏”与“好”构成反义关系，指心情不好。"}, {"text": "慢", "is_correct": false, "explanation": "与“好”无反义或近义关系：“慢”是“快”的反义词。"}, {"text": "远", "is_correct": false, "explanation": "与“好”无反义或近义关系：“远”指距离长。"}, {"text": "硬", "is_correct": false, "explanation": "与“好”无反义或近义关系：“硬”指质地坚实。"}], "correct_answer": "坏", "explanations": {"坏": "正确：“坏”与“好”构成反义关系，指心情不好。", "慢": "与“好”无反义或近义关系：“慢”是“快”的反义词。", "远": "与“好”无反义或近义关系：“远”指距离长。", "硬": "与“好”无反义或近义关系：“硬”指质地坚实。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "差", "is_correct": true, "explanation": "正确：“差”与“好”构成反义关系，指质量不好。"}, {"text": "厚", "is_correct": false, "explanation": "与“好”无反义或近义关系：“厚”指厚度大。"}, {"text": "重", "is_correct": false, "explanation": "与“好”无反义或近义关系：“重”指分量大。"}, {"text": "高", "is_correct": false, "explanation": "与“好”无反义或近义关系：“高”指高度。"}], "correct_answer": "差", "explanations": {"差": "正确：“差”与“好”构成反义关系，指质量不好。", "厚": "与“好”无反义或近义关系：“厚”指厚度大。", "重": "与“好”无反义或近义关系：“重”指分量大。", "高": "与“好”无反义或近义关系：“高”指高度。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好的意思是让人觉得开心、满意。", "primary_collocate": null, "pronunciation": "hǎo", "ipa": "xau˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天天气真好。", "target_word": "好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的服务很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有一个好朋友。", "target_word": "好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的心情今天很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书很好，我想再看一遍。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹的成绩很好，妈妈很高兴。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上我睡得很好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的空气比城里好。", "target_word": "好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天是出去玩的好时候。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他的字写得很好。", "target_word": "好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好好", "label": "重叠"}, {"form": "更好", "label": "比较"}, {"form": "好看", "label": "复合"}], "register": "口语", "sense_fingerprint": "好：事物或人的质量、状态令人开心、满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a7f8796-b995-49d4-a98e-f68767af4dc6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音，表示令人开心、满意。"}, {"text": "号", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。"}, {"text": "毫", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。"}, {"text": "海", "is_correct": false, "explanation": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。"}, {"text": "考", "is_correct": false, "explanation": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。"}, {"text": "老", "is_correct": false, "explanation": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音，表示令人开心、满意。", "号": "hào（第四声）与 hǎo（第三声）声调不同，意思是号码、号召。", "毫": "háo（第二声）与 hǎo（第三声）声调不同，意思是毫米、一点点（毫不）。", "海": "hǎi 与 hǎo 韵母不同（ai 与 ao），意思是海洋。", "考": "kǎo 与 hǎo 声母不同（k 与 h），意思是考试。", "老": "lǎo 与 hǎo 声母不同（l 与 h），意思是年纪大、陈旧。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“真好”评价天气令人满意，符合语境。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”说速度，不能用来形容天气。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容物体质地，不说天气硬。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，不能用来形容天气。"}], "explanations": {"好": "正确：“真好”评价天气令人满意，符合语境。", "快": "语义：“快”说速度，不能用来形容天气。", "硬": "搭配：“硬”形容物体质地，不说天气硬。", "重": "语义：“重”说分量，不能用来形容天气。"}, "sentence_index": 0, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "作业终于做好了，我们可以去玩了。", "explanation": "这里的「好」表示完成、做完，是另一个意思，不表示令人开心、满意。"}, {"text": "好，我马上就去。", "explanation": "这里的「好」是应答语，表示同意，是另一个意思，不表示令人开心、满意。"}, {"text": "他的病好了，明天可以去上学了。", "explanation": "这里的「好」表示病愈，是另一个意思，不表示令人开心、满意。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "好", "is_correct": true, "explanation": "正确答案。hǎo（第三声）是“好”的读音。"}, {"text": "耗", "is_correct": false, "explanation": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。"}, {"text": "豪", "is_correct": false, "explanation": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。"}, {"text": "草", "is_correct": false, "explanation": "cǎo 与 hǎo 声母不同（c 与 h），意思是草。"}, {"text": "宝", "is_correct": false, "explanation": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。"}], "explanations": {"好": "正确答案。hǎo（第三声）是“好”的读音。", "耗": "hào（第四声）与 hǎo（第三声）声调不同，意思是消耗。", "豪": "háo（第二声）与 hǎo（第三声）声调不同，意思是豪迈、豪华。", "草": "cǎo 与 hǎo 声母不同（c 与 h），意思是草。", "宝": "bǎo 与 hǎo 声母不同（b 与 h），意思是宝贝。"}, "sentence_index": null, "correct_answer": "好"}, "level_3": {"options": [{"text": "好", "is_correct": true, "explanation": "正确：“睡得很好”评价睡眠质量，符合语境。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，不能形容睡眠。"}, {"text": "高", "is_correct": false, "explanation": "语义：“高”指高度，不能形容睡眠的状态。"}, {"text": "贵", "is_correct": false, "explanation": "搭配：“贵”形容价格，不能修饰“睡得”。"}], "explanations": {"好": "正确：“睡得很好”评价睡眠质量，符合语境。", "亮": "语义：“亮”指光线明亮，不能形容睡眠。", "高": "语义：“高”指高度，不能形容睡眠的状态。", "贵": "搭配：“贵”形容价格，不能修饰“睡得”。"}, "sentence_index": 6, "correct_answer": "好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师对他的字很好。", "explanation": "这里应该用〈满意〉。「对……好」指待人好，评价作品要说「对……很满意」，而不是「对……很好」。"}, {"text": "他对自己的字很好。", "explanation": "这里应该用〈得意〉。“对……好”指待人好，对自己作品的自豪要说“得意”。"}, {"text": "我对这个结果很好。", "explanation": "这里应该用〈满足〉。“对……好”指待人好，对结果的满意要说“满足”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹在学校有很好朋友。", "corrected_sentence": "我妹妹在学校有好朋友。", "error_description": "错误：“很好朋友”。正确：“好朋友”。“好”作定语修饰名词时，前面不能直接加“很”；要说“很好的朋友”需加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行的天气好很。", "corrected_sentence": "这次旅行的天气很好。", "error_description": "错误：“好很”。正确：“很好”。副词“很”作状语，须放在形容词“好”的前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25c7b2f3-445d-4298-bf71-266e6df41c79') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
