INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27532, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听到别人说的话后，明白了意思。", "primary_collocate": null, "pronunciation": "tīng dǒng", "ipa": "tʰiŋ˥ tʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他听懂了老师的问题。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事很简单，孩子们都听懂了。", "target_word": "听懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国人说得太快，我没听懂。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了三遍，我才听懂他的意思。", "target_word": "听懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她刚学中文，已经能听懂简单的话。", "target_word": "听懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听懂我的意思了吗？", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说的方言，我一半听懂了。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广播里说了什么，你听懂了吗？", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他点点头，好像听懂了。", "target_word": "听懂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "只要多听，就能慢慢听懂新闻。", "target_word": "听懂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听懂了", "label": "体标"}, {"form": "没听懂", "label": "否定"}, {"form": "听得懂", "label": "可能补语"}, {"form": "聽懂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "听了别人的话之后明白意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '477f6bce-3da5-4648-b3b5-63365f3456a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听懂", "is_correct": true, "explanation": "正确。「听懂」指理解老师问题的内容，与句子的意思相合。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」的对象是食物，不能带「问题」作宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」只带衣服、鞋袜等对象，不能用于「问题」。"}, {"text": "哭", "is_correct": false, "explanation": "配价：「哭」是不及物动词，后面不能带宾语「问题」。"}], "explanations": {"听懂": "正确。「听懂」指理解老师问题的内容，与句子的意思相合。", "吃": "搭配：「吃」的对象是食物，不能带「问题」作宾语。", "穿": "搭配：「穿」只带衣服、鞋袜等对象，不能用于「问题」。", "哭": "配价：「哭」是不及物动词，后面不能带宾语「问题」。"}, "sentence_index": 0, "correct_answer": "听懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "开会时，我一直听懂他的表情。", "explanation": "这里应该用〈注意〉。「听懂」的对象是别人说的话，观察表情要用「注意」。"}, {"text": "这封信，我一眼就听懂了。", "explanation": "这里应该用〈读懂〉。「一眼」说明是看，书面内容要用「读懂」，「听懂」只用于听到的话语。"}, {"text": "我能听懂这座山的高度。", "explanation": "这里应该用〈看出〉。「听懂」只用于理解话语的内容，山的高度要靠视觉判断，应说「看出」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听懂", "is_correct": true, "explanation": "正确。「一半」说明只理解了一部分，「听懂」与「方言」的语境相合。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」的对象是饮料，不能用于「方言」。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」的对象是物体，不能与「方言」搭配。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」与「说方言」的语境无关，句子意思不通。"}], "explanations": {"听懂": "正确。「一半」说明只理解了一部分，「听懂」与「方言」的语境相合。", "喝": "搭配：「喝」的对象是饮料，不能用于「方言」。", "洗": "搭配：「洗」的对象是物体，不能与「方言」搭配。", "睡": "语义：「睡」与「说方言」的语境无关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "听懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我一闻就听懂了那是桂花的香味。", "explanation": "这里应该用〈闻到〉。「听懂」只用于理解话语，香味要用嗅觉词「闻到」。"}, {"text": "他能听懂颜色的不同。", "explanation": "这里应该用〈辨认〉。「听懂」的对象是话语，颜色的不同要用「辨认」。"}, {"text": "我终于听懂了观众的人数。", "explanation": "这里应该用〈数清〉。「听懂」指理解话语，数人数要用「数清」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我终于听懂得他说的话。", "corrected_sentence": "我终于听懂了他说的话。", "error_description": "错误形式：「听懂得」。正确形式：「听懂了」。表示动作已经完成要用「了」；「得」用于可能补语或程度补语，这里不能用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天那段录音，我不听懂开头。", "corrected_sentence": "昨天那段录音，我没听懂开头。", "error_description": "错误形式：「不听懂」。正确形式：「没听懂」。句子说的是「昨天」已经发生的事，否定要用「没」，不能用「不」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43f752ac-a758-40a7-916c-c404be2f5547') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
