INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "看，用眼睛看东西。", "primary_collocate": null, "pronunciation": "chá kàn", "ipa": "ʈʂʰa˧˥ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他蹲下来查看地上的小虫子。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈查看了孩子的手。", "target_word": "查看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生查看他的眼睛。", "target_word": "查看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我打开门，查看外面有没有人。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师走过来查看我的画。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着灯，查看桌子下面。", "target_word": "查看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你查看一下这只鞋子。", "target_word": "查看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸查看了车的轮子。", "target_word": "查看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她仔细查看着那朵花。", "target_word": "查看", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站起来，查看四周。", "target_word": "查看", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "查看了", "label": "体标"}, {"form": "查看着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用眼睛仔细看眼前的东西或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27534, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "查看", "is_correct": true, "explanation": "正确：蹲下来用眼睛仔细看地上的小虫子。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：品尝是用嘴感受味道，不能用来描述看小虫子。"}, {"text": "烹饪", "is_correct": false, "explanation": "搭配：“烹饪”的对象是食物，不说“烹饪小虫子”。"}, {"text": "搭建", "is_correct": false, "explanation": "搭配：“搭建”的对象是房屋、平台等，不说“搭建小虫子”。"}], "explanations": {"查看": "正确：蹲下来用眼睛仔细看地上的小虫子。", "品尝": "语义：品尝是用嘴感受味道，不能用来描述看小虫子。", "烹饪": "搭配：“烹饪”的对象是食物，不说“烹饪小虫子”。", "搭建": "搭配：“搭建”的对象是房屋、平台等，不说“搭建小虫子”。"}, "sentence_index": 0, "correct_answer": "查看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她慢慢查看着这块蛋糕的甜味。", "explanation": "这里应该用〈品尝〉。甜味要用舌头品尝，“查看”指用眼睛看东西，不能用于味觉。"}, {"text": "我在剧院查看了一场演出。", "explanation": "这里应该用〈观看〉。演出要用观看，“查看”偏向仔细察看眼前的东西。"}, {"text": "她站在雪地里，查看着寒风。", "explanation": "这里应该用〈感受〉。寒风要用身体感受，“查看”指用眼睛看东西，不用于感觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "查看", "is_correct": true, "explanation": "正确：仔细看这只鞋子。"}, {"text": "演奏", "is_correct": false, "explanation": "语义：鞋子不能演奏，演奏用于乐器或乐曲。"}, {"text": "烘焙", "is_correct": false, "explanation": "搭配：“烘焙”的对象是食物，不说“烘焙鞋子”。"}, {"text": "哄", "is_correct": false, "explanation": "搭配：“哄”的对象一般是人，不说“哄鞋子”。"}], "explanations": {"查看": "正确：仔细看这只鞋子。", "演奏": "语义：鞋子不能演奏，演奏用于乐器或乐曲。", "烘焙": "搭配：“烘焙”的对象是食物，不说“烘焙鞋子”。", "哄": "搭配：“哄”的对象一般是人，不说“哄鞋子”。"}, "sentence_index": 6, "correct_answer": "查看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他站起来，查看远处飘来的花香。", "explanation": "这里应该用〈闻〉。花香要用鼻子闻，“查看”指用眼睛看东西，不能用于气味。"}, {"text": "他站起来，查看四周的声音。", "explanation": "这里应该用〈聆听〉。声音要用耳朵听，“查看”指用眼睛仔细看。"}, {"text": "他躺在草地上，查看着温暖。", "explanation": "这里应该用〈享受〉。温暖要靠身体感受，“查看”指用眼睛看东西，不能用来享受温暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他仔细查看着了那只虫子。", "corrected_sentence": "他仔细查看了那只虫子。", "error_description": "体标叠加错误：“查看”后的“着”表示动作持续，不能再接表示完成的“了”（“睡着了”中的“着”是结果补语，不同）。应说“查看了”，去掉“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他查看了过这只鞋子，没有发现问题。", "corrected_sentence": "他查看过这只鞋子，没有发现问题。", "error_description": "体标错误：“了”和“过”不能同时用在一个动词后，表示经历用“过”，应说“查看过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
