INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27536, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个新东西出现，比如新玩具或新书。", "primary_collocate": null, "pronunciation": "tuī chū", "ipa": "tʰueɪ˥ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "那家玩具店推出了新玩具。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出版社下个月推出一本新书。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店推出了新的冰淇淋。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司推出了一个新的小游戏。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们每年夏天都推出新衣服。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校推出了一本新的画册。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包店今天推出了新蛋糕。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个牌子推出过很多好玩的玩具。", "target_word": "推出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，下周出版社会推出新书。", "target_word": "推出", "complexity_tier": "T3", "furigana": "lǎo shī shuō, xià zhōu chū bǎn shè huì tuī chū xīn shū.", "sentence_source": "generated"}, {"text": "孩子们很喜欢这家店新推出的玩具。", "target_word": "推出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "推出了", "label": "体标"}, {"form": "推出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "让新玩具、新书等新东西出现在大家面前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指让新的东西出现在大家面前。"}, {"text": "退出", "is_correct": false, "explanation": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。"}, {"text": "吹出", "is_correct": false, "explanation": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。"}, {"text": "追出", "is_correct": false, "explanation": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指让新的东西出现在大家面前。", "退出": "退出 tuìchū 第一个音节声调不同（tuì 第四声，tuī 第一声），意思是离开某个组织或场所。", "吹出": "吹出 chuīchū 第一个音节声母不同（ch 与 t），意思是用力把气或东西吹出来。", "追出": "追出 zhuīchū 第一个音节声母不同（zh 与 t），意思是追赶着跑到外面去。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“那家玩具店推出了新玩具”指让新玩具出现在大家面前，符合句中语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：玩具店不会吃玩具，“吃”与句中“玩具店”的语境冲突。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象通常是饮品，不能接“新玩具”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象通常是歌曲，不能接“新玩具”。"}], "explanations": {"推出": "正确答案。“那家玩具店推出了新玩具”指让新玩具出现在大家面前，符合句中语境。", "吃": "语义：玩具店不会吃玩具，“吃”与句中“玩具店”的语境冲突。", "喝": "搭配：“喝”的对象通常是饮品，不能接“新玩具”。", "唱": "搭配：“唱”的对象通常是歌曲，不能接“新玩具”。"}, "sentence_index": 0, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在班会上推出了一个问题，大家都在讨论。", "explanation": "这里应该用〈提出〉。提出用于问题、意见；推出用于让新的物品或服务出现在大家面前。"}, {"text": "他用力把箱子推出了门外，因为箱子太重。", "explanation": "这里是“推出”表示用力使物体离开某处的意思，不表示让新东西出现，与句意不符。"}, {"text": "老师推出了一本新书给我，我很喜欢。", "explanation": "这里应该用〈推荐〉。推荐指把好的东西介绍给别人；推出是让新东西出现在大家面前，不能用于对个人的介绍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27536, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。推出 tuīchū，指让新的东西出现在大家面前。"}, {"text": "突出", "is_correct": false, "explanation": "突出 tūchū 与推出只差韵母（tū 与 tuī），意思是高于周围或显眼。"}, {"text": "脱出", "is_correct": false, "explanation": "脱出 tuōchū 第一个音节的韵母和声调都与 tuī 不同（tuō 第二声，tuī 第一声），意思是挣脱后从某处出来。"}, {"text": "催出", "is_correct": false, "explanation": "催出 cuīchū 第一个音节声母不同（c 与 t），意思是促使某物显现出来。"}], "explanations": {"推出": "正确答案。推出 tuīchū，指让新的东西出现在大家面前。", "突出": "突出 tūchū 与推出只差韵母（tū 与 tuī），意思是高于周围或显眼。", "脱出": "脱出 tuōchū 第一个音节的韵母和声调都与 tuī 不同（tuō 第二声，tuī 第一声），意思是挣脱后从某处出来。", "催出": "催出 cuīchū 第一个音节声母不同（c 与 t），意思是促使某物显现出来。"}, "sentence_index": null, "correct_answer": "推出"}, "level_3": {"options": [{"text": "推出", "is_correct": true, "explanation": "正确答案。“面包店今天推出了新蛋糕”指让新蛋糕出现在大家面前，符合句中语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是衣物或器具，不能接“新蛋糕”。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”的对象通常是损坏的物品，不能用来形容新蛋糕。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，与“今天推出新蛋糕”的语境相反。"}], "explanations": {"推出": "正确答案。“面包店今天推出了新蛋糕”指让新蛋糕出现在大家面前，符合句中语境。", "洗": "搭配：“洗”的对象通常是衣物或器具，不能接“新蛋糕”。", "修": "搭配：“修”的对象通常是损坏的物品，不能用来形容新蛋糕。", "扔": "语义：扔是丢弃，与“今天推出新蛋糕”的语境相反。"}, "sentence_index": 6, "correct_answer": "推出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他推出了一个笑话，大家都笑了。", "explanation": "这里应该用〈讲〉。讲笑话是把笑话说给别人听；推出用于让新的物品或服务出现在大家面前。"}, {"text": "我把书推出了书架，因为它太旧。", "explanation": "这里是“推出”表示用力使物体离开某处的意思，不表示让新东西出现，与句意不符。"}, {"text": "店员把旧玩具推出了柜台，因为卖不掉。", "explanation": "这里是“推出”表示用力使物体离开某处的意思，不表示让新东西出现，与句意不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店没推出了新玩具。", "corrected_sentence": "这家店没推出新玩具。", "error_description": "体标错误：否定句中“没”与“了”不能同时用在动词后，应说“没推出”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出版社去年推出了过一本新书。", "corrected_sentence": "出版社去年推出过一本新书。", "error_description": "体标用错了。“推出过”表示曾经做过某事，“过”不能与“了”同时出现在“推出”后面，正确形式是“推出过”，错误形式写成“推出了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
