INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "帮别人做事情的人。", "primary_collocate": null, "pronunciation": "zhù shǒu", "ipa": "ʈʂu˥˩ ʂoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小王是我的助手，每天帮我做事。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师的助手在洗菜。", "target_word": "助手", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想找一个助手帮我看店。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的助手把东西都准备好了。", "target_word": "助手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让两个学生做她的助手。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工作太多了，我需要助手。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当了医生的助手，学到很多。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的助手每天早上八点来上班。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好助手不会让老板担心。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈做饭时，我是她的助手，帮她切菜。", "target_word": "助手", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个助手", "label": "量词"}, {"form": "小助手", "label": "复合"}], "register": "中性", "sense_fingerprint": "帮别人做事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '499dcf25-efda-40b6-ac5d-8424935f606b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指帮别人做事的人。"}, {"text": "部首", "is_correct": false, "explanation": "部首 bùshǒu 第一个音节声母不同（b 与 zh），意思是汉字的偏旁部件。"}, {"text": "触手", "is_correct": false, "explanation": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够接触到的地方。"}, {"text": "祝寿", "is_correct": false, "explanation": "祝寿 zhùshòu 第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。"}, {"text": "猪手", "is_correct": false, "explanation": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指帮别人做事的人。", "部首": "部首 bùshǒu 第一个音节声母不同（b 与 zh），意思是汉字的偏旁部件。", "触手": "触手 chùshǒu 第一个音节声母不同（ch 与 zh），意思是能够接触到的地方。", "祝寿": "祝寿 zhùshòu 第二个音节声调不同（shòu 第四声，shǒu 第三声），意思是庆祝生日。", "猪手": "猪手 zhūshǒu 第一个音节声调不同（zhū 第一声，zhù 第四声），意思是猪蹄。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“小王是我的助手”指帮我做事的人，与“每天帮我做事”一致。"}, {"text": "老板", "is_correct": false, "explanation": "语义：老板是管理者，不会被说成每天来帮我做事，与句中“帮我做事”的语境冲突。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“钢笔”是物品，不能作为“每天帮我做事”的主语。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑物，不能每天帮我做事，与句中语境冲突。"}], "explanations": {"助手": "正确答案。“小王是我的助手”指帮我做事的人，与“每天帮我做事”一致。", "老板": "语义：老板是管理者，不会被说成每天来帮我做事，与句中“帮我做事”的语境冲突。", "钢笔": "搭配：“钢笔”是物品，不能作为“每天帮我做事”的主语。", "房子": "语义：房子是建筑物，不能每天帮我做事，与句中语境冲突。"}, "sentence_index": 0, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台洗衣机是我家的好助手，每天帮我洗衣服。", "explanation": "这里是〈助手〉的另一个意思，指帮人做事的机器，不指人。定义中的〈助手〉指帮别人做事的人，这里用来指物，用法不对。"}, {"text": "我的助手和我经常比赛，谁赢谁输都很高兴。", "explanation": "这里应该用〈对手〉。助手是帮别人做事的人，与自己比赛的是对手，两者不能互换。"}, {"text": "他是这家公司的助手，每天负责决定公司的发展方向。", "explanation": "助手是帮别人做事的人，不负责决定公司的方向。这里把决策者说成助手，角色用错了，应该用〈总经理〉或〈负责人〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。助手 zhùshǒu，指帮别人做事的人。"}, {"text": "着手", "is_correct": false, "explanation": "着手 zhuóshǒu 第一个音节声调不同（zhuó 第二声，zhù 第四声），意思是开始动手去做。"}, {"text": "追手", "is_correct": false, "explanation": "追手 zhuīshǒu 第一个音节韵母与声调不同（zhuī 第一声，zhù 第四声），意思是追赶的人。"}, {"text": "只手", "is_correct": false, "explanation": "只手 zhīshǒu 第一个音节韵母与声调不同（zhī 第一声，zhù 第四声），意思是一只手，常见于“只手遮天”。"}], "explanations": {"助手": "正确答案。助手 zhùshǒu，指帮别人做事的人。", "着手": "着手 zhuóshǒu 第一个音节声调不同（zhuó 第二声，zhù 第四声），意思是开始动手去做。", "追手": "追手 zhuīshǒu 第一个音节韵母与声调不同（zhuī 第一声，zhù 第四声），意思是追赶的人。", "只手": "只手 zhīshǒu 第一个音节韵母与声调不同（zhī 第一声，zhù 第四声），意思是一只手，常见于“只手遮天”。"}, "sentence_index": null, "correct_answer": "助手"}, "level_3": {"options": [{"text": "助手", "is_correct": true, "explanation": "正确答案。“她当了医生的助手”指在医生身边协助工作，符合句中“学到很多”的语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人是接受治疗的人，不会在医生身边工作，与“当了……的”的语境冲突。"}, {"text": "药", "is_correct": false, "explanation": "搭配：“医生的药”不能说成“当了医生的药”，“当”后面不能接物品来表示职务。"}, {"text": "病历", "is_correct": false, "explanation": "语义：病历是记录病情的文件，不能被“当”成职务，与句中的语境冲突。"}], "explanations": {"助手": "正确答案。“她当了医生的助手”指在医生身边协助工作，符合句中“学到很多”的语境。", "病人": "语义：病人是接受治疗的人，不会在医生身边工作，与“当了……的”的语境冲突。", "药": "搭配：“医生的药”不能说成“当了医生的药”，“当”后面不能接物品来表示职务。", "病历": "语义：病历是记录病情的文件，不能被“当”成职务，与句中的语境冲突。"}, "sentence_index": 6, "correct_answer": "助手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台旧机器是我的老助手，我把它卖给了邻居。", "explanation": "这里是〈助手〉的另一个意思，指辅助工作的机器，不指人。句中说的是机器，与定义中“帮别人做事的人”不同。"}, {"text": "我们班的助手是老师，负责管理全班。", "explanation": "助手是辅助性的角色，不负责全面管理。这里把老师说成助手，身份用错了。"}, {"text": "小狗是我的助手，每天负责睡觉。", "explanation": "这里把〈助手〉用成了〈宠物〉的意思，指陪伴人的动物，而不是协助别人做事的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一条助手，每天帮我做饭。", "corrected_sentence": "我有一位助手，每天帮我做饭。", "error_description": "量词错误：“助手”指人，应用“位”或“个”，“条”多用于细长的东西，不能用于人。错误形式“一条助手”应改为“一位助手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院新请了一只助手，负责帮护士整理病历。", "corrected_sentence": "医院新请了一个助手，负责帮护士整理病历。", "error_description": "量词用错了。“助手”指人，应用“个”或“位”，不能用“只”。“只”多用于动物或成对的器物，错误形式把“助手”当成了动物或器物。正确形式是“一个助手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6ca7f8d-3f72-4d24-9866-9694356ed35b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
