INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做电脑程序的人。", "primary_collocate": null, "pronunciation": "kāi fā zhě", "ipa": "kʰaɪ̯⁵⁵ fa⁵⁵ ʈʂɤ²¹⁴", "syllable_count": 3, "sentences": [{"text": "他是做手机游戏的开发者。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥是一名软件开发者。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开发者正在写新的程序。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个网站的开发者住在上海。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开发者让这个软件更好用了。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她小时候就想当开发者。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司请了两位开发者做新应用。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发者给用户发了一封信。", "target_word": "开发者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的开发者会认真听用户的话。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位开发者做过很多有名的软件。", "target_word": "开发者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位开发者", "label": "量词"}, {"form": "一名开发者", "label": "量词"}, {"form": "開發者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做电脑程序的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开发者", "is_correct": true, "explanation": "正确。“开发者”指做电脑程序的人，与“做手机游戏”的语境吻合。"}, {"text": "玩家", "is_correct": false, "explanation": "语义：玩家是玩游戏的人，与句中“做游戏”的语境不符。"}, {"text": "厨子", "is_correct": false, "explanation": "语义：厨子是做菜的人，与“做手机游戏”的语境不符。"}, {"text": "大爷", "is_correct": false, "explanation": "语义与语域：“大爷”指老年男子或摆架子的人，与“做手机游戏的”人不符，且是口语词。"}], "explanations": {"开发者": "正确。“开发者”指做电脑程序的人，与“做手机游戏”的语境吻合。", "玩家": "语义：玩家是玩游戏的人，与句中“做游戏”的语境不符。", "厨子": "语义：厨子是做菜的人，与“做手机游戏”的语境不符。", "大爷": "语义与语域：“大爷”指老年男子或摆架子的人，与“做手机游戏的”人不符，且是口语词。"}, "sentence_index": 0, "correct_answer": "开发者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的开发者是一位年轻人。", "explanation": "这里应该用〈作家〉。开发者指做电脑程序的人，不用于写书的人。"}, {"text": "这个网站的一台开发者住在上海。", "explanation": "量词用错了。“台”用于机器，开发者是人，应用“位”或“名”。"}, {"text": "这幅画的开发者住在上海。", "explanation": "这里应该用〈画家〉。开发者指做电脑程序的人，不用于画作的创作者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发者", "is_correct": true, "explanation": "正确。“开发者”指做电脑程序的人，符合公司请人做新应用的语境。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师做菜，不做软件应用，与句中语境不符。"}, {"text": "保安", "is_correct": false, "explanation": "语义：保安负责安保，不做新应用，与句中语境冲突。"}, {"text": "老头", "is_correct": false, "explanation": "语义与语域：“老头”指老年男子，与“做新应用”的开发者不符，且是口语词。"}], "explanations": {"开发者": "正确。“开发者”指做电脑程序的人，符合公司请人做新应用的语境。", "厨师": "语义：厨师做菜，不做软件应用，与句中语境不符。", "保安": "语义：保安负责安保，不做新应用，与句中语境冲突。", "老头": "语义与语域：“老头”指老年男子，与“做新应用”的开发者不符，且是口语词。"}, "sentence_index": 6, "correct_answer": "开发者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位开发者创作过很多有名的歌曲。", "explanation": "这里应该用〈作曲家〉。开发者指做电脑程序的人，不指创作歌曲的人。"}, {"text": "这辆开发者做过很多有名的软件。", "explanation": "量词用错了。“辆”用于车辆，开发者是人，应用“位”或“名”。"}, {"text": "这位开发者做过很多有名的手术。", "explanation": "这里应该用〈医生〉。开发者指做电脑程序的人，不做手术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天都在开发者电脑程序。", "corrected_sentence": "他每天都在开发电脑程序。", "error_description": "词类错误。“开发者”是名词，指人，不能当动词用；此处应用动词“开发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两台开发者很有名。", "corrected_sentence": "这两位开发者很有名。", "error_description": "量词错误。“台”用于机器、设备，开发者是人，应用“位”。正确句为“这两位开发者很有名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
