INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人替另一个人做事情。", "primary_collocate": null, "pronunciation": "dài lǐ", "ipa": "taɪ̯⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "经理出差了，小李代理他的工作。", "target_word": "代理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师生病了，王老师暂时代理他的教学工作。", "target_word": "代理", "complexity_tier": "T3", "furigana": "dài lǐ", "sentence_source": "generated"}, {"text": "校长不在，由副校长代理校长的工作。", "target_word": "代理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不在的时候，请小张代理我的工作。", "target_word": "代理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他代理局长一职已经三个月了。", "target_word": "代理", "complexity_tier": "T3", "furigana": "dài lǐ", "sentence_source": "generated"}, {"text": "经理走了，谁来代理这个职位？", "target_word": "代理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，请你代理他的职务。", "target_word": "代理", "complexity_tier": "T3", "furigana": "dài lǐ", "sentence_source": "generated"}, {"text": "老板回国了，他的弟弟代理店长。", "target_word": "代理", "complexity_tier": "T3", "furigana": "dài lǐ", "sentence_source": "generated"}, {"text": "她代理过一年班主任。", "target_word": "代理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理休假时，由副总经理代理。", "target_word": "代理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "代理了", "label": "体标"}, {"form": "代理过", "label": "体标"}, {"form": "代理着", "label": "体标"}, {"form": "代理人", "label": "复合"}], "register": "书面", "sense_fingerprint": "暂时替别人做工作或事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7833e8da-174d-473c-8fad-ba990596ff35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "代理", "is_correct": true, "explanation": "代理（dài lǐ）指暂时替别人做事，是正确答案。"}, {"text": "大礼", "is_correct": false, "explanation": "dà 与 dài 韵母不同（少了 -i），大礼指隆重的仪式。"}, {"text": "代指", "is_correct": false, "explanation": "lǐ 与 zhǐ 声母不同（l- 与 zh-），代指指用一事物代替另一事物来称呼。"}, {"text": "代领", "is_correct": false, "explanation": "dài 相同，lǐng 比 lǐ 多韵尾 -ng，代领指替别人领取。"}], "explanations": {"代理": "代理（dài lǐ）指暂时替别人做事，是正确答案。", "大礼": "dà 与 dài 韵母不同（少了 -i），大礼指隆重的仪式。", "代指": "lǐ 与 zhǐ 声母不同（l- 与 zh-），代指指用一事物代替另一事物来称呼。", "代领": "dài 相同，lǐng 比 lǐ 多韵尾 -ng，代领指替别人领取。"}, "sentence_index": null, "correct_answer": "代理"}, "level_3": {"options": [{"text": "代理", "is_correct": true, "explanation": "正确。“代理”指暂时替别人做工作，与经理出差的语境吻合。"}, {"text": "辞去", "is_correct": false, "explanation": "语义：“辞去”指离职，与经理出差、小李暂时接手的语境相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“工作”一般不作“吃”的宾语，二者不搭配。"}, {"text": "撤销", "is_correct": false, "explanation": "语义：“撤销”指取消，经理出差时不会取消他的工作。"}], "explanations": {"代理": "正确。“代理”指暂时替别人做工作，与经理出差的语境吻合。", "辞去": "语义：“辞去”指离职，与经理出差、小李暂时接手的语境相反。", "吃": "搭配：“工作”一般不作“吃”的宾语，二者不搭配。", "撤销": "语义：“撤销”指取消，经理出差时不会取消他的工作。"}, "sentence_index": 0, "correct_answer": "代理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他退休后，小王永久代理了他的工作。", "explanation": "这里应该用〈接替〉。代理指暂时替人做事，不能与“永久”搭配，长期交接应说“接替”。"}, {"text": "这台洗衣机代理了我的家务。", "explanation": "这里应该用〈代替〉。代理的主体须是人，洗衣机是物，不能说代理，应说“代替”。"}, {"text": "他感冒了，请妹妹代理他去上学。", "explanation": "这里应该用〈代替〉。代理指暂代职务或事务，不用于替人去上学这类个人行为，应说“代替”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27548, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "代理", "is_correct": true, "explanation": "代理（dài lǐ）指暂时替别人做事，是正确答案。"}, {"text": "大理", "is_correct": false, "explanation": "dà 与 dài 韵母不同（少了 -i），大理是云南的地名。"}, {"text": "在理", "is_correct": false, "explanation": "zài 与 dài 声母不同（z- 与 d-），在理指有道理。"}, {"text": "带领", "is_correct": false, "explanation": "dài 相同，lǐng 比 lǐ 多韵尾 -ng，带领指引导、率领。"}], "explanations": {"代理": "代理（dài lǐ）指暂时替别人做事，是正确答案。", "大理": "dà 与 dài 韵母不同（少了 -i），大理是云南的地名。", "在理": "zài 与 dài 声母不同（z- 与 d-），在理指有道理。", "带领": "dài 相同，lǐng 比 lǐ 多韵尾 -ng，带领指引导、率领。"}, "sentence_index": null, "correct_answer": "代理"}, "level_3": {"options": [{"text": "代理", "is_correct": true, "explanation": "正确。“代理”指暂时替别人承担职务，与“他生病了”的语境吻合。"}, {"text": "夺取", "is_correct": false, "explanation": "语义：“夺取”指强行取得，与“请你”的委托语境相反。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与请人代为履职的语境不合。"}, {"text": "查收", "is_correct": false, "explanation": "搭配：“查收”多用于邮件、文件，不与“职务”搭配。"}], "explanations": {"代理": "正确。“代理”指暂时替别人承担职务，与“他生病了”的语境吻合。", "夺取": "语义：“夺取”指强行取得，与“请你”的委托语境相反。", "讨厌": "语义：“讨厌”表示厌恶，与请人代为履职的语境不合。", "查收": "搭配：“查收”多用于邮件、文件，不与“职务”搭配。"}, "sentence_index": 6, "correct_answer": "代理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛中他受伤了，只能由替补队员代理上场。", "explanation": "这里应该用〈代替〉。代理多指暂代职务或事务，不用于替补上场。"}, {"text": "他代理自己去看了病。", "explanation": "这里应该用〈亲自〉。代理指替另一个人做事，不能替自己做事，本人去做应说“亲自”。"}, {"text": "这辆车代理了我每天上班。", "explanation": "这里应该用〈代替〉。代理的主体须是人，车不能代理人做事，应说“代替”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理出差期间，小李代理很好。", "corrected_sentence": "经理出差期间，小李代理得很好。", "error_description": "补语标记漏掉。动词后带程度补语时要用“得”，应说“代理得很好”，不说“代理很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总经理休假期间，由副总经理代理得三个月。", "corrected_sentence": "总经理休假期间，由副总经理代理三个月。", "error_description": "时量补语前多加了“得”。时量补语直接跟在动词之后，不用“得”，应说“代理三个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bf0f44c-6a14-4dae-aac9-a85947f44c71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
