INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "小动物脚上尖尖的、能抓东西的硬壳。", "primary_collocate": null, "pronunciation": "zhuǎ", "ipa": "tʂwa˨˩˦", "syllable_count": 1, "sentences": [{"text": "小猫的爪很尖，别让它抓到你。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗用爪推开了门。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫的爪被卡在门缝里了。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟站在树枝上，爪抓得很紧。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的爪上有泥，地板都脏了。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小松鼠用爪抱着花生，吃得很香。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫伸出爪，想抓树叶。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡的爪细细的，在地上找虫子。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫睡着了，爪也缩起来了。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小熊用爪抓蜂蜜，脸上都是蜜。", "target_word": "爪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "爪子", "label": "复合"}], "register": "中性", "sense_fingerprint": "小动物脚上尖尖的、能抓东西的硬壳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd050e39d-2ea0-4db5-ae84-c11939194167') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27550, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爪", "is_correct": true, "explanation": "爪（zhuǎ，第三声）指小动物脚上尖尖的、能抓东西的硬壳，即本词。"}, {"text": "抓", "is_correct": false, "explanation": "抓（zhuā，第一声）与 zhuǎ 声调不同，意思是用手或爪握住。"}, {"text": "转", "is_correct": false, "explanation": "转（zhuǎn）与 zhuǎ 韵母不同，意思是转动。"}, {"text": "耍", "is_correct": false, "explanation": "耍（shuǎ）与 zhuǎ 声母不同（sh 与 zh），意思是玩耍。"}, {"text": "眨", "is_correct": false, "explanation": "眨（zhǎ）比 zhuǎ 少了介音 u，声调相同，意思是眨眼。"}], "explanations": {"爪": "爪（zhuǎ，第三声）指小动物脚上尖尖的、能抓东西的硬壳，即本词。", "抓": "抓（zhuā，第一声）与 zhuǎ 声调不同，意思是用手或爪握住。", "转": "转（zhuǎn）与 zhuǎ 韵母不同，意思是转动。", "耍": "耍（shuǎ）与 zhuǎ 声母不同（sh 与 zh），意思是玩耍。", "眨": "眨（zhǎ）比 zhuǎ 少了介音 u，声调相同，意思是眨眼。"}, "sentence_index": null, "correct_answer": "爪"}, "level_3": {"options": [{"text": "爪", "is_correct": true, "explanation": "正确：空格应填“爪”，与后句“别让它抓到你”呼应。"}, {"text": "牙", "is_correct": false, "explanation": "搭配：“抓到你”要用爪，牙齿是咬，不能说牙“抓到”你。"}, {"text": "毛", "is_correct": false, "explanation": "语义：毛发不会“很尖”，也不能抓人。"}, {"text": "嘴", "is_correct": false, "explanation": "搭配：嘴用来咬或吃，不能说嘴“抓到你”。"}], "explanations": {"爪": "正确：空格应填“爪”，与后句“别让它抓到你”呼应。", "牙": "搭配：“抓到你”要用爪，牙齿是咬，不能说牙“抓到”你。", "毛": "语义：毛发不会“很尖”，也不能抓人。", "嘴": "搭配：嘴用来咬或吃，不能说嘴“抓到你”。"}, "sentence_index": 0, "correct_answer": "爪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用爪擦干了眼泪。", "explanation": "这里应该用〈手〉。“爪”指动物脚上的硬爪，人用东西要说用手，不能用爪。"}, {"text": "牛在草地上奔跑，爪踏起一阵尘土。", "explanation": "这里应该用〈蹄〉。牛的脚端是蹄，“爪”指有爪的动物，不用于牛。"}, {"text": "小狗用爪喝水，喝了一大口。", "explanation": "这里应该用〈嘴〉。狗喝水要用舌头和嘴，“爪”是脚上的硬爪，不能用来喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27550, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爪", "is_correct": true, "explanation": "爪（zhuǎ，第三声）指小动物脚上尖尖的、能抓东西的硬壳，即本词。"}, {"text": "煮", "is_correct": false, "explanation": "煮（zhǔ，第三声）意思是用水加热做熟；与 zhuǎ 声母、声调相同，仅韵母少一个 a，听感可混。"}, {"text": "找", "is_correct": false, "explanation": "找（zhǎo，第三声）意思是寻找；与 zhuǎ 声母、声调相同，韵母 ao 与 ua 有别。"}, {"text": "寡", "is_correct": false, "explanation": "寡（guǎ，第三声）意思是少；与 zhuǎ 韵母、声调相同，仅声母 g 与 zh 有别。"}], "explanations": {"爪": "爪（zhuǎ，第三声）指小动物脚上尖尖的、能抓东西的硬壳，即本词。", "煮": "煮（zhǔ，第三声）意思是用水加热做熟；与 zhuǎ 声母、声调相同，仅韵母少一个 a，听感可混。", "找": "找（zhǎo，第三声）意思是寻找；与 zhuǎ 声母、声调相同，韵母 ao 与 ua 有别。", "寡": "寡（guǎ，第三声）意思是少；与 zhuǎ 韵母、声调相同，仅声母 g 与 zh 有别。"}, "sentence_index": null, "correct_answer": "爪"}, "level_3": {"options": [{"text": "爪", "is_correct": true, "explanation": "正确：原句为“小猫伸出爪，想抓树叶”，空格应填“爪”。"}, {"text": "尾", "is_correct": false, "explanation": "语义：尾巴不能用来抓树叶，此处意思不通。"}, {"text": "舌", "is_correct": false, "explanation": "搭配：舌不能抓东西，“伸出舌”后接“想抓树叶”不搭配。"}, {"text": "耳", "is_correct": false, "explanation": "语义：耳朵不能伸出去抓东西，此处意思不通。"}], "explanations": {"爪": "正确：原句为“小猫伸出爪，想抓树叶”，空格应填“爪”。", "尾": "语义：尾巴不能用来抓树叶，此处意思不通。", "舌": "搭配：舌不能抓东西，“伸出舌”后接“想抓树叶”不搭配。", "耳": "语义：耳朵不能伸出去抓东西，此处意思不通。"}, "sentence_index": 6, "correct_answer": "爪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "柳树的枝条上挂满了绿色的爪，随风摆动。", "explanation": "这里应该用〈树叶〉。“爪”指动物脚上的硬爪，柳树枝上的叶子要说树叶，不能说爪。"}, {"text": "这头公牛的爪又粗又长，很吓人。", "explanation": "这里应该用〈角〉。“爪”指动物脚上的硬爪，公牛头上长的是角，不能说爪。"}, {"text": "菊花的中心长着一只黄色的爪，很漂亮。", "explanation": "这里应该用〈花蕊〉。“爪”指动物脚上的硬爪，花的中心要说花蕊，不能说爪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗抬起一根爪，看了看泥。", "corrected_sentence": "小狗抬起一只爪，看了看泥。", "error_description": "量词错误：动物的爪按只数，应说“一只爪”；“根”只用于细长的东西，不能用于爪。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸟的爪抓了紧树枝。", "corrected_sentence": "小鸟的爪抓紧了树枝。", "error_description": "补语位置错误：“抓紧”是动补结构，“紧”要紧跟“抓”，应说“抓紧了”，不能说“抓了紧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43a2108-07da-481c-8821-c30e1a8054c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
