INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "试试看东西好不好。", "primary_collocate": null, "pronunciation": "cè shì", "ipa": "tsʰɤ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "买手机以前，我想先测试一下它的声音好不好。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈测试了一下新锅，煮饭很快。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿起新耳机，测试音质怎么样。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在店里测试了几支笔，看哪支好写。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，小王先测试话筒有没有声音。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子测试玩具车能跑多快。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买鞋以前，先穿上测试一下舒服不舒服。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸测试这把新椅子结不结实。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手机测试家里的网速。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想测试一下这把伞会不会漏水。", "target_word": "测试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "测试了", "label": "完成体"}, {"form": "测试过", "label": "经历体"}, {"form": "测试测试", "label": "重叠"}, {"form": "測試", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常生活中随手试一试东西好不好用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e23eec3b-6256-4fda-81a7-c349d8b21264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "测试", "is_correct": true, "explanation": "“测试一下”表示试一试东西好不好，与“买手机以前，我想先……一下它的声音”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是物体或身体，不能洗声音，“洗一下它的声音好不好”不成立。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”一般用于食物或物体，不能用于声音。"}, {"text": "寄", "is_correct": false, "explanation": "语义：“寄”指邮寄，与检查声音好不好的意思无关。"}], "explanations": {"测试": "“测试一下”表示试一试东西好不好，与“买手机以前，我想先……一下它的声音”的语境相符。", "洗": "搭配：“洗”的对象是物体或身体，不能洗声音，“洗一下它的声音好不好”不成立。", "咬": "搭配：“咬”一般用于食物或物体，不能用于声音。", "寄": "语义：“寄”指邮寄，与检查声音好不好的意思无关。"}, "sentence_index": 0, "correct_answer": "测试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "裁缝测试了布料的长度。", "explanation": "这里应该用〈测量〉。测量指用工具确定长短、面积等数值，布料长度要用测量；测试指试试看东西好不好，不用于取得数值。"}, {"text": "我测试了一下房租。", "explanation": "这里应该用〈打听〉。打听指向别人询问消息，房租的情况要用打听；测试用于检验物品或能力。"}, {"text": "他测试了账单的总额。", "explanation": "这里应该用〈计算〉。计算指用算式求出数量，账单总额要用计算；测试指试试看东西好不好，不用于求数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "测试", "is_correct": true, "explanation": "“测试一下”表示试试舒服不舒服，与“买鞋以前，先穿上……”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能用于穿鞋后的舒适检查。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，与检查鞋子是否舒服无关。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”指撞击或击打，不能用于检查舒适程度。"}], "explanations": {"测试": "“测试一下”表示试试舒服不舒服，与“买鞋以前，先穿上……”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能用于穿鞋后的舒适检查。", "唱": "语义：“唱”是发出歌声，与检查鞋子是否舒服无关。", "打": "搭配：“打”指撞击或击打，不能用于检查舒适程度。"}, "sentence_index": 6, "correct_answer": "测试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "专家测试明天会下雨。", "explanation": "这里应该用〈预测〉。预测指根据现有情况推断未来，天气变化要用预测；测试指检验事物的性能或能力。"}, {"text": "我慢慢测试春天的温暖。", "explanation": "这里应该用〈感受〉。感受指身心的体会，温暖要用感受；测试不用于体会感觉。"}, {"text": "科学家正在测试宇宙的奥秘。", "explanation": "这里应该用〈探索〉。探索指深入寻求未知的规律，宇宙的奥秘要用探索；测试用于检验已有事物的性能。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们测试过过这支笔，写起来很顺手。", "corrected_sentence": "我们测试过这支笔，写起来很顺手。", "error_description": "“过”重复：经历体“过”只用一次，应说“测试过这支笔”，不能写成“测试过过这支笔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在测试了这把新椅子。", "corrected_sentence": "他正在测试这把新椅子。", "error_description": "“正在”表示动作正在进行，不能与完成体“了”同用。应说“正在测试这把新椅子”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd166ec2-b0e0-497c-be3e-417587a00208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失当", "is_correct": true, "explanation": "失当：安排或处理不恰当，与“得当”是反义关系。"}, {"text": "结实", "is_correct": false, "explanation": "结实：坚固、有力，与“得当”没有反义关系。"}, {"text": "迟钝", "is_correct": false, "explanation": "迟钝：反应慢，与“得当”没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭：坡度大，与“得当”没有反义关系。"}], "correct_answer": "失当", "explanations": {"失当": "失当：安排或处理不恰当，与“得当”是反义关系。", "结实": "结实：坚固、有力，与“得当”没有反义关系。", "迟钝": "迟钝：反应慢，与“得当”没有反义关系。", "陡峭": "陡峭：坡度大，与“得当”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失当", "is_correct": true, "explanation": "失当：言行不恰当，与“得当”是反义关系。"}, {"text": "清脆", "is_correct": false, "explanation": "清脆：声音清亮、利落，与“得当”没有反义关系。"}, {"text": "浓厚", "is_correct": false, "explanation": "浓厚：程度深、分量重，与“得当”没有反义关系。"}, {"text": "干燥", "is_correct": false, "explanation": "干燥：缺少水分，与“得当”没有反义关系。"}], "correct_answer": "失当", "explanations": {"失当": "失当：言行不恰当，与“得当”是反义关系。", "清脆": "清脆：声音清亮、利落，与“得当”没有反义关系。", "浓厚": "浓厚：程度深、分量重，与“得当”没有反义关系。", "干燥": "干燥：缺少水分，与“得当”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情做得刚刚好，让人觉得很合适。", "primary_collocate": null, "pronunciation": "dé dàng", "ipa": "tɤ˧˥ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的话说得不多，但很得当。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着得当，去面试正合适。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的火候掌握得当。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他安排时间很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友生气时，你这样说很得当。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你选的礼物很得当，她很喜欢。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事得当，大家都喜欢和他合作。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的建议很得当。", "target_word": "得当", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她说话得当，不多也不少。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开玩笑要得当，别让人难过。", "target_word": "得当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "处理得当", "label": "复合"}, {"form": "安排得当", "label": "复合"}], "register": "书面", "sense_fingerprint": "得当：做得恰到好处，让人觉得合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7745670-384d-4266-b7e1-8f53799026db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "得当", "is_correct": true, "explanation": "得当：说话的分寸合适，与“说得不多”相呼应。"}, {"text": "啰嗦", "is_correct": false, "explanation": "语义：“啰嗦”指话多、重复，与“他的话说得不多”矛盾。"}, {"text": "冗长", "is_correct": false, "explanation": "语义：「冗长」指话多、拖沓，与「说得不多」矛盾。"}, {"text": "唠叨", "is_correct": false, "explanation": "语义：“唠叨”指话多、絮叨，与“说得不多”矛盾。"}], "explanations": {"得当": "得当：说话的分寸合适，与“说得不多”相呼应。", "啰嗦": "语义：“啰嗦”指话多、重复，与“他的话说得不多”矛盾。", "冗长": "语义：「冗长」指话多、拖沓，与「说得不多」矛盾。", "唠叨": "语义：“唠叨”指话多、絮叨，与“说得不多”矛盾。"}, "sentence_index": 0, "correct_answer": "得当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很得当。", "explanation": "这里应该用〈好〉。「得当」形容做事、说话的分寸，脾气的好坏要用「好」。"}, {"text": "这套房子的大小很得当。", "explanation": "这里应该用〈适中〉。得当形容做事、说话的分寸，房屋大小等程度要用适中。"}, {"text": "这间教室的光线很得当。", "explanation": "这里应该用〈适宜〉。得当不用于光线、环境条件，这类要用适宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得当", "is_correct": true, "explanation": "得当：做事分寸合适，所以大家都愿意与他合作。"}, {"text": "鲁莽", "is_correct": false, "explanation": "语义：“鲁莽”指做事冒失、不顾后果，与“大家都喜欢和他合作”不协调。"}, {"text": "粗心", "is_correct": false, "explanation": "语义：“粗心”指做事不仔细，与“大家都喜欢和他合作”的语境矛盾。"}, {"text": "凶狠", "is_correct": false, "explanation": "搭配：“凶狠”形容神情或行为，不用来修饰“做事”的分寸。"}], "explanations": {"得当": "得当：做事分寸合适，所以大家都愿意与他合作。", "鲁莽": "语义：“鲁莽”指做事冒失、不顾后果，与“大家都喜欢和他合作”不协调。", "粗心": "语义：“粗心”指做事不仔细，与“大家都喜欢和他合作”的语境矛盾。", "凶狠": "搭配：“凶狠”形容神情或行为，不用来修饰“做事”的分寸。"}, "sentence_index": 6, "correct_answer": "得当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的数学水平很得当。", "explanation": "这里应该用〈高〉。得当形容做法、说话的分寸合适，水平的高低要用高。"}, {"text": "这次比赛的成绩很得当。", "explanation": "这里应该用〈好〉。得当指做法合适，成绩的好坏要用好。"}, {"text": "他的兴趣很得当。", "explanation": "这里应该用〈广泛〉。得当形容做事、说话的做法合适，兴趣的范围要用广泛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她做事得当得，同事都信任她。", "corrected_sentence": "她做事得当，同事都信任她。", "error_description": "多字错误：「得当」后多出一个「得」，「得当得」不成词，应删去多余的「得」，说「做事得当」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很说话得当，大家都很喜欢他。", "corrected_sentence": "他说话得当，大家都很喜欢他。", "error_description": "错误位置：副词“很”放在动词“说话”前。“很”不能直接修饰动词，应删去，说“他说话得当”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
