INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27574, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "名字是。", "primary_collocate": null, "pronunciation": "míng wéi", "ipa": "miŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这只小猫名为“小白”。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的妹妹名为“小雨”，今年六岁。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河名为“长江”。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山名为“青山”，风景很美。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他养的狗名为“大黄”。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的公司名为“华信”，在北京。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书名为《月光》，是他写的。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的小店名为“福来”，开了很多年。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个社区的花园名为“和风”，每天都很热闹。", "target_word": "名为", "complexity_tier": "T3", "furigana": "zhège shèqū de huāyuán míngwéi “héfēng”, měitiān dōu hěn rènao", "sentence_source": "generated"}, {"text": "这个小岛名为“月牙岛”，非常安静。", "target_word": "名为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "作谓语，说明某人或某物的名字是什么，常见于「X名为Y」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ee36597-8734-49e0-a69e-b3539cfe9228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名为", "is_correct": true, "explanation": "名为作谓语，说明这只小猫的名字是“小白”。"}, {"text": "姓", "is_correct": false, "explanation": "语义：姓用于人的姓氏，不能说猫有姓氏。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：报名的对象是比赛或活动，不能说“报名名字”。"}, {"text": "设计", "is_correct": false, "explanation": "语义：设计是人有意构思的行为，与猫的名字无关。"}], "explanations": {"名为": "名为作谓语，说明这只小猫的名字是“小白”。", "姓": "语义：姓用于人的姓氏，不能说猫有姓氏。", "报名": "搭配：报名的对象是比赛或活动，不能说“报名名字”。", "设计": "语义：设计是人有意构思的行为，与猫的名字无关。"}, "sentence_index": 0, "correct_answer": "名为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们给新来的小狗名为“旺财”。", "explanation": "这里应该用〈取名为〉。给事物起名要说“取名为”，名为不能接在“给……”之后。"}, {"text": "公司每月都名为一次员工大会。", "explanation": "这里应该用〈召开〉。名为只说明名称是什么，不表示举行活动，召开会议要说召开。"}, {"text": "妈妈在窗口大声名为弟弟吃饭。", "explanation": "这里应该用〈叫〉（呼唤）。名为只说明名字，不表示大声招呼某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名为", "is_correct": true, "explanation": "名为作谓语，说明这本书的名字是《月光》。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：撕碎表示破坏，与书的命名无关。"}, {"text": "迷恋", "is_correct": false, "explanation": "搭配：迷恋需要有感情的人作主语，书不能迷恋。"}, {"text": "咬", "is_correct": false, "explanation": "配价：咬需要有生命的主语，“这本书”不能咬东西。"}], "explanations": {"名为": "名为作谓语，说明这本书的名字是《月光》。", "撕碎": "语义：撕碎表示破坏，与书的命名无关。", "迷恋": "搭配：迷恋需要有感情的人作主语，书不能迷恋。", "咬": "配价：咬需要有生命的主语，“这本书”不能咬东西。"}, "sentence_index": 6, "correct_answer": "名为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "政府给这座湖名为“月亮湖”。", "explanation": "这里应该用〈命名为〉。给事物起名要说“命名为”，名为不能接在“给……”之后。"}, {"text": "人们名为他“老林”。", "explanation": "这里应该用〈称为〉。称呼某人为某名要说“称他为”，名为不能带人作对象。"}, {"text": "他的名字名为“小明”，今年八岁。", "explanation": "这里应该用〈是〉。名为已表示“名字是”，前面再加“名字”就重复了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座小镇名为了“青石镇”，很安静。", "corrected_sentence": "这座小镇名为“青石镇”，很安静。", "error_description": "错误：“名为”后面不加“了”。“名为”作谓语说明名字，不表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个湖名为是“清波湖”，四周都是树林。", "corrected_sentence": "这个湖名为“清波湖”，四周都是树林。", "error_description": "错误：“名为”后面不加“是”。“名为”本身已表示“名字是”，再加“是”就重复了，应说“这个湖名为“清波湖””。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
