INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人或事物的作用、力量在具体场合中充分表现出来，产生实际效果。", "primary_collocate": null, "pronunciation": "fā huī", "ipa": "fa˥ xwei˥", "syllable_count": 2, "sentences": [{"text": "这种药在治疗中发挥了很大作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的制度能发挥更大的效果。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机在生活里发挥着重要作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者在这次活动中发挥了作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法在学习上发挥不了作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水在植物生长中发挥关键作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新堤坝在大雨中发挥了作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小组合作能发挥每个人的力量。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校应该发挥自己的带头作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阅读在孩子成长中发挥着作用。", "target_word": "发挥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发挥了", "label": "完成体"}, {"form": "发挥着", "label": "持续体"}, {"form": "发挥过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "事物或人的作用、力量在具体场合中实际产生效果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7745670-384d-4266-b7e1-8f53799026db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥了很大作用”表示药物产生效果，与“在治疗中”相符。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“很大作用”搭配不当。"}, {"text": "收回", "is_correct": false, "explanation": "语义：“收回”指拿回，与“在治疗中……很大作用”的语义不合。"}, {"text": "扣除", "is_correct": false, "explanation": "语义：“扣除”指减去，“很大作用”不能被扣除，句子说不通。"}], "explanations": {"发挥": "正确答案：“发挥了很大作用”表示药物产生效果，与“在治疗中”相符。", "消耗": "搭配：“消耗”多用于能量、资源，“作用”不能被消耗，与“很大作用”搭配不当。", "收回": "语义：“收回”指拿回，与“在治疗中……很大作用”的语义不合。", "扣除": "语义：“扣除”指减去，“很大作用”不能被扣除，句子说不通。"}, "sentence_index": 0, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头发挥了热量。", "explanation": "这里应该用〈放出〉。“发挥”用于能力、作用，热量要用“放出”。"}, {"text": "他在比赛中发挥了很多汗。", "explanation": "这里应该用〈流〉。“发挥”不用于汗水，出汗要用“流”。"}, {"text": "这座水库发挥了很多水。", "explanation": "这里应该用〈蓄〉。“发挥”不用于水的储存，水库储水要用“蓄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发挥", "is_correct": true, "explanation": "正确答案：“发挥了作用”表示堤坝产生效果，与“在大雨中”相符。"}, {"text": "阻挡", "is_correct": false, "explanation": "搭配：“阻挡”的对象是水流、人群等，不能与“作用”搭配。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”指不再要，“作用”不能被放弃，句子说不通。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”不能以“作用”为宾语，句子结构无法成立。"}], "explanations": {"发挥": "正确答案：“发挥了作用”表示堤坝产生效果，与“在大雨中”相符。", "阻挡": "搭配：“阻挡”的对象是水流、人群等，不能与“作用”搭配。", "放弃": "语义：“放弃”指不再要，“作用”不能被放弃，句子说不通。", "拒绝": "配价：“拒绝”不能以“作用”为宾语，句子结构无法成立。"}, "sentence_index": 6, "correct_answer": "发挥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明在路上发挥着一辆自行车。", "explanation": "这里应该用〈骑〉。“发挥”不能与自行车搭配，骑车要用“骑”。"}, {"text": "妈妈每天发挥一碗汤给我。", "explanation": "这里应该用〈煮〉。“发挥”不用于做饭，煮汤要用“煮”。"}, {"text": "昨天发挥了一场大雨。", "explanation": "这里应该用〈下〉。“发挥”不用于描述天气，下雨要用“下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项新规定能发挥得更大的作用。", "corrected_sentence": "这项新规定能发挥更大的作用。", "error_description": "错误在“得”：“发挥”后直接带宾语“作用”，不能用表示补语的“得”，应去掉“得”，说“能发挥更大的作用”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27580, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小组应该发挥着自己的领导作用。", "corrected_sentence": "这个小组应该发挥自己的领导作用。", "error_description": "错误在“着”：“应该”表示应当，后面不能用表示持续的“着”，应去掉“着”，说“应该发挥自己的领导作用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '431a5649-ad92-4743-bd4e-2d18cf4361f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
