INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指学术界，即从事学问研究的人及其圈子。", "primary_collocate": null, "pronunciation": "xué jiè", "ipa": "ɕɥɛ˧˥ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "学界的人都在读这篇论文。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想进入学界，做一名研究者。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界的朋友们常常在一起讨论。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在学界工作了二十年。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界需要更多年轻人。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她离开公司，回到了学界。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界的老师和学生一起开会。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在学界做出自己的成绩。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界的消息传得很快。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学界不太欢迎只想赚钱的人。", "target_word": "学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "學界", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "指一起做学问的人群及其圈子，如「进入学界」「学界的朋友」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ee36597-8734-49e0-a69e-b3539cfe9228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不是读论文的人群，句意不通。"}, {"text": "学界", "is_correct": true, "explanation": "正确：“学界”指做学问的人群，与“读这篇论文”相符。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是种花草的地方，不能说“花园的人都在读论文”。"}, {"text": "饭碗", "is_correct": false, "explanation": "语域：“饭碗”是口语，指谋生的职业，与书面语的句子不协调。"}], "explanations": {"厨房": "语义：“厨房”是做饭的地方，不是读论文的人群，句意不通。", "学界": "正确：“学界”指做学问的人群，与“读这篇论文”相符。", "花园": "语义：“花园”是种花草的地方，不能说“花园的人都在读论文”。", "饭碗": "语域：“饭碗”是口语，指谋生的职业，与书面语的句子不协调。"}, "sentence_index": 0, "correct_answer": "学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名优秀的学界。", "explanation": "这里应该用〈学者〉。“学界”指学术界这个圈子，不指个人。"}, {"text": "他的学界很深。", "explanation": "这里应该用〈学问〉。“学界”不能用来形容人的学识深浅。"}, {"text": "这学期他的学界很重。", "explanation": "这里应该用〈学业〉。“学界”指学术界，不指学习的任务，不能说“学界很重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄河", "is_correct": false, "explanation": "语义：“黄河”是河流，不是人群，不能有老师和学生在这里开会。"}, {"text": "学界", "is_correct": true, "explanation": "正确：“学界的老师和学生”指学术界中的人，符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能与“老师和学生”组成这样的句子。"}, {"text": "马路", "is_correct": false, "explanation": "搭配：“开会”的主体应是人或机构，“马路”不能与“开会”搭配。"}], "explanations": {"黄河": "语义：“黄河”是河流，不是人群，不能有老师和学生在这里开会。", "学界": "正确：“学界的老师和学生”指学术界中的人，符合句意。", "冰箱": "语义：“冰箱”是家用电器，不能与“老师和学生”组成这样的句子。", "马路": "搭配：“开会”的主体应是人或机构，“马路”不能与“开会”搭配。"}, "sentence_index": 6, "correct_answer": "学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都在学界门口卖早餐。", "explanation": "这里应该用〈学校〉。“学界”指学术界，不指学校，不能说“学界门口”。"}, {"text": "这个学界一共要上三个月的课。", "explanation": "这里应该用〈学期〉。“学界”指学术界，不指一段学习的时间，不能说“学界要上三个月的课”。"}, {"text": "数学是他最喜欢的学界。", "explanation": "这里应该用〈学科〉。“学界”是群体概念，不指具体的学科，不能说“最喜欢的学界”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直希望能学界有所作为。", "corrected_sentence": "她一直希望能在学界有所作为。", "error_description": "“学界”前要加介词“在”表示范围。应说“在学界有所作为”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学界的们同行经常在一起交流。", "corrected_sentence": "学界的同行经常在一起交流。", "error_description": "错误：“们”不能加在结构助词“的”之后。“学界的同行”中不需要“们”，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相关", "is_correct": true, "explanation": "与“无关”相对，指与事情有关联的，是反义词。"}, {"text": "陌生", "is_correct": false, "explanation": "不构成反义，“陌生”指不熟悉，与“无关”的“不相干”不对应。"}, {"text": "柔软", "is_correct": false, "explanation": "不构成反义，“柔软”形容质地，与“无关”没有对应关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "不构成反义，“漂亮”形容外貌或事物美观，与“无关”没有对应关系。"}], "correct_answer": "相关", "explanations": {"相关": "与“无关”相对，指与事情有关联的，是反义词。", "陌生": "不构成反义，“陌生”指不熟悉，与“无关”的“不相干”不对应。", "柔软": "不构成反义，“柔软”形容质地，与“无关”没有对应关系。", "漂亮": "不构成反义，“漂亮”形容外貌或事物美观，与“无关”没有对应关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "相关", "is_correct": true, "explanation": "与“无关”相对，指与事情有关联的，是反义词。"}, {"text": "安静", "is_correct": false, "explanation": "不构成反义，“安静”形容环境或状态，与“无关”没有对应关系。"}, {"text": "干净", "is_correct": false, "explanation": "不构成反义，“干净”形容清洁程度，与“无关”没有对应关系。"}, {"text": "整齐", "is_correct": false, "explanation": "不构成反义，“整齐”形容排列有序，与“无关”没有对应关系。"}], "correct_answer": "相关", "explanations": {"相关": "与“无关”相对，指与事情有关联的，是反义词。", "安静": "不构成反义，“安静”形容环境或状态，与“无关”没有对应关系。", "干净": "不构成反义，“干净”形容清洁程度，与“无关”没有对应关系。", "整齐": "不构成反义，“整齐”形容排列有序，与“无关”没有对应关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有关系，不相关。", "primary_collocate": null, "pronunciation": "wú guān", "ipa": "u˧˥ kuan˥", "syllable_count": 2, "sentences": [{"text": "请不要问无关的问题。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两件事完全无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了很多无关的话。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无关的人请先离开这里。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词看着像，意思却完全无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们别写无关的内容。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的内容和题目无关。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把无关的东西都扔了。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个问题互相无关，可以分开做。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片和今天的会议无关，不用看。", "target_word": "无关", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "無關", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作定语或谓语，说明事物之间不相关，如「无关的问题」「完全无关」", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ee36597-8734-49e0-a69e-b3539cfe9228') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的身材、体形，不能用来修饰“问题”。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能透光，“问题”不能透明，句子不通。"}, {"text": "无关", "is_correct": true, "explanation": "正确：“无关的问题”指与所谈事情没有关系的问题，符合“请不要问”的语境。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，不能用来修饰“问题”。"}], "explanations": {"高大": "体貌：“高大”形容人或物的身材、体形，不能用来修饰“问题”。", "透明": "语义：“透明”形容物体能透光，“问题”不能透明，句子不通。", "无关": "正确：“无关的问题”指与所谈事情没有关系的问题，符合“请不要问”的语境。", "圆": "语义：“圆”指形状，不能用来修饰“问题”。"}, "sentence_index": 0, "correct_answer": "无关"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我是这次事故的当事人，却是无关的人。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“当事人”自相矛盾，应说“有关的人”。"}, {"text": "他的成功与努力无关，全靠每天刻苦练习才成功。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“全靠每天刻苦练习才成功”矛盾，应说“有关”。"}, {"text": "这份报告的数据与结论无关，所有结论都是从这些数据中得出的。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“结论都是从这些数据中得出的”矛盾，应说“有关”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”形容人或动物的身材，不能用来形容内容和题目。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容颜色或光线很暗，不能用来形容内容和题目。"}, {"text": "无关", "is_correct": true, "explanation": "正确：“与……无关”表示内容和题目之间没有联系，符合句意。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”形容颜色，不能用来形容内容和题目。"}], "explanations": {"瘦小": "体貌：“瘦小”形容人或动物的身材，不能用来形容内容和题目。", "漆黑": "语义：“漆黑”形容颜色或光线很暗，不能用来形容内容和题目。", "无关": "正确：“与……无关”表示内容和题目之间没有联系，符合句意。", "雪白": "语义：“雪白”形容颜色，不能用来形容内容和题目。"}, "sentence_index": 6, "correct_answer": "无关"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些线索都与案件无关，警方却全靠它们破了案。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“警方却全靠它们破了案”矛盾，应说“有关”。"}, {"text": "这道题的答案与公式无关，我们却全靠公式算出来。", "explanation": "这里应该用〈有关〉。“无关”表示没有牵涉，与“全靠公式算出来”矛盾，应说“有关”。"}, {"text": "他对家人有无关的爱。", "explanation": "这里应该用〈无限〉。“无关”指没有牵涉，不能用来形容爱的程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他总是说些无关地话，大家都很烦。", "corrected_sentence": "他总是说些无关的话，大家都很烦。", "error_description": "错误：修饰名词时结构助词应用“的”，不能用“地”。应说“无关的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告我们的项目无关，可以先放一边。", "corrected_sentence": "这份报告与我们的项目无关，可以先放一边。", "error_description": "“与……无关”中的“与”不能省略。应说“与我们的项目无关”，不能直接说“我们的项目无关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f2e61d22-7b0a-4a61-9918-fecd866bb64a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
