INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "产业界就是做很多生意的公司和工厂在一起的大圈子。", "primary_collocate": null, "pronunciation": "chǎn yè jiè", "ipa": "tʂʰan˨˩ jɛ˥˩ tɕjɛ˥˩", "syllable_count": 3, "sentences": [{"text": "产业界的公司都想招聘新员工。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲一直在产业界做事。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界有很多工厂和公司。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息很快传遍了产业界。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界的朋友请我去参观工厂。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界今年的生意不太好。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想进产业界，不想当老师。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界和政府常常开会。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产业界的人都认识这位老板。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在产业界认识了不少朋友。", "target_word": "产业界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "公司和工厂聚在一起的生意圈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学界", "is_correct": false, "explanation": "语义：学界指学术领域，没有“公司”，与句意不符。"}, {"text": "产业界", "is_correct": true, "explanation": "正确。产业界指做生意的公司和工厂组成的圈子，修饰“公司”符合语境。"}, {"text": "政界", "is_correct": false, "explanation": "语义：政界指政治领域，不是做生意的公司群体。"}, {"text": "军队", "is_correct": false, "explanation": "语义：军队是武装力量，不是做生意的公司群体，与“公司都想招聘新员工”的句意不符。"}], "explanations": {"学界": "语义：学界指学术领域，没有“公司”，与句意不符。", "产业界": "正确。产业界指做生意的公司和工厂组成的圈子，修饰“公司”符合语境。", "政界": "语义：政界指政治领域，不是做生意的公司群体。", "军队": "语义：军队是武装力量，不是做生意的公司群体，与“公司都想招聘新员工”的句意不符。"}, "sentence_index": 0, "correct_answer": "产业界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把产业界装进了冰箱。", "explanation": "这里应该用〈剩饭〉。产业界是做生意的公司和工厂组成的抽象圈子，不能装进冰箱。"}, {"text": "他渴了，喝了一口产业界。", "explanation": "这里应该用〈水〉。产业界指做生意的公司和工厂组成的圈子，是抽象群体，不是可以喝的东西。"}, {"text": "产业界在草地上跑来跑去。", "explanation": "这里应该用〈小狗〉。产业界是抽象群体，不能像动物一样在草地上跑来跑去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能被“进入”，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能让人“进”，与句意不符。"}, {"text": "产业界", "is_correct": true, "explanation": "正确。“进”后接的对象是企业圈子，符合“想进……”的语境。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“进”后要接场所或群体，“沙发”不能与“进”搭配。"}], "explanations": {"石头": "语义：石头不能被“进入”，与句意不符。", "空气": "语义：空气不能让人“进”，与句意不符。", "产业界": "正确。“进”后接的对象是企业圈子，符合“想进……”的语境。", "沙发": "搭配：“进”后要接场所或群体，“沙发”不能与“进”搭配。"}, "sentence_index": 6, "correct_answer": "产业界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个产业界很甜。", "explanation": "这里应该用〈西瓜〉。产业界是做生意的公司和工厂组成的圈子，是抽象群体，不能用味道来形容。"}, {"text": "他每天用产业界写字。", "explanation": "这里应该用〈笔〉。产业界指做生意的公司和工厂组成的圈子，不是工具，不能用来写字。"}, {"text": "他把产业界拿去卖了。", "explanation": "这里应该用〈旧货〉。产业界是抽象的群体，不是可以拿去卖的实体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他产业界有很多朋友。", "corrected_sentence": "他在产业界有很多朋友。", "error_description": "错误在于漏掉介词“在”：表示地点的“产业界”前应有“在”。正确形式为“他在产业界有很多朋友”，不能说“他产业界有很多朋友”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在一只产业界工作了很多年。", "corrected_sentence": "他在产业界工作了很多年。", "error_description": "错误在量词：“只”多用于动物或成对事物中的单个，不能用于产业界这种抽象圈子，应直接说“在产业界”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
