INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27592, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "让一个人变得和别人不一样。", "primary_collocate": null, "pronunciation": "gè tǐ huà", "ipa": "kɤ˥˩ tʰi˨˩˦ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "衣服、爱好和想法都是个体化的方式。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人通过个体化找到真正的自己。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个体化不是学别人，而是做自己。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子长大后，会经历个体化的过程。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的个体化从选择专业开始。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学家说，个体化让人拥有自己的想法。", "target_word": "个体化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有个体化，每个人就会和别人一样。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "个体化需要时间，不能太着急。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他觉得个体化比跟着大家走更重要。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校应该尊重学生的个体化。", "target_word": "个体化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "個體化", "label": "繁体"}], "register": "中性", "sense_fingerprint": "个体化：让一个人变得和别人不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084ae0df-3253-40e5-a861-f0a9a013f1f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "个体化", "is_correct": true, "explanation": "正确答案。“都是个体化的方式”指让自己与别人不同的方式。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能表示让人变得与众不同的方式。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：口语化的俗称，与本句的书面语域不合。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是具体材料，不能作为一种生活方式。"}], "explanations": {"个体化": "正确答案。“都是个体化的方式”指让自己与别人不同的方式。", "颜色": "语义：颜色不能表示让人变得与众不同的方式。", "玩意儿": "语域：口语化的俗称，与本句的书面语域不合。", "木头": "语义：木头是具体材料，不能作为一种生活方式。"}, "sentence_index": 0, "correct_answer": "个体化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个体化跑得很快。", "explanation": "这里应该用〈进展〉。个体化是抽象的过程，不能用“跑”来形容，应说“个体化进展很快”。"}, {"text": "他把个体化打开了。", "explanation": "这里应该用〈进行〉。“打开”不能支配抽象的过程，应说“进行个体化”。"}, {"text": "这个个体化很聪明。", "explanation": "这里应该用〈个体〉。个体化指让人变得与众不同的过程，不指具体的人，说某个人要用个体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "个体化", "is_correct": true, "explanation": "正确答案。“没有个体化，每个人就会和别人一样”，个体化是让人与众不同的过程。"}, {"text": "泥土", "is_correct": false, "explanation": "语义：泥土无法让人与别人不一样，与本句逻辑不符。"}, {"text": "货色", "is_correct": false, "explanation": "语域：口语化的贬义说法，与本句的书面语域不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，与人是否与别人一样毫无关系。"}], "explanations": {"个体化": "正确答案。“没有个体化，每个人就会和别人一样”，个体化是让人与众不同的过程。", "泥土": "语义：泥土无法让人与别人不一样，与本句逻辑不符。", "货色": "语域：口语化的贬义说法，与本句的书面语域不合。", "冰箱": "语义：冰箱是家电，与人是否与别人一样毫无关系。"}, "sentence_index": 6, "correct_answer": "个体化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都个体化一顿饭。", "explanation": "这里应该用〈吃〉。个体化是抽象的过程，不能用于吃饭。"}, {"text": "研究者认为个体化能喝掉一杯水。", "explanation": "语义：个体化是抽象的过程，不能与“喝”搭配。"}, {"text": "他找到了一只个体化。", "explanation": "这里应该用〈种〉。个体化是抽象的过程，不能用“只”计数，应说“一种个体化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只个体化让他与众不同。", "corrected_sentence": "这种个体化让他与众不同。", "error_description": "错误在量词“只”。“个体化”是抽象的过程，不能用“只”（“只”多用于动物或成对事物中的单个），应用“种”，写作“这种个体化”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "没有一条个体化，人们就很难真正做自己。", "corrected_sentence": "没有一种个体化，人们就很难真正做自己。", "error_description": "错误在量词：“个体化”是抽象的过程，不能用“条”计量（“条”用于细长的物体），应用“种”，写作“没有一种个体化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cca7642-df11-4003-a229-fc802ecf1463') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
