INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "变得比以前更厉害。", "primary_collocate": null, "pronunciation": "biàn qiáng", "ipa": "pjɛn⁵¹ tɕʰjɑŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这只狗长大了，变强了不少。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的对手变强了，我们要小心。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟最近天天游泳，变强了，能游一千米。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏里，你可以买东西让自己变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的球队今年变强了，常常赢球。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人变强以后，我们很难打赢。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，我比去年变强了。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想快点变强，当一名好警察。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "变强的路上，会有很多困难。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在努力，我也不能不变强。", "target_word": "变强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "变强了", "label": "体标：了"}, {"form": "变强过", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "和以前相比变得更厉害、更有力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a9ed81-ee57-4f6d-9b76-d0a5321a3745') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：变强（biàn qiáng），指变得比以前更厉害。"}, {"text": "变迁", "is_correct": false, "explanation": "qiān（第一声）与 qiáng（第二声）韵母不同（an 与 ang），声调也不同；变迁指事物的演变，不是变得更厉害。"}, {"text": "变清", "is_correct": false, "explanation": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变清意思是变得清澈。"}, {"text": "变晴", "is_correct": false, "explanation": "qíng（第二声）与 qiáng 声调相同，韵母不同（ing 与 ang）；变晴指天气转晴。"}], "explanations": {"变强": "正确：变强（biàn qiáng），指变得比以前更厉害。", "变迁": "qiān（第一声）与 qiáng（第二声）韵母不同（an 与 ang），声调也不同；变迁指事物的演变，不是变得更厉害。", "变清": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变清意思是变得清澈。", "变晴": "qíng（第二声）与 qiáng 声调相同，韵母不同（ing 与 ang）；变晴指天气转晴。"}, "sentence_index": null, "correct_answer": "变强"}, "level_3": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：“变强”指变得比以前更厉害，与“长大了”的变化方向一致。"}, {"text": "变小", "is_correct": false, "explanation": "语义：“长大”与“变小”意思相反，句子自相矛盾。"}, {"text": "变矮", "is_correct": false, "explanation": "体貌：“矮”描写身高，狗长大后不会变矮，与句意不合。"}, {"text": "变轻", "is_correct": false, "explanation": "语义：“变轻”指重量减少，与“长大了”的变化方向不符。"}], "explanations": {"变强": "正确：“变强”指变得比以前更厉害，与“长大了”的变化方向一致。", "变小": "语义：“长大”与“变小”意思相反，句子自相矛盾。", "变矮": "体貌：“矮”描写身高，狗长大后不会变矮，与句意不合。", "变轻": "语义：“变轻”指重量减少，与“长大了”的变化方向不符。"}, "sentence_index": 0, "correct_answer": "变强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的考试题变强了，同学们都很难过。", "explanation": "这里应该用〈变难〉。变强指人的能力、实力变强，题目的难度要说变难。"}, {"text": "今年的订单变强了，工厂忙得不得了。", "explanation": "这里应该用〈增加〉。变强不用于订单这类数量，订单多了要用增加。"}, {"text": "这个月的油价变强了，大家都很担心。", "explanation": "这里不能用变强。变强只说人或团队的能力、实力变强，油价的涨跌要说涨或跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：变强（biàn qiáng），指变得比以前更厉害。"}, {"text": "变穷", "is_correct": false, "explanation": "qióng 与 qiáng 声调相同，韵母不同（ong 与 ang）；变穷意思是变得贫穷。"}, {"text": "变轻", "is_correct": false, "explanation": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变轻意思是变得轻。"}, {"text": "变亲", "is_correct": false, "explanation": "qīn（第一声）与 qiáng 韵母不同（in 与 ang），声调也不同；变亲意思是变得亲近。"}], "explanations": {"变强": "正确：变强（biàn qiáng），指变得比以前更厉害。", "变穷": "qióng 与 qiáng 声调相同，韵母不同（ong 与 ang）；变穷意思是变得贫穷。", "变轻": "qīng（第一声）与 qiáng 韵母不同（ing 与 ang），声调也不同；变轻意思是变得轻。", "变亲": "qīn（第一声）与 qiáng 韵母不同（in 与 ang），声调也不同；变亲意思是变得亲近。"}, "sentence_index": null, "correct_answer": "变强"}, "level_3": {"options": [{"text": "变强", "is_correct": true, "explanation": "正确：“变强”指比以前更厉害，与“比去年”的比较搭配，符合句意。"}, {"text": "变远", "is_correct": false, "explanation": "语义：“变远”指距离拉开，不能用来说人变得怎样，句子说不通。"}, {"text": "变湿", "is_correct": false, "explanation": "搭配：“湿”多用于物体或天气，不用来形容人的状态。"}, {"text": "变咸", "is_correct": false, "explanation": "语义：“咸”指味道，人不能“变咸”，与句意不合。"}], "explanations": {"变强": "正确：“变强”指比以前更厉害，与“比去年”的比较搭配，符合句意。", "变远": "语义：“变远”指距离拉开，不能用来说人变得怎样，句子说不通。", "变湿": "搭配：“湿”多用于物体或天气，不用来形容人的状态。", "变咸": "语义：“咸”指味道，人不能“变咸”，与句意不合。"}, "sentence_index": 6, "correct_answer": "变强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月班里的迟到次数变强了，老师很生气。", "explanation": "这里应该用〈增多〉。变强指能力、实力变强，迟到次数增加要说增多，不能用变强。"}, {"text": "我们的计划变强了，大家都很满意。", "explanation": "这里应该用〈完善〉。变强描述能力、实力，计划要说完善。"}, {"text": "这家店的顾客数量变强了，老板很开心。", "explanation": "这里应该用〈增多〉。变强不用于顾客数量，数量变多要说增多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只狗最近被变强了不少，跑起来很快。", "corrected_sentence": "这只狗最近变强了不少，跑起来很快。", "error_description": "错误在“被”。“变强”是不及物动词，不能用“被”字句。应去掉“被”，说“这只狗最近变强了不少”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈说，我比去年变强着很多。", "corrected_sentence": "妈妈说，我比去年变强了很多。", "error_description": "错误在“着”。“着”表示状态的持续，“变强”是一次完成的变化，不能接“着”。应说“妈妈说，我比去年变强了很多”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26a72a2d-9dc4-4cea-bae7-9fe2c86ea628') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
