INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27602, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有缝，很完整。", "primary_collocate": null, "pronunciation": "wú fèng", "ipa": "u˧˥ fəŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个塑料盒是无缝的，水不会从缝里漏出来。", "target_word": "无缝", "complexity_tier": "T3", "furigana": "zhè ge sù liào hé shì wú fèng de, shuǐ bú huì cóng fèng lǐ lòu chū lái.", "sentence_source": "generated"}, {"text": "这张桌子是无缝的，非常平。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服无缝，穿起来很舒服。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两块板连在一起，几乎是无缝的。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是无缝的，所以不会漏水。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无缝的墙看起来又平又干净。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地板铺得很好，看上去是无缝的。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买无缝的内衣，因为里面没有线头。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根管子无缝，水不会从旁边流出来。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门和墙之间有缝，不是无缝的。", "target_word": "无缝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "无缝连接", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体上没有缝，完整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d23743e-da8a-456c-b392-e2c429d26a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27602, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无缝", "is_correct": true, "explanation": "“无缝”作表语，说明盒子没有缝，水漏不出来。"}, {"text": "破损", "is_correct": false, "explanation": "语义：“破损”说明盒子有损坏，与“水不会从缝里漏出来”相矛盾。"}, {"text": "漏水", "is_correct": false, "explanation": "语义：“漏水”与“水不会从缝里漏出来”直接矛盾。"}, {"text": "开裂", "is_correct": false, "explanation": "搭配：“开裂”多用于墙面、木材等，不常用来形容塑料盒。"}], "explanations": {"无缝": "“无缝”作表语，说明盒子没有缝，水漏不出来。", "破损": "语义：“破损”说明盒子有损坏，与“水不会从缝里漏出来”相矛盾。", "漏水": "语义：“漏水”与“水不会从缝里漏出来”直接矛盾。", "开裂": "搭配：“开裂”多用于墙面、木材等，不常用来形容塑料盒。"}, "sentence_index": 0, "correct_answer": "无缝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸的颜色很无缝。", "explanation": "这里应该用〈鲜艳〉。无缝描述物体没有缝，不用来形容颜色。"}, {"text": "这碗汤的味道很无缝。", "explanation": "这里应该用〈鲜美〉。无缝形容物体没有缝隙、完整，不用来形容味道。"}, {"text": "这个孩子的身高是无缝的。", "explanation": "这里应该用〈高〉。无缝形容物体没有缝隙、完整，不用来形容身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27602, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无缝", "is_correct": true, "explanation": "“无缝”说明地板没有缝，与“铺得很好”相合。"}, {"text": "歪斜", "is_correct": false, "explanation": "语义：“歪斜”指不平正，与“铺得很好”的语境矛盾。"}, {"text": "坑洼", "is_correct": false, "explanation": "语义：“坑洼”指表面凹凸不平，与“铺得很好”矛盾。"}, {"text": "破旧", "is_correct": false, "explanation": "搭配：“破旧”多用于旧物的状态，不能描述刚铺好的地板的外观。"}], "explanations": {"无缝": "“无缝”说明地板没有缝，与“铺得很好”相合。", "歪斜": "语义：“歪斜”指不平正，与“铺得很好”的语境矛盾。", "坑洼": "语义：“坑洼”指表面凹凸不平，与“铺得很好”矛盾。", "破旧": "搭配：“破旧”多用于旧物的状态，不能描述刚铺好的地板的外观。"}, "sentence_index": 6, "correct_answer": "无缝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的价格是无缝的。", "explanation": "这里应该用〈便宜〉。无缝描述的是没有缝隙或衔接紧密，不用来形容价格的高低。"}, {"text": "这次考试的难度是无缝的。", "explanation": "这里应该用〈简单〉。无缝描述的是物体没有缝隙，不用来形容题目的难易。"}, {"text": "这台电脑的重量是无缝的。", "explanation": "这里应该用〈轻〉。无缝描述物体没有缝，不用来形容重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27602, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板做无缝，很结实。", "corrected_sentence": "这块木板做得无缝，很结实。", "error_description": "错误：“做无缝”缺少补语标记“得”。“无缝”作结果补语，要说“做得无缝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27602, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根水管不无缝，水不会漏出来。", "corrected_sentence": "这根水管无缝，水不会漏出来。", "error_description": "错误：在“无缝”前加了“不”。“无缝”本身就是没有缝的意思，说有缝要用“有缝”或“不是无缝的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
