INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "这个东西可以方便地换到别的电脑上使用。", "primary_collocate": null, "pronunciation": "kě yí zhí xìng", "ipa": "kʰɤ˨˩˦ i˧˥ ʈʂɨ˧˥ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这个小工具的可移植性很好，换台电脑就能用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买软件以前，我会先看看它的可移植性。", "target_word": "可移植性", "complexity_tier": "T3", "furigana": "kě yí zhí xìng", "sentence_source": "generated"}, {"text": "我的游戏可移植性不好，不能换电脑玩。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "可移植性高，说明换电脑时不用重新安装。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，好程序要有可移植性。", "target_word": "可移植性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个办公软件的可移植性让同事们很满意。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为可移植性差，这个软件只能在旧电脑上用。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这个软件，主要是它的可移植性好。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想提高软件的可移植性，方便用户换电脑。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统的可移植性怎么样，试一试就知道了。", "target_word": "可移植性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "科技", "sense_fingerprint": "东西能方便地换到别的电脑上使用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c16dde-b3e4-4ca0-a198-05848c7b5269') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：指东西能方便地换到别的电脑上使用，与“换台电脑就能用”相符。"}, {"text": "防水性", "is_correct": false, "explanation": "语义：句末说“换台电脑就能用”，与防水无关，句意不通。"}, {"text": "续航力", "is_correct": false, "explanation": "语义：续航与换到哪台电脑上使用无关，与句中的因果不符。"}, {"text": "亮度", "is_correct": false, "explanation": "语义：亮度与软件能否换到别的电脑上使用无关，句意不通。"}], "explanations": {"可移植性": "正确：指东西能方便地换到别的电脑上使用，与“换台电脑就能用”相符。", "防水性": "语义：句末说“换台电脑就能用”，与防水无关，句意不通。", "续航力": "语义：续航与换到哪台电脑上使用无关，与句中的因果不符。", "亮度": "语义：亮度与软件能否换到别的电脑上使用无关，句意不通。"}, "sentence_index": 0, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的可移植性很强，居民生活很方便。", "explanation": "这里应该用〈宜居性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说城市是否适合居住。"}, {"text": "这栋楼的可移植性很好，地震时也很安全。", "explanation": "这里应该用〈稳定性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说建筑承受外力的能力。"}, {"text": "他跳舞的可移植性很好，动作很整齐。", "explanation": "这里应该用〈协调性〉。可移植性指东西能方便地换到别的电脑上使用，不用来说人动作配合得是否协调。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可移植性", "is_correct": true, "explanation": "正确：说明软件换到新电脑上用不了，与“只能在旧电脑上用”相符。"}, {"text": "透气性", "is_correct": false, "explanation": "搭配：“透气性”多用于布料和衣物，不用来说明软件能否换机使用。"}, {"text": "耐寒性", "is_correct": false, "explanation": "搭配：“耐寒性”指材料耐低温，不用来说明软件的使用范围。"}, {"text": "耐磨性", "is_correct": false, "explanation": "语义：“耐磨性”指物体经受磨损的能力，与软件能在哪台电脑上运行无关。"}], "explanations": {"可移植性": "正确：说明软件换到新电脑上用不了，与“只能在旧电脑上用”相符。", "透气性": "搭配：“透气性”多用于布料和衣物，不用来说明软件能否换机使用。", "耐寒性": "搭配：“耐寒性”指材料耐低温，不用来说明软件的使用范围。", "耐磨性": "语义：“耐磨性”指物体经受磨损的能力，与软件能在哪台电脑上运行无关。"}, "sentence_index": 6, "correct_answer": "可移植性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的可移植性很高，蛋白质很丰富。", "explanation": "这里应该用〈营养价值〉。可移植性指东西能方便地换到别的电脑上使用，不用来说食物的营养。"}, {"text": "这所学校的可移植性很高，老师都很认真。", "explanation": "这里应该用〈教学质量〉。可移植性指东西能方便地换到别的电脑上使用，不用来说学校的教学水平。"}, {"text": "这位老师对学生的可移植性很好，讲题讲了很多遍。", "explanation": "这里应该用〈耐心〉。可移植性指东西能方便地换到别的电脑上使用，不用来说老师对学生是否有耐心。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这个小工具的可移植性提高，换电脑就方便多了。", "corrected_sentence": "我们把这个小工具的可移植性提高了，换电脑就方便多了。", "error_description": "“把”字句中，“提高”后缺少“了”。应为“把……提高了”，“把”字句要求动词带“了”或补语，缺少则句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个软件的可移植性的很好，换台电脑就能直接用。", "corrected_sentence": "这个软件的可移植性很好，换台电脑就能直接用。", "error_description": "多余的“的”：“可移植性”后直接接“很好”作谓语，不能加“的”。正确说法是“这个软件的可移植性很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f31dd33-5180-44a2-a897-57cd7e9ac8c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
