INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27608, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个可以拼在一起的小块。", "primary_collocate": null, "pronunciation": "mó kuài", "ipa": "mwo˧˥ kʰwai˥˩", "syllable_count": 2, "sentences": [{"text": "孩子把几个模块拼成了一座小房子。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套玩具有二十个彩色模块。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个模块都有小孔，可以插在一起。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些模块可以拼成不同的样子。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有红色的模块和蓝色的模块。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用四个模块搭了一张小桌子。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这个模块放在最上面，不然房子会倒。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小模块掉在地上了，快去捡起来。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给每个学生发了一盒模块。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房子是由许多模块拼成的。", "target_word": "模块", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "彩色模块", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以拼在一起的小块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d23743e-da8a-456c-b392-e2c429d26a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27608, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模块", "is_correct": true, "explanation": "正确。“孩子把几个模块拼成了一座小房子”，模块是可以拼在一起的小块。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是教室里的书写设备，不能拼成房子。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：“眼睛”是人的器官，不能用来拼装成房子。"}, {"text": "雨滴", "is_correct": false, "explanation": "语义：“雨滴”是水珠，不能被拼在一起搭成房子。"}], "explanations": {"模块": "正确。“孩子把几个模块拼成了一座小房子”，模块是可以拼在一起的小块。", "黑板": "语义：“黑板”是教室里的书写设备，不能拼成房子。", "眼睛": "体貌：“眼睛”是人的器官，不能用来拼装成房子。", "雨滴": "语义：“雨滴”是水珠，不能被拼在一起搭成房子。"}, "sentence_index": 0, "correct_answer": "模块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把模块炒了一盘。", "explanation": "这里应该用〈鸡蛋〉。模块是玩具的小块，不能用来炒菜；炒一盘要用“鸡蛋”之类的食材。"}, {"text": "孩子把几根模块拼成了一座小桥。", "explanation": "这里应该用〈个〉。〈根〉用于细长的物体，模块是可以拼在一起的小块，量词要用“个”。"}, {"text": "这位模块很漂亮，大家都来拍照。", "explanation": "这里应该用〈模特〉。模特指做展示的人，模块是可以拼在一起的小块，不能指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27608, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模块", "is_correct": true, "explanation": "正确。“请把这个模块放在最上面，不然房子会倒”，模块是可以堆放、搭建的小块。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”是需要治疗的人，不能被放在房子的最上面当积木。"}, {"text": "包子", "is_correct": false, "explanation": "语义：“包子”是食物，不能用来搭房子。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：“脸色”描述人的面部气色，不是可以搬动、放置的东西。"}], "explanations": {"模块": "正确。“请把这个模块放在最上面，不然房子会倒”，模块是可以堆放、搭建的小块。", "病人": "语义：“病人”是需要治疗的人，不能被放在房子的最上面当积木。", "包子": "语义：“包子”是食物，不能用来搭房子。", "脸色": "体貌：“脸色”描述人的面部气色，不是可以搬动、放置的东西。"}, "sentence_index": 6, "correct_answer": "模块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天用模块来刷牙。", "explanation": "这里应该用〈牙刷〉。模块是拼插的小块，不能用来刷牙；刷牙要用“牙刷”。"}, {"text": "他买了一张模块，放在桌上。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，模块是小块，量词要用“个”。"}, {"text": "他买了一把模块，放在桌上。", "explanation": "这里应该用〈个〉。〈把〉用于带柄或可握的物体，模块是小块，量词要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27608, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子用三只模块拼了一条小船。", "corrected_sentence": "孩子用三个模块拼了一条小船。", "error_description": "量词错误：“模块”应与量词“个”搭配，不能用“只”（“只”多用于动物或成对物件中的一个）。正确说法是：三个模块。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27608, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子已经把模块拼了好。", "corrected_sentence": "孩子已经把模块拼好了。", "error_description": "补语位置错误：“拼好”是动词加结果补语，“好”要紧跟动词，应说“拼好了”，不能说“拼了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把带子、绳子扎紧，与“解开”的意思相反。"}, {"text": "量", "is_correct": false, "explanation": "“量”指测量长短大小，与“解”不构成反义关系。"}, {"text": "找", "is_correct": false, "explanation": "“找”指寻求、寻找，与“解”不构成反义关系。"}, {"text": "捡", "is_correct": false, "explanation": "“捡”指拾取，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把带子、绳子扎紧，与“解开”的意思相反。", "量": "“量”指测量长短大小，与“解”不构成反义关系。", "找": "“找”指寻求、寻找，与“解”不构成反义关系。", "捡": "“捡”指拾取，与“解”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "系", "is_correct": true, "explanation": "“系”与“解”相对，指把红绳、带子扎紧，与“解一下红绳”的动作相反。"}, {"text": "搬", "is_correct": false, "explanation": "“搬”指移动物体的位置，与“解”不构成反义关系。"}, {"text": "敲", "is_correct": false, "explanation": "“敲”指用物体撞击，与“解”不构成反义关系。"}, {"text": "扛", "is_correct": false, "explanation": "“扛”指把东西架在肩上，与“解”不构成反义关系。"}], "correct_answer": "系", "explanations": {"系": "“系”与“解”相对，指把红绳、带子扎紧，与“解一下红绳”的动作相反。", "搬": "“搬”指移动物体的位置，与“解”不构成反义关系。", "敲": "“敲”指用物体撞击，与“解”不构成反义关系。", "扛": "“扛”指把东西架在肩上，与“解”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西打开或分开。", "primary_collocate": null, "pronunciation": "jiě", "ipa": "tɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "他回到家，先解包裹上的带子。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把头发上的绳子解了，头发散下来。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔夫坐在船边解网。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷慢慢解袋子口的线。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天热了，他解围巾，放进包里。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你解一下腰带，会舒服一点。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子急着解礼物上的丝带。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他解书包上的拉绳，拿出本子。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人解口袋里的小布包，拿出钱。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你解一下这个盒子上的红绳。", "target_word": "解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解了", "label": "体标：了"}, {"form": "解过", "label": "体标：过"}, {"form": "解开", "label": "复合"}], "register": "中性", "sense_fingerprint": "把捆着或合着的东西打开、分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d23743e-da8a-456c-b392-e2c429d26a6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。"}, {"text": "借", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。"}, {"text": "接", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。"}, {"text": "介", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。", "借": "jiè（第四声）与 jiě（第三声）声调不同，意思是借入或借出。", "结": "jié（第二声）与 jiě（第三声）声调不同，意思是绳结或结束。", "接": "jiē（第一声）与 jiě（第三声）声调不同，意思是接住或接受。", "介": "jiè（第四声）与 jiě（第三声）声调不同，意思是介绍或介于之间。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指打开包裹上的带子，与“先”和“包裹上的带子”搭配，句子通顺。"}, {"text": "舔", "is_correct": false, "explanation": "语义：“舔”是用舌头接触，与打开带子的动作不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”用于清洁，不能说洗包裹上的带子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与包裹和带子无关。"}], "explanations": {"解": "“解”指打开包裹上的带子，与“先”和“包裹上的带子”搭配，句子通顺。", "舔": "语义：“舔”是用舌头接触，与打开带子的动作不符。", "洗": "搭配：“洗”用于清洁，不能说洗包裹上的带子。", "吃": "语义：“吃”指进食，与包裹和带子无关。"}, "sentence_index": 0, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈解开那碗汤，慢慢喝了下去。", "explanation": "这里应该用〈端〉。解开指打开捆着或合着的东西，碗里的汤不是这类东西，应说“端”。"}, {"text": "她解开橘子皮，递给我一瓣。", "explanation": "这里应该用〈剥〉。橘子皮包在果肉外面，去皮要用“剥”，不用“解开”。"}, {"text": "他解开那杯牛奶，喝了一口。", "explanation": "这里应该用〈倒〉。解开指打开捆着或合着的东西，杯中的牛奶不能用“解开”，应说“倒”出来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "解", "is_correct": true, "explanation": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。"}, {"text": "街", "is_correct": false, "explanation": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。"}, {"text": "戒", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。"}, {"text": "界", "is_correct": false, "explanation": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}], "explanations": {"解": "jiě（第三声）是正确答案，指把捆着或合着的东西打开、分开。", "节": "jié（第二声）与 jiě（第三声）声调不同，意思是节日或段落。", "街": "jiē（第一声）与 jiě（第三声）声调不同，意思是街道。", "戒": "jiè（第四声）与 jiě（第三声）声调不同，意思是戒除或戒指。", "界": "jiè（第四声）与 jiě（第三声）声调不同，意思是界限或界别。"}, "sentence_index": null, "correct_answer": "解"}, "level_3": {"options": [{"text": "解", "is_correct": true, "explanation": "“解”指打开礼物上的丝带，与“急着”和“礼物上的丝带”搭配，句子通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与丝带无关。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”用于烹饪食物，不能用于丝带。"}, {"text": "梳", "is_correct": false, "explanation": "搭配：“梳”多用于头发，不说梳礼物上的丝带。"}], "explanations": {"解": "“解”指打开礼物上的丝带，与“急着”和“礼物上的丝带”搭配，句子通顺。", "唱": "语义：“唱”指发出歌声，与丝带无关。", "煎": "语义：“煎”用于烹饪食物，不能用于丝带。", "梳": "搭配：“梳”多用于头发，不说梳礼物上的丝带。"}, "sentence_index": 6, "correct_answer": "解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈解了一锅粥，给全家人盛好。", "explanation": "这里应该用〈煮〉。解指打开或松开，不能表示烹饪，煮粥要用“煮”。"}, {"text": "这个小孩解了一杯果汁，一口气喝光了。", "explanation": "这里应该用〈端〉。解指打开或分开捆着、合着的东西，果汁不是这类东西，应说“端”。"}, {"text": "这道数学题他解了半天，终于解出来了。", "explanation": "这里的〈解〉是解答难题的意思，不是“打开或分开东西”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前解了过这条腰带。", "corrected_sentence": "他以前解过这条腰带。", "error_description": "错误：“解了过”；正确：“解过”。“过”表示曾经有过这样的经历，不能与表示完成的“了”同用，动词后只用“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她开解了红绳。", "corrected_sentence": "她解开了红绳。", "error_description": "错误：“开解”；正确：“解开”。“开”是结果补语，必须紧跟动词之后，应说“解开”，表示红绳被打开。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f83fa018-fb44-4669-a925-7706119e4f8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
