INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27613, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把商品、服务或事项捆在一起，使其不能分开。", "primary_collocate": null, "pronunciation": "bǎng dìng", "ipa": "pɑŋ˨˩ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "商店把牙刷和牙膏绑定在一起卖。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司把电话和网络绑定在一起。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个软件绑定销售，你不能只买一个。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个套餐绑定了手机和宽带。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想把工作和生活绑定在一起。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个项目绑定着，不能分开做。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商家常把便宜的东西和贵的东西绑定卖。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两门课绑定在一起，要一起选。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把我的奖金和销量绑定了。", "target_word": "绑定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这台机器时，服务也和它绑定在一起。", "target_word": "绑定", "complexity_tier": "T3", "furigana": "mǎi zhè tái jī qì shí, fú wù yě hé tā bǎng dìng zài yì qǐ.", "sentence_source": "generated"}], "morphological_forms": [{"form": "绑定了", "label": "体标（了）"}, {"form": "绑定过", "label": "体标（过）"}, {"form": "绑定着", "label": "体标（着）"}, {"form": "解绑", "label": "复合"}], "register": "中性", "sense_fingerprint": "把商品、服务或事项捆在一起，不能分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27613, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绑定", "is_correct": true, "explanation": "正确。“绑定在一起卖”表示把牙刷和牙膏捆在一起销售。"}, {"text": "分开", "is_correct": false, "explanation": "语义：“分开”与句中“在一起”相反，句子说的是捆在一起卖。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件或内容，不能说“打印在一起卖”。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能与“在一起卖”搭配，句子无法表达销售的意思。"}], "explanations": {"绑定": "正确。“绑定在一起卖”表示把牙刷和牙膏捆在一起销售。", "分开": "语义：“分开”与句中“在一起”相反，句子说的是捆在一起卖。", "打印": "搭配：“打印”的对象是文件或内容，不能说“打印在一起卖”。", "测量": "搭配：“测量”不能与“在一起卖”搭配，句子无法表达销售的意思。"}, "sentence_index": 0, "correct_answer": "绑定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条裙子绑定一条围巾很好看。", "explanation": "这里应该用〈搭配〉。搭配是挑选、配合衣物等，绑定强调固定地连成一体，衣物搭配不能说绑定。"}, {"text": "这根线绑定了电脑和显示器。", "explanation": "这里应该用〈连接〉。连接用于设备之间的接通，绑定用于商品或服务的捆绑，不能用于线路。"}, {"text": "他用绳子把两根木棍绑定在一起。", "explanation": "这里应该用〈绑〉。绑是用绳子等缠紧实物，绑定用于把商品、服务等结合在一起，说用绳子绑木棍时要用“绑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27613, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绑定", "is_correct": true, "explanation": "正确。“商家常把……绑定卖”表示把东西捆在一起销售。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”不能带“卖”作结果，“挑选卖”不成立。"}, {"text": "比较", "is_correct": false, "explanation": "语义：“比较”不是把东西组合起来的动作，与“常把……和……卖”的语境不符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是坏的物品，不能说“修理卖”。"}], "explanations": {"绑定": "正确。“商家常把……绑定卖”表示把东西捆在一起销售。", "挑选": "搭配：“挑选”不能带“卖”作结果，“挑选卖”不成立。", "比较": "语义：“比较”不是把东西组合起来的动作，与“常把……和……卖”的语境不符。", "修理": "搭配：“修理”的对象是坏的物品，不能说“修理卖”。"}, "sentence_index": 6, "correct_answer": "绑定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月会从卡里绑定十块钱。", "explanation": "这里应该用〈扣〉。扣是从账户里减去钱款，绑定指把两样东西连在一起，不能用来说从卡里扣款。"}, {"text": "我绑定了一张照片。", "explanation": "这里应该用〈拍〉。拍是用相机摄取影像，绑定指把东西连在一起，不能用来说拍照。"}, {"text": "这张桌子用螺丝绑定在墙上。", "explanation": "这里应该用〈固定〉。固定是用螺丝等把东西牢牢装在某处；绑定只用于把商品、服务或事项捆在一起，不说用螺丝装在墙上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27613, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店把洗发水和护发素被绑定在一起卖。", "corrected_sentence": "这家店把洗发水和护发素绑定在一起卖。", "error_description": "语法错误：“把”字句与“被”字句不能同时使用，“把”已标出宾语“洗发水和护发素”，“被”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27613, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两件商品还没绑定了在一起卖。", "corrected_sentence": "这两件商品还没绑定在一起卖。", "error_description": "错误：“还没绑定了在一起”；正确：“还没绑定在一起”。“没”否定时，动词后不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
