INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27618, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做最重要事情的人。", "primary_collocate": null, "pronunciation": "zhǔ dǎo zhě", "ipa": "tʂu˨˩ tɑʊ˨˩ tʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这件事的主导者是谁？", "target_word": "主导者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他是整个计划的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司里的主导者就是总经理。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的主导者是那位导演。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "主导者要对结果负责。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的主导者会听大家的意见。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她是这次改革的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是球队的主导者？", "target_word": "主导者", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个会议的主导者今天没有来。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要先找到这个计划的主导者。", "target_word": "主导者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "负责做最重要事情的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27618, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "主导者", "is_correct": true, "explanation": "正确：“这件事的主导者”指主持、推动这件事的人，与句意相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘车、乘船的人，与“这件事的”搭配不当，不能指事情的负责人。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”指做饭的人，与“这件事”无关，不能指事情的负责人。"}, {"text": "病人", "is_correct": false, "explanation": "语义：“病人”指接受治疗的人，与“这件事”无关。"}], "explanations": {"主导者": "正确：“这件事的主导者”指主持、推动这件事的人，与句意相符。", "乘客": "语义：“乘客”指乘车、乘船的人，与“这件事的”搭配不当，不能指事情的负责人。", "厨师": "语义：“厨师”指做饭的人，与“这件事”无关，不能指事情的负责人。", "病人": "语义：“病人”指接受治疗的人，与“这件事”无关。"}, "sentence_index": 0, "correct_answer": "主导者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场演唱会有很多主导者。", "explanation": "这里应该用〈观众〉。“主导者”指负责做最重要事情的人，看演唱会的人要说“观众”。"}, {"text": "这个车站里有很多主导者在偷东西。", "explanation": "这里应该用〈小偷〉。“主导者”指负责做最重要事情的人，偷东西的人要说“小偷”。"}, {"text": "这趟火车有很多主导者。", "explanation": "这里应该用〈乘客〉。“主导者”指负责做最重要事情的人，乘车的人要说“乘客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27618, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主导者", "is_correct": true, "explanation": "正确：“这次改革的主导者”指推动改革、起主要作用的人，句意相符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：“乘客”指乘车的人，与“改革”无关。"}, {"text": "考生", "is_correct": false, "explanation": "搭配：“考生”指参加考试的人，“改革的考生”搭配不当。"}, {"text": "嫌疑人", "is_correct": false, "explanation": "语义：“嫌疑人”指涉嫌犯罪的人，与推动改革的角色相悖。"}], "explanations": {"主导者": "正确：“这次改革的主导者”指推动改革、起主要作用的人，句意相符。", "乘客": "语义：“乘客”指乘车的人，与“改革”无关。", "考生": "搭配：“考生”指参加考试的人，“改革的考生”搭配不当。", "嫌疑人": "语义：“嫌疑人”指涉嫌犯罪的人，与推动改革的角色相悖。"}, "sentence_index": 6, "correct_answer": "主导者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这支球队的主导者每场比赛都坐在看台上大喊加油。", "explanation": "这里应该用〈球迷〉。“主导者”指负责做最重要事情的人，坐在看台上为球队加油的人要说“球迷”。"}, {"text": "这座景区有很多主导者。", "explanation": "这里应该用〈游客〉。“主导者”指负责做最重要事情的人，参观景区的人要说“游客”。"}, {"text": "这家医院里有很多主导者正在输液。", "explanation": "这里应该用〈病人〉。“主导者”指负责做最重要事情的人，接受输液治疗的人要说“病人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27618, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次改革有两辆主导者。", "corrected_sentence": "这次改革有两位主导者。", "error_description": "错误在量词：“辆”应改为“位”。“辆”用于车辆，“主导者”指人，应用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27618, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个计划有两件主导者。", "corrected_sentence": "这个计划有两位主导者。", "error_description": "错误在量词：“件”应改为“位”。“件”多用于物品、事情，“主导者”指人，应用“位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
