INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27622, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指涉是说一个词或一句话提到某个人或某个东西。", "primary_collocate": null, "pronunciation": "zhǐ shè", "ipa": "tʂʅ˨˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "“我”指涉说话的人。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话指涉的是你的朋友。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“它”在这句话里指涉那只小狗。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的“那个人”指涉谁？", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词指涉一种水果。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书名里的“他”指涉作者的父亲。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话没有指涉任何人。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子里的“这里”指涉我们的学校。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，“你们”指涉全班同学。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上的那句话指涉一个有名的歌手。", "target_word": "指涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指涉了", "label": "体标"}, {"form": "指涉过", "label": "体标"}], "register": "书面", "sense_fingerprint": "指涉：一个词或一句话提到某个人或某个东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指涉", "is_correct": true, "explanation": "正确：指涉指词语提到某人或某物，填入“我”____说话的人，句意通顺。"}, {"text": "消失", "is_correct": false, "explanation": "配价：消失是不及物动词，不能带“说话的人”作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指修补器物，与词语的指称无关。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：冷藏指低温保存食物等，与这句话的意思无关。"}], "explanations": {"指涉": "正确：指涉指词语提到某人或某物，填入“我”____说话的人，句意通顺。", "消失": "配价：消失是不及物动词，不能带“说话的人”作宾语。", "修理": "语义：修理指修补器物，与词语的指称无关。", "冷藏": "语义：冷藏指低温保存食物等，与这句话的意思无关。"}, "sentence_index": 0, "correct_answer": "指涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向大家指涉这位新同学。", "explanation": "这里应该用〈介绍〉。指涉指词语提到某人或某物，不表示向他人引见。"}, {"text": "孩子正在指涉积木。", "explanation": "这里应该用〈搭〉。指涉指词语提到某个对象，不表示用积木搭建东西。"}, {"text": "工人正在指涉电视。", "explanation": "这里应该用〈修理〉。指涉不表示修理器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指涉", "is_correct": true, "explanation": "正确：指涉指词语提到某人，填入“她的话没有____任何人”，句意通顺。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：吞下指咽进去，与话语是否提到人无关。"}, {"text": "修补", "is_correct": false, "explanation": "语义：修补指修复破损之物，不能用于话语。"}, {"text": "脱落", "is_correct": false, "explanation": "配价：脱落是不及物动词，不能带“任何人”作宾语。"}], "explanations": {"指涉": "正确：指涉指词语提到某人，填入“她的话没有____任何人”，句意通顺。", "吞下": "语义：吞下指咽进去，与话语是否提到人无关。", "修补": "语义：修补指修复破损之物，不能用于话语。", "脱落": "配价：脱落是不及物动词，不能带“任何人”作宾语。"}, "sentence_index": 6, "correct_answer": "指涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把箱子指涉进了仓库。", "explanation": "这里应该用〈搬运〉。指涉不表示搬动物体。"}, {"text": "妈妈在指涉衣服。", "explanation": "这里应该用〈洗〉。指涉不表示清洗衣物。"}, {"text": "厨师在指涉一锅汤。", "explanation": "这里应该用〈烧〉。指涉不表示烹煮食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你”指涉得听话的人。", "corrected_sentence": "“你”指涉听话的人。", "error_description": "多余的助词：“得”只能接在动词后作补语的标记，“指涉”后直接带宾语，不能加“得”。应说“指涉听话的人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个名字没有指涉了任何人。", "corrected_sentence": "这个名字没有指涉任何人。", "error_description": "体标误用：「没有」否定时不能与「了」共现，「指涉」后不应加「了」。应说「这个名字没有指涉任何人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
