INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27628, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "价值观就是你觉得什么重要、什么好。", "primary_collocate": null, "pronunciation": "jià zhí guān", "ipa": "tɕja˥˩ ʈʂɨ˧˥ kuan˥", "syllable_count": 3, "sentences": [{"text": "你的价值观是什么？", "target_word": "价值观", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "诚实是我最重要的价值观。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的价值观是把家人放在第一位。", "target_word": "价值观", "complexity_tier": "T3", "furigana": "tā de jiàzhíguān shì bǎ jiārén fàng zài dì yī wèi", "sentence_source": "generated"}, {"text": "朋友之间价值观差不多，聊天更轻松。", "target_word": "价值观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的价值观很简单：对人好。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一个人怎么花钱，能看出他的价值观。", "target_word": "价值观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的价值观让她选择了这份工作。", "target_word": "价值观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的价值观不一样，所以常常吵架。", "target_word": "价值观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书改变了我的价值观。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是按自己的价值观做事。", "target_word": "价值观", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人觉得什么重要、什么好的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '177778a7-0e89-45d6-9599-764796678496') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27628, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价值观", "is_correct": true, "explanation": "正确。问别人的“价值观是什么”指他觉得什么重要、什么好，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能用“你的……是什么”询问一个人觉得什么重要。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色指外表的色彩，不是个人觉得什么重要、什么好的想法，问人时不能这样说。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是具体物品，不能作为询问个人看法的对象，与句意不符。"}], "explanations": {"价值观": "正确。问别人的“价值观是什么”指他觉得什么重要、什么好，符合句意。", "天气": "语义：天气是自然现象，不能用“你的……是什么”询问一个人觉得什么重要。", "颜色": "体貌：颜色指外表的色彩，不是个人觉得什么重要、什么好的想法，问人时不能这样说。", "钥匙": "语义：钥匙是具体物品，不能作为询问个人看法的对象，与句意不符。"}, "sentence_index": 0, "correct_answer": "价值观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台冰箱的价值观在三千元左右。", "explanation": "这里应该用〈价位〉。说商品的价格区间要用价位，价值观指看法和评价标准，不能用来表示金额。"}, {"text": "他的价值观很工整。", "explanation": "这里应该用〈字迹〉。形容字写得整齐要用字迹，价值观指看法和评价标准，不能用“工整”来形容。"}, {"text": "这箱苹果的价值观是十元。", "explanation": "这里应该用〈单价〉。说每件商品的价钱要用单价，价值观指看法和评价标准，不能用来表示金额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27628, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价值观", "is_correct": true, "explanation": "正确。价值观是人的基本看法和标准，可以影响选择，符合“让她选择了这份工作”的语境。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李是携带的物品，不能让人作出选择工作的决定。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：鞋子不能作为促使人做决定的原因，说“鞋子让她选择了工作”不合理。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，没有影响人作出选择的作用，与句意不符。"}], "explanations": {"价值观": "正确。价值观是人的基本看法和标准，可以影响选择，符合“让她选择了这份工作”的语境。", "行李": "语义：行李是携带的物品，不能让人作出选择工作的决定。", "鞋子": "搭配：鞋子不能作为促使人做决定的原因，说“鞋子让她选择了工作”不合理。", "桌子": "语义：桌子是家具，没有影响人作出选择的作用，与句意不符。"}, "sentence_index": 6, "correct_answer": "价值观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子的价值观是每月三千元。", "explanation": "这里应该用〈租金〉。说房子每月要付的钱要用租金，价值观指看法和评价标准，不能用来表示金额。"}, {"text": "他为这次比赛花了很大的价值观。", "explanation": "这里应该用〈力气〉。花力气指付出努力，价值观是看法和标准，不能用来计量付出。"}, {"text": "他的价值观越来越多，已经够买房了。", "explanation": "这里应该用〈存款〉。存款是钱财，可以越来越多；价值观是看法标准，不能这样计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27628, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家人有一只独特的价值观。", "corrected_sentence": "这家人有一种独特的价值观。", "error_description": "量词错误：价值观是抽象概念，应使用量词“种”，不能用“只”。正确说法是“一种独特的价值观”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27628, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他有一套明确地价值观。", "corrected_sentence": "他有一套明确的价值观。", "error_description": "的地混用：“明确”修饰名词“价值观”时应用“的”，不能用“地”。正确说法是“明确的价值观”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cff5d6f-854d-4a1b-90fc-8c55125fdad8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
