INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27630, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己看自己心里想什么，看看自己做得对不对。", "primary_collocate": null, "pronunciation": "nèi xǐng", "ipa": "nei˥˩ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "做错事以后，要学会内省。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛，开始内省自己今天的表现。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，我该内省一下，为什么总迟到。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内省就是问问自己：我做得对吗？", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不内省，所以总犯同样的错。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡前内省十分钟，对我很有帮助。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生气了，我先内省了一下。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常内省，担心自己说错了话。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在河边，内省着这一年的得失。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子犯错后，老师让他回家好好内省。", "target_word": "内省", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "内省了", "label": "完成体"}, {"form": "内省着", "label": "持续体"}], "register": "书面", "sense_fingerprint": "自己想想心里的想法，检查自己做得对不对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内省", "is_correct": true, "explanation": "正确：“学会内省”指学会反思自己做错的原因，与“做错事以后”的语境吻合。"}, {"text": "长高", "is_correct": false, "explanation": "语义：“要学会长高”与“做错事以后”的语境毫不相干，句意荒谬。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“学会生病”不是可以学习的能力，与语境矛盾，句意荒谬。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要宾语（送什么、送给谁），单独放在空位里句子不完整。"}], "explanations": {"内省": "正确：“学会内省”指学会反思自己做错的原因，与“做错事以后”的语境吻合。", "长高": "语义：“要学会长高”与“做错事以后”的语境毫不相干，句意荒谬。", "生病": "语义：“学会生病”不是可以学习的能力，与语境矛盾，句意荒谬。", "送": "配价：“送”需要宾语（送什么、送给谁），单独放在空位里句子不完整。"}, "sentence_index": 0, "correct_answer": "内省"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天都内省家乡。", "explanation": "这里应该用〈思念〉。内省是对自己想法和行为的反思，不能用来表达对家乡的思念。"}, {"text": "老师内省这份卷子，找出了错误。", "explanation": "这里应该用〈检查〉。内省的对象是自己，不能用来指检查外面的卷子。"}, {"text": "妈妈每天都内省孩子。", "explanation": "这里应该用〈照顾〉。内省只指反思自己的内心，不能把别人当作对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内省", "is_correct": true, "explanation": "正确：朋友生气时自己先反思，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“我先吃了一下”与朋友生气的语境无关，句意荒谬。"}, {"text": "赠", "is_correct": false, "explanation": "配价：“赠”需要两个宾语（赠给谁、赠什么），单独放在空位里句子不完整。"}, {"text": "吐", "is_correct": false, "explanation": "语义：“我先吐了一下”与语境不符，句意荒谬。"}], "explanations": {"内省": "正确：朋友生气时自己先反思，符合语境。", "吃": "语义：“我先吃了一下”与朋友生气的语境无关，句意荒谬。", "赠": "配价：“赠”需要两个宾语（赠给谁、赠什么），单独放在空位里句子不完整。", "吐": "语义：“我先吐了一下”与语境不符，句意荒谬。"}, "sentence_index": 6, "correct_answer": "内省"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让他回家好好内省课文。", "explanation": "这里应该用〈背诵〉。内省针对自己的想法和行为，不能用于课文。"}, {"text": "老师让他回家好好内省钢琴。", "explanation": "这里应该用〈练习〉。内省只指对自己的反思，不能用于钢琴。"}, {"text": "老师让他回家好好内省自行车。", "explanation": "这里应该用〈修理〉。内省不能用来指对器物的处理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天内省了过自己的错误。", "corrected_sentence": "他昨天内省过自己的错误。", "error_description": "体标叠用错误：“了”与“过”不能同时用在同一动词之后，应去掉“了”，说“内省过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈生气了，我先把内省一下。", "corrected_sentence": "妈妈生气了，我先内省一下。", "error_description": "错误：多用了“把”。“内省”是不及物的反思动作，后面没有受处置的宾语，不能用“把”字句，应去掉“把”，说“我先内省一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
