INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27632, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情要遵守的规则。", "primary_collocate": null, "pronunciation": "zhǔn zé", "ipa": "tʂuən˨˩ tsɤ˧˥", "syllable_count": 2, "sentences": [{"text": "这个社团有自己的准则，大家都要遵守。", "target_word": "准则", "complexity_tier": "T3", "furigana": "zhǔn zé", "sentence_source": "generated"}, {"text": "这家工厂的安全准则写在墙上。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明忘了老师定的准则，被批评了。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有三条准则，第一条是准时。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做实验时，一定要按准则来做。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本手册里写了员工的工作准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队的准则很简单：不迟到，不放弃。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你先看一下网上聊天的准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来不违反家里的准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学要先学习学校的准则。", "target_word": "准则", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "安全准则", "label": "复合"}, {"form": "準則", "label": "繁体"}], "register": "书面", "sense_fingerprint": "准则：做事时必须遵守的规则、规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27632, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准则", "is_correct": true, "explanation": "正确：准则指做事时必须遵守的规则，与“遵守”搭配，句意通顺。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“遵守”的对象应是规则，不能说遵守节目。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“遵守”不能搭配名片，名片是交换身份信息的卡片。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是物体的色彩，不能被遵守。"}], "explanations": {"准则": "正确：准则指做事时必须遵守的规则，与“遵守”搭配，句意通顺。", "节目": "搭配：“遵守”的对象应是规则，不能说遵守节目。", "名片": "搭配：“遵守”不能搭配名片，名片是交换身份信息的卡片。", "颜色": "语义：颜色是物体的色彩，不能被遵守。"}, "sentence_index": 0, "correct_answer": "准则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天的准则很满。", "explanation": "这里应该用〈行程〉。准则指做事应遵守的规则，不指时间安排或日程。"}, {"text": "这块蛋糕的准则很甜。", "explanation": "这里应该用〈味道〉。准则指做事应遵守的规则，不用来描述食物的味道。"}, {"text": "这种螺丝的准则尺寸是五毫米。", "explanation": "这里应该用〈标准〉。准则是做事应遵守的规则，不用作可测量的尺寸标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27632, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准则", "is_correct": true, "explanation": "正确：准则指做事时必须遵守的规则，“很简单：不迟到，不放弃”正是规则的内容。"}, {"text": "球衣", "is_correct": false, "explanation": "语义：球衣是队员穿的服装，不是规则，不能是“不迟到，不放弃”。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高描述身体特征，不能作为球队的规则内容。"}, {"text": "比分", "is_correct": false, "explanation": "语义：比分是比赛的结果，与规则无关。"}], "explanations": {"准则": "正确：准则指做事时必须遵守的规则，“很简单：不迟到，不放弃”正是规则的内容。", "球衣": "语义：球衣是队员穿的服装，不是规则，不能是“不迟到，不放弃”。", "身高": "体貌：身高描述身体特征，不能作为球队的规则内容。", "比分": "语义：比分是比赛的结果，与规则无关。"}, "sentence_index": 6, "correct_answer": "准则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拿着准则找路。", "explanation": "这里应该用〈地图〉。准则是做事应遵守的规则，不能用来找路。"}, {"text": "服务员递来一碗准则。", "explanation": "这里应该用〈汤〉。准则指规则，不能盛在碗里端上来。"}, {"text": "他照着准则弹钢琴。", "explanation": "这里应该用〈乐谱〉。准则指言行的原则，不能用来照着弹奏乐曲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂有三件安全准则。", "corrected_sentence": "这家工厂有三条安全准则。", "error_description": "量词错误：“件”用于衣物、事情等，准则应用“条”或“项”计数，应说“三条安全准则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班定了一根准则。", "corrected_sentence": "这个班定了一条准则。", "error_description": "量词错误：“根”用于细长的条状物，准则应用“条”计数，应说“定了一条准则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
