INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27636, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像人一样的；不是真人。", "primary_collocate": null, "pronunciation": "lèi rén", "ipa": "lei˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "电影里有一个类人的外星生物。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个类人机器人能和客人聊天。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "它不是真人，只是一个类人的玩偶。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店门口站着一个类人机器人。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个类人角色看起来像真人，其实是电脑做的。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们造了类人的机器，用来照顾老人。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "类人的声音让我以为是真人在说话。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的类人机器人会搬箱子。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个类人的脸很像人，但不是真人。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很喜欢这个会唱歌的类人机器人。", "target_word": "类人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "类人的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "像人一样但不是真人的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f37998e-cef0-48d6-bb96-36f60a03b191') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27636, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人形容像人但不是真人的事物，符合“类人的外星生物”。"}, {"text": "食用", "is_correct": false, "explanation": "语义：食用指可以吃，外星生物不能用“食用”来形容。"}, {"text": "可燃", "is_correct": false, "explanation": "语义：可燃指能燃烧，与生物的意思不符。"}, {"text": "油炸", "is_correct": false, "explanation": "语义：油炸是食物的烹饪方式，外星生物不能用“油炸”来形容，句意荒谬。"}], "explanations": {"类人": "正确：类人形容像人但不是真人的事物，符合“类人的外星生物”。", "食用": "语义：食用指可以吃，外星生物不能用“食用”来形容。", "可燃": "语义：可燃指能燃烧，与生物的意思不符。", "油炸": "语义：油炸是食物的烹饪方式，外星生物不能用“油炸”来形容，句意荒谬。"}, "sentence_index": 0, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的邻居是一位类人的老人。", "explanation": "这里的类人指像人但不是真人的事物，不能用来形容真正的人。"}, {"text": "这个玩具是类人的小狗。", "explanation": "这里应该用〈仿真〉。类人强调像人，不用于形容动物。"}, {"text": "书架上放着一本类人的书。", "explanation": "这里应该用〈纸质〉。类人只描述像人的事物，不说明材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27636, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "类人", "is_correct": true, "explanation": "正确：类人形容像人的声音，让人误以为是真人在说话。"}, {"text": "木质", "is_correct": false, "explanation": "语义：木质指材料，与声音的意思不符。"}, {"text": "陶瓷", "is_correct": false, "explanation": "语义：陶瓷指材料，与声音的意思不符。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：颜色词不修饰声音，不说红色的声音。"}], "explanations": {"类人": "正确：类人形容像人的声音，让人误以为是真人在说话。", "木质": "语义：木质指材料，与声音的意思不符。", "陶瓷": "语义：陶瓷指材料，与声音的意思不符。", "红色": "搭配：颜色词不修饰声音，不说红色的声音。"}, "sentence_index": 6, "correct_answer": "类人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一台类人的洗衣机。", "explanation": "这里应该用〈电动〉。类人强调像人，不描述机器的动力方式。"}, {"text": "这块皮革是类人的，不是真皮。", "explanation": "这里应该用〈人造〉。人造指人工制成的材料，类人只说像人的事物，不用于描述材料。"}, {"text": "这种类人的机器鱼能在水里游。", "explanation": "这里应该用〈仿生〉。仿生指模仿生物的构造，类人指像人一样的事物，不能用来模仿鱼类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27636, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "展厅里有一个类人地机器人在迎接客人。", "corrected_sentence": "展厅里有一个类人的机器人在迎接客人。", "error_description": "错误：定语标记用错。类人修饰名词“机器人”，应用“的”，不用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27636, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站门口站着一个类人地机器人在打招呼。", "corrected_sentence": "车站门口站着一个类人的机器人在打招呼。", "error_description": "错误：定语标记用错。“类人”修饰名词“机器人”，应用“的”，不能用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9524ef72-b2b9-4d61-8737-9346f19388ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
