INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人类就是所有男男女女老老少少的人。", "primary_collocate": null, "pronunciation": "rén lèi", "ipa": "ʐən˧˥ lei˥˩", "syllable_count": 2, "sentences": [{"text": "人类需要空气、水和食物。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类已经去过月球。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护环境对人类都有好处。", "target_word": "人类", "complexity_tier": "T3", "furigana": "bǎohù huánjìng duì rénlèi dōu yǒu hǎochu", "sentence_source": "generated"}, {"text": "很久以前，人类住在山洞里。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗是人类最好的朋友。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类的历史有几千年。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学让人类的生活越来越方便。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病曾经给人类带来很大的麻烦。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人类和动物都需要睡觉。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想了解人类是怎么出现的。", "target_word": "人类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "全人类", "label": "复合"}, {"form": "人类学", "label": "复合"}, {"form": "人類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "作为整体的所有人，与动物相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”不需要吃喝，“需要空气、水和食物”不能用来描述汽车。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不需要空气、水和食物，这样描述不通。"}, {"text": "人类", "is_correct": true, "explanation": "“人类”是有生命的群体，需要空气、水和食物，与句意相合。"}, {"text": "理想", "is_correct": false, "explanation": "搭配：“理想”是抽象概念，不能说“理想需要空气、水和食物”。"}], "explanations": {"汽车": "语义：“汽车”不需要吃喝，“需要空气、水和食物”不能用来描述汽车。", "石头": "语义：“石头”不需要空气、水和食物，这样描述不通。", "人类": "“人类”是有生命的群体，需要空气、水和食物，与句意相合。", "理想": "搭配：“理想”是抽象概念，不能说“理想需要空气、水和食物”。"}, "sentence_index": 0, "correct_answer": "人类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人类是国家的主人。", "explanation": "这里应该用〈人民〉。国家的主人指国民，要说“人民”；“人类”指整个人类，不指一国的国民。"}, {"text": "这辆车里坐着三个人类。", "explanation": "这里应该用〈人〉。“人类”是全体人的总称，不能和具体数量“三个”搭配。"}, {"text": "街上人类很多。", "explanation": "这里应该用〈人群〉。“人类”指整个人类，不是街上具体的一群人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”没有“生活”，“科学让窗户的生活越来越方便”不通。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“生活”的主体应是有生命的人或动物，“钢铁的生活”不能说。"}, {"text": "人类", "is_correct": true, "explanation": "“人类”是有生活的群体，科学使其生活便利，与句意相合。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”不是生活的主体，句子的意思不成立。"}], "explanations": {"窗户": "语义：“窗户”没有“生活”，“科学让窗户的生活越来越方便”不通。", "钢铁": "搭配：“生活”的主体应是有生命的人或动物，“钢铁的生活”不能说。", "人类": "“人类”是有生活的群体，科学使其生活便利，与句意相合。", "桌子": "语义：“桌子”不是生活的主体，句子的意思不成立。"}, "sentence_index": 6, "correct_answer": "人类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们是中华人类的一员。", "explanation": "这里应该用〈民族〉。“人类”指全体人类，不能用来指某个民族。"}, {"text": "中国人类很多，超过了十亿。", "explanation": "这里应该用〈人口〉。“人类”是全体，不能用来统计某国的人数；统计人数要说“人口”。"}, {"text": "国家需要大量人类。", "explanation": "这里应该用〈人才〉。“人类”指全体人，不能用来指有能力、有专长的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家帮助人类们治好了许多疾病。", "corrected_sentence": "科学家帮助人类治好了许多疾病。", "error_description": "错误：“人类”后加了复数标记“们”。正确：“人类”本身是总称，不能再加“们”，应为“帮助人类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "科学家们正在研究人类的的起源。", "corrected_sentence": "科学家们正在研究人类的起源。", "error_description": "错误：“人类”后多加了一个“的”，写成“人类的的起源”。正确：“人类的起源”，“的”只用一个，连接定语“人类”和中心语“起源”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27650, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加与排除意思相反：一个是加入，一个是去除。"}, {"text": "观察", "is_correct": false, "explanation": "观察与排除没有反义关系，二者意思无关。"}, {"text": "购买", "is_correct": false, "explanation": "购买与排除没有反义关系，二者意思无关。"}, {"text": "演奏", "is_correct": false, "explanation": "演奏与排除没有反义关系，二者意思无关。"}], "correct_answer": "添加", "explanations": {"添加": "添加与排除意思相反：一个是加入，一个是去除。", "观察": "观察与排除没有反义关系，二者意思无关。", "购买": "购买与排除没有反义关系，二者意思无关。", "演奏": "演奏与排除没有反义关系，二者意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f50ad900-16d3-4117-a66b-17b60f4ca301') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
