INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27652, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "表示数量太多，做不完、吃不完或用不完。", "primary_collocate": null, "pronunciation": "bù liǎo", "ipa": "pu˥˩ liɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这么多菜，我一个人吃不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些钱太多了，一辈子也花不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些米太多，我们一家人一年也吃不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的故事太长，一晚上也讲不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书太多了，一个月也看不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些衣服很多，我这辈子都穿不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这一大袋土豆太多，我一周也吃不了。", "target_word": "不了", "complexity_tier": "T3", "furigana": "zhè yí dà dài tǔdòu tài duō, wǒ yì zhōu yě chī bù liǎo。", "sentence_source": "generated"}, {"text": "今天的工作太多，我一个人干不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个话题有意思，我们聊三天也聊不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些纸很多，我们用一年也用不了。", "target_word": "不了", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "得了", "label": "肯定式"}], "register": "口语", "sense_fingerprint": "动词后的可能补语，表示数量太多而做不完、吃不完", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83f95e5d-4e87-424f-8121-0527036d276a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不了", "is_correct": true, "explanation": "不了（bù liǎo）：表示数量太多而做不完、用不完，是正确答案。"}, {"text": "不少", "is_correct": false, "explanation": "第一音节声母 l 与 sh 不同，声调相同（第三声）；意思是数量多。"}, {"text": "不好", "is_correct": false, "explanation": "第二音节声母 l 与 h 不同，声调相同（第三声）；意思是不好。"}, {"text": "不料", "is_correct": false, "explanation": "韵母相同，第二音节声调不同（第四声）；意思是没想到。"}], "explanations": {"不了": "不了（bù liǎo）：表示数量太多而做不完、用不完，是正确答案。", "不少": "第一音节声母 l 与 sh 不同，声调相同（第三声）；意思是数量多。", "不好": "第二音节声母 l 与 h 不同，声调相同（第三声）；意思是不好。", "不料": "韵母相同，第二音节声调不同（第四声）；意思是没想到。"}, "sentence_index": null, "correct_answer": "不了"}, "level_3": {"options": [{"text": "不了", "is_correct": true, "explanation": "正确。“吃不了”表示量太大，一个人吃不完。"}, {"text": "不起", "is_correct": false, "explanation": "语义：“吃不起”说的是没有钱买，与“菜多”的语境不符。"}, {"text": "不惯", "is_correct": false, "explanation": "语义：“吃不惯”说的是不习惯某种食物，与菜多无关。"}, {"text": "不上", "is_correct": false, "explanation": "搭配：“吃不上”多用于没有东西吃的情况，与“这么多菜”矛盾。"}], "explanations": {"不了": "正确。“吃不了”表示量太大，一个人吃不完。", "不起": "语义：“吃不起”说的是没有钱买，与“菜多”的语境不符。", "不惯": "语义：“吃不惯”说的是不习惯某种食物，与菜多无关。", "不上": "搭配：“吃不上”多用于没有东西吃的情况，与“这么多菜”矛盾。"}, "sentence_index": 0, "correct_answer": "不了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些书太少了，我一个星期也看不了。", "explanation": "这里应该用〈看完〉。“不了”表示东西太多、做不完，书很少时不能这样说。"}, {"text": "这碗饭只有一小口，我一个人也吃不了。", "explanation": "这里应该用〈吃完〉。“吃不了”表示东西太多、吃不完，一小口的饭不能这样说。"}, {"text": "这张纸只有一页，我们用一年也用不了。", "explanation": "这里应该用〈用完〉。“用不了”表示东西太多、用不完，只有一页时不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27652, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不了", "is_correct": true, "explanation": "不了（bù liǎo）：表示数量太多而做不完、用不完，是正确答案。"}, {"text": "布料", "is_correct": false, "explanation": "韵母相同，第二音节声调不同（第四声）；意思是做衣服的材料。"}, {"text": "不聊", "is_correct": false, "explanation": "第二音节声调不同（第二声），其余相同；意思是不闲谈。"}, {"text": "不老", "is_correct": false, "explanation": "韵母少了 i 介音（iao 与 ao），声调相同（第三声）；意思是不显老。"}], "explanations": {"不了": "不了（bù liǎo）：表示数量太多而做不完、用不完，是正确答案。", "布料": "韵母相同，第二音节声调不同（第四声）；意思是做衣服的材料。", "不聊": "第二音节声调不同（第二声），其余相同；意思是不闲谈。", "不老": "韵母少了 i 介音（iao 与 ao），声调相同（第三声）；意思是不显老。"}, "sentence_index": null, "correct_answer": "不了"}, "level_3": {"options": [{"text": "不了", "is_correct": true, "explanation": "正确。“吃不了”表示量太大，一周也吃不完。"}, {"text": "不着", "is_correct": false, "explanation": "语义：“吃不着”说的是没有机会吃到，与土豆太多的语境矛盾。"}, {"text": "不准", "is_correct": false, "explanation": "语义：“吃不准”指拿不准，与吃的数量无关。"}, {"text": "不透", "is_correct": false, "explanation": "搭配：“吃透”多用于理解或精神层面，不用于说吃土豆。"}], "explanations": {"不了": "正确。“吃不了”表示量太大，一周也吃不完。", "不着": "语义：“吃不着”说的是没有机会吃到，与土豆太多的语境矛盾。", "不准": "语义：“吃不准”指拿不准，与吃的数量无关。", "不透": "搭配：“吃透”多用于理解或精神层面，不用于说吃土豆。"}, "sentence_index": 6, "correct_answer": "不了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个面包很小，我一个人吃十年也吃不了。", "explanation": "这里应该用〈吃完〉。“吃不了”表示东西太多、吃不完，面包这么小时不能这样说。"}, {"text": "这杯水只有半杯，我一天也喝不了。", "explanation": "这里应该用〈喝完〉。“喝不了”表示东西太多、喝不完，半杯水时不能这样说。"}, {"text": "这些钱只有十块，我一辈子也花不了。", "explanation": "这里应该用〈花完〉。“花不了”表示东西太多、花不完，只有十块钱时不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么大的一个西瓜，我一个人吃了不了。", "corrected_sentence": "这么大的一个西瓜，我一个人吃不了。", "error_description": "“不了”是可能补语，“吃”与“不了”之间不能插入“了”，应说“吃不了”，不能说“吃了不了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一箱苹果太多，我一个星期也吃不了完。", "corrected_sentence": "这一箱苹果太多，我一个星期也吃不了。", "error_description": "“吃不了”中的“不了”本身已表示“吃不完”，后面不能再加结果补语“完”。写作：这一箱苹果太多，我一个星期也吃不了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77416edf-e61e-487e-9a2a-45ffe72e9712') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
