INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (27658, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像火或太阳一样的颜色。", "primary_collocate": null, "pronunciation": "hóng", "ipa": "xʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "傍晚的太阳又大又红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳升起来了，天边红了一片。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夕阳把天空照得很红。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火很大，火苗红得耀眼。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯红得像小太阳。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山后的太阳慢慢变红了。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天边的云很红，明天会是好天气。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篝火烧得很红，大家围着它唱歌。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的太阳红红的，像一个大盘子。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山的时候，海面也变红了。", "target_word": "红", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "紅", "label": "繁体"}, {"form": "红红", "label": "重叠"}, {"form": "通红", "label": "复合"}], "register": "中性", "sense_fingerprint": "像火或太阳的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee9bb47-a98c-44f8-aee4-2ec290e9d84e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
